def _launch_quote_task9_windows_argument(value: str) -> str:
    if type(value) is not str or any(
        character == "\x00" or 0xD800 <= ord(character) <= 0xDFFF
        for character in value
    ):
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    if value and not any(character in '" \t' for character in value):
        return value
    rendered = ['"']
    backslashes = 0
    for character in value:
        if character == "\\":
            backslashes += 1
        elif character == '"':
            rendered.append("\\" * (2 * backslashes + 1))
            rendered.append('"')
            backslashes = 0
        else:
            rendered.append("\\" * backslashes)
            rendered.append(character)
            backslashes = 0
    rendered.append("\\" * (2 * backslashes))
    rendered.append('"')
    return "".join(rendered)


