def _guarded_sys_path_roles_are_valid(
    startup_roles: object,
    base_roles: object,
) -> bool:
    if (
        type(startup_roles) is not tuple
        or type(base_roles) is not tuple
        or len(startup_roles) < 2
        or any(type(role) is not str for role in startup_roles)
        or any(type(role) is not str for role in base_roles)
        or startup_roles[0] != "python_home"
        or startup_roles[-1] != "runtime_site"
        or base_roles != startup_roles[:-1]
    ):
        return False
    optional_roles = startup_roles[1:-1]
    return optional_roles == tuple(
        role for role in _GUARDED_OPTIONAL_STDLIB_ROLES if role in optional_roles
    )


def _reject(code: str) -> NoReturn:
    raise RuntimeError(code)


def _is_sha256(value: object) -> bool:
    return type(value) is str and _SHA256.fullmatch(value) is not None


def _canonical_json_bytes(value: object) -> bytes:
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8", errors="strict")
    except (UnicodeError, TypeError, ValueError):
        _reject(CLIENT_LAUNCH_INPUT_INVALID)


