def _valid_absolute_path(value: object) -> bool:
    if (
        type(value) is not str
        or not value
        or len(value) > _MAX_PATH_CHARS
        or any(character in value for character in ("\x00", "\r", "\n"))
    ):
        return False
    try:
        return Path(value).is_absolute()
    except (OSError, ValueError):
        return False


def _identity_record(identity: FilesystemObjectIdentity) -> dict[str, int]:
    return {
        "device": identity.device,
        "file_type": identity.file_type,
        "inode": identity.inode,
        "link_count": identity.link_count,
        "reparse_tag": identity.reparse_tag,
    }


def _validate_plain_identity(
    identity: object,
    *,
    code: str,
) -> FilesystemObjectIdentity:
    if type(identity) is not FilesystemObjectIdentity:
        _reject(code)
    try:
        identity.__post_init__()
    except Exception as exc:
        raise RuntimeError(code) from exc
    if (
        identity.file_type != 1
        or identity.reparse_tag != 0
        or identity.link_count != 1
    ):
        _reject(code)
    return identity


def _copy_identity(identity: FilesystemObjectIdentity) -> FilesystemObjectIdentity:
    _validate_plain_identity(identity, code=FILE_CHANGE_PATH_UNSAFE)
    return FilesystemObjectIdentity(
        device=identity.device,
        inode=identity.inode,
        file_type=identity.file_type,
        reparse_tag=identity.reparse_tag,
        link_count=identity.link_count,
    )


def _entry_record(entry: FilesystemSnapshotEntry) -> dict[str, object]:
    return {
        "identity": _identity_record(entry.identity),
        "kind": entry.kind,
        "link_count": entry.link_count,
        "relative_path": entry.relative_path,
        "sha256": entry.sha256,
        "size": entry.size,
    }


def _snapshot_record(snapshot: FilesystemRootSnapshot) -> dict[str, object]:
    return {
        "ancestor_identities": [
            _identity_record(identity) for identity in snapshot.ancestor_identities
        ],
        "entries": [_entry_record(entry) for entry in snapshot.entries],
        "manifest_sha256": snapshot.manifest_sha256,
        "present": snapshot.present,
        "relative_root": snapshot.relative_root,
        "root_identity": (
            None
            if snapshot.root_identity is None
            else _identity_record(snapshot.root_identity)
        ),
        "root_index": snapshot.root_index,
    }


def _copy_snapshot(snapshot: object) -> FilesystemRootSnapshot:
    if type(snapshot) is not FilesystemRootSnapshot:
        _reject(FILE_CHANGE_PATH_UNSAFE)
    try:
        snapshot.__post_init__()
        entries = tuple(
            FilesystemSnapshotEntry(
                relative_path=entry.relative_path,
                kind=entry.kind,
                size=entry.size,
                sha256=entry.sha256,
                link_count=entry.link_count,
                identity=_copy_identity(entry.identity),
            )
            for entry in snapshot.entries
        )
        root_identity = (
            None
            if snapshot.root_identity is None
            else _copy_identity(snapshot.root_identity)
        )
        ancestors = tuple(
            _copy_identity(identity) for identity in snapshot.ancestor_identities
        )
        return FilesystemRootSnapshot(
            root_index=snapshot.root_index,
            relative_root=snapshot.relative_root,
            present=snapshot.present,
            root_identity=root_identity,
            ancestor_identities=ancestors,
            entries=entries,
            manifest_sha256=snapshot.manifest_sha256,
        )
    except RuntimeError as exc:
        if str(exc) in {
            FILE_CHANGE_PATH_UNSAFE,
            FILE_CHANGE_CONTENT_INVALID,
        }:
            raise
        raise RuntimeError(FILE_CHANGE_PATH_UNSAFE) from exc
    except Exception as exc:
        raise RuntimeError(FILE_CHANGE_PATH_UNSAFE) from exc


@dataclass(frozen=True)
class _ValidatorZipMember:
    name: str
    size: int
    compressed_size: int
    crc32: int
    sha256: str


@dataclass(frozen=True)
class _ValidatorWheelPlan:
    members: tuple[_ValidatorZipMember, ...]
    expected_paths: tuple[str, ...]


@dataclass(frozen=True)
class _ValidatorCreatedObject:
    path: str
    parent_identity: FilesystemObjectIdentity
    kind: Literal["file", "directory"]
    identity: FilesystemObjectIdentity
    size: int | None
    sha256: str | None

    def __post_init__(self) -> None:
        try:
            canonical = _validator_absolute_path(Path(self.path), output=True)
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            raise RuntimeError(VALIDATOR_BUNDLE_INVALID) from exc
        if (
            str(canonical) != self.path
            or type(self.parent_identity) is not FilesystemObjectIdentity
            or type(self.identity) is not FilesystemObjectIdentity
            or self.kind not in {"file", "directory"}
        ):
            _validator_reject()
        _validate_plain_identity(
            self.parent_identity,
            code=VALIDATOR_BUNDLE_INVALID,
        )
        _validate_plain_identity(self.identity, code=VALIDATOR_BUNDLE_INVALID)
        if self.kind == "directory":
            if self.size is not None or self.sha256 is not None:
                _validator_reject()
        elif not (
            (self.size is None and self.sha256 is None)
            or (
                type(self.size) is int
                and self.size >= 0
                and _is_sha256(self.sha256)
            )
        ):
            _validator_reject()


def _validator_reject(exc: BaseException | None = None) -> NoReturn:
    if exc is None:
        raise RuntimeError(VALIDATOR_BUNDLE_INVALID)
    raise RuntimeError(VALIDATOR_BUNDLE_INVALID) from exc


def _validator_absolute_path(value: object, *, output: bool = False) -> Path:
    if not isinstance(value, Path):
        _validator_reject()
    raw = str(value)
    try:
        normalized = command_plan._normalize_namespace_root(raw)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        _validator_reject(exc)
    if raw.replace("/", "\\") != normalized:
        _validator_reject()
    path = Path(normalized)
    if output:
        try:
            for component in PureWindowsPath(normalized).parts[1:]:
                _validator_win32_component_key(component)
        except (RuntimeError, UnicodeError, ValueError) as exc:
            _validator_reject(exc)
        tmp_root = ntpath.normpath(r"D:\tmp")
        try:
            common = ntpath.commonpath((tmp_root, normalized))
        except ValueError:
            _validator_reject()
        if ntpath.normcase(common) != ntpath.normcase(tmp_root):
            _validator_reject()
    return path


def _validator_plain_file_identity(path: Path) -> FilesystemObjectIdentity:
    try:
        metadata = path.lstat()
        if (
            not stat.S_ISREG(metadata.st_mode)
            or preparation._is_link_or_reparse(path)
        ):
            _validator_reject()
        parent_identity, _parent_ancestors = preparation._observe_plain_directory(
            path.parent
        )
        identity = preparation._policy_identity(
            metadata,
            namespace_device=parent_identity.device,
        )
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)
    if (
        identity.file_type != 1
        or identity.reparse_tag != 0
        or identity.link_count != 1
    ):
        _validator_reject()
    return identity


def _validator_plain_directory_identity(path: Path) -> FilesystemObjectIdentity:
    try:
        preparation._require_plain_directory(path, label="validator directory")
        identity, _ancestors = preparation._observe_plain_directory(path)
    except BaseException as exc:
        _validator_reject(exc)
    if (
        identity.file_type != 1
        or identity.reparse_tag != 0
        or identity.link_count != 1
    ):
        _validator_reject()
    return identity


def _validator_capture_plain_file(
    path: Path,
    *,
    max_bytes: int,
) -> tuple[bytes, FilesystemObjectIdentity]:
    try:
        parent_identity_before = _validator_plain_directory_identity(path.parent)
        _observed_parent, parent_ancestors = preparation._observe_plain_directory(
            path.parent
        )
        if _observed_parent != parent_identity_before:
            _validator_reject()
        identity_before = _validator_plain_file_identity(path)
        payload = file_change_policy._stable_read_regular_file(
            path,
            max_bytes=max_bytes,
            code=VALIDATOR_BUNDLE_INVALID,
            expected_identity=identity_before,
            expected_parent_identities=(*parent_ancestors, parent_identity_before),
        )
        identity_after = _validator_plain_file_identity(path)
        parent_identity_after = _validator_plain_directory_identity(path.parent)
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)
    if (
        identity_after != identity_before
        or parent_identity_after != parent_identity_before
        or len(payload) > max_bytes
    ):
        _validator_reject()
    return payload, _copy_identity(identity_before)


def _validator_revalidate_plain_file(
    path: Path,
    *,
    expected_content: bytes,
    expected_identity: FilesystemObjectIdentity,
    max_bytes: int,
) -> None:
    content, identity = _validator_capture_plain_file(path, max_bytes=max_bytes)
    if content != expected_content or identity != expected_identity:
        _validator_reject()


def _validator_raw_zip_names(payload: bytes) -> tuple[str, ...]:
    eocd_signature = b"PK\x05\x06"
    central_signature = b"PK\x01\x02"
    local_signature = b"PK\x03\x04"
    eocd_offset = payload.rfind(
        eocd_signature,
        max(0, len(payload) - (65_535 + 22)),
    )
    try:
        if eocd_offset < 0 or eocd_offset + 22 > len(payload):
            _validator_reject()
        (
            signature,
            disk_number,
            central_disk,
            disk_entries,
            total_entries,
            central_size,
            central_offset,
            comment_length,
        ) = struct.unpack_from("<4s4H2LH", payload, eocd_offset)
        if (
            signature != eocd_signature
            or disk_number != 0
            or central_disk != 0
            or disk_entries != total_entries
            or total_entries < 1
            or total_entries > _VALIDATOR_ZIP_MEMBER_CAP
            or eocd_offset + 22 + comment_length != len(payload)
            or central_offset + central_size != eocd_offset
        ):
            _validator_reject()
        position = central_offset
        names: list[str] = []
        for _index in range(total_entries):
            if position + 46 > eocd_offset:
                _validator_reject()
            fields = struct.unpack_from("<4s6H3L5H2L", payload, position)
            if fields[0] != central_signature:
                _validator_reject()
            flags = fields[3]
            filename_length = fields[10]
            extra_length = fields[11]
            entry_comment_length = fields[12]
            local_offset = fields[16]
            name_start = position + 46
            name_end = name_start + filename_length
            entry_end = name_end + extra_length + entry_comment_length
            if name_end > entry_end or entry_end > eocd_offset:
                _validator_reject()
            raw_name = payload[name_start:name_end]
            encoding = "utf-8" if flags & 0x800 else "cp437"
            name = raw_name.decode(encoding, errors="strict")
            if (
                not raw_name
                or any(character in name for character in ("\\", "\x00", "\r", "\n"))
                or local_offset + 30 > central_offset
                or payload[local_offset : local_offset + 4] != local_signature
            ):
                _validator_reject()
            local_filename_length, local_extra_length = struct.unpack_from(
                "<HH",
                payload,
                local_offset + 26,
            )
            local_name_start = local_offset + 30
            local_name_end = local_name_start + local_filename_length
            if (
                local_name_end + local_extra_length > central_offset
                or payload[local_name_start:local_name_end] != raw_name
            ):
                _validator_reject()
            names.append(name)
            position = entry_end
        if position != eocd_offset:
            _validator_reject()
        return tuple(names)
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)


def _validator_win32_component_key(component: str) -> str:
    try:
        utf16_units = len(component.encode("utf-16-le", errors="strict")) // 2
    except UnicodeEncodeError as exc:
        _validator_reject(exc)
    forbidden = '<>:"\\|?*'
    device_stem = component.split(".", 1)[0].rstrip(" .").casefold()
    reserved = {
        "aux",
        "clock$",
        "con",
        "conin$",
        "conout$",
        "nul",
        "prn",
        *(f"com{index}" for index in range(1, 10)),
        *(f"lpt{index}" for index in range(1, 10)),
    }
    if (
        not component
        or component in (".", "..")
        or utf16_units > 255
        or component.endswith((".", " "))
        or any(ord(character) < 0x20 for character in component)
        or any(character in forbidden for character in component)
        or device_stem in reserved
    ):
        _validator_reject()
    return component.casefold()


def _validator_preflight_wheel(payload: bytes) -> _ValidatorWheelPlan:
    try:
        raw_names = _validator_raw_zip_names(payload)
        with zipfile.ZipFile(io.BytesIO(payload), mode="r") as archive:
            infos = archive.infolist()
            if (
                not infos
                or len(infos) > _VALIDATOR_ZIP_MEMBER_CAP
                or tuple(info.orig_filename for info in infos) != raw_names
            ):
                _validator_reject()
            names: set[str] = set()
            nodes: dict[
                tuple[str, ...],
                tuple[tuple[str, ...], Literal["file", "directory"]],
            ] = {}
            declared_total = 0
            actual_total = 0
            members: list[_ValidatorZipMember] = []
            for info in infos:
                name = info.filename
                original_name = info.orig_filename
                segments = name.split("/")
                unix_mode = (info.external_attr >> 16) & 0xFFFF
                unix_kind = stat.S_IFMT(unix_mode)
                if (
                    type(name) is not str
                    or original_name != name
                    or not name
                    or len(name) > _MAX_PATH_CHARS
                    or any(character in name for character in ("\\", "\x00", "\r", "\n"))
                    or name.startswith("/")
                    or re.match(r"^[A-Za-z]:", name) is not None
                    or len(segments) < 2
                    or any(segment in ("", ".", "..") for segment in segments)
                    or str(PurePosixPath(*segments)) != name
                    or segments[0] not in _VALIDATOR_RUNTIME_TOP_LEVELS
                    or info.is_dir()
                    or bool(info.flag_bits & 0x1)
                    or unix_kind not in (0, stat.S_IFREG)
                    or info.file_size < 0
                    or info.file_size > _VALIDATOR_ZIP_MEMBER_CAP_BYTES
                    or info.compress_size < 0
                    or info.compress_size > _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
                    or info.compress_type not in (
                        zipfile.ZIP_STORED,
                        zipfile.ZIP_DEFLATED,
                    )
                ):
                    _validator_reject()
                folded_parts: list[str] = []
                for index, segment in enumerate(segments):
                    folded_parts.append(_validator_win32_component_key(segment))
                    key = tuple(folded_parts)
                    exact = tuple(segments[: index + 1])
                    kind: Literal["file", "directory"] = (
                        "file" if index == len(segments) - 1 else "directory"
                    )
                    existing = nodes.get(key)
                    if existing is None:
                        nodes[key] = (exact, kind)
                        if len(nodes) > _VALIDATOR_RUNTIME_ENTRY_CAP:
                            _validator_reject()
                    elif existing[0] != exact or existing[1] != kind:
                        _validator_reject()
                    elif kind == "file":
                        _validator_reject()
                if name in names:
                    _validator_reject()
                names.add(name)
                declared_total += info.file_size
                if declared_total > _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES:
                    _validator_reject()
                member_actual = 0
                digest = sha256()
                with archive.open(info, mode="r") as source:
                    while True:
                        chunk = source.read(_VALIDATOR_COPY_CHUNK_BYTES)
                        if not chunk:
                            break
                        if (
                            member_actual + len(chunk) > info.file_size
                            or member_actual + len(chunk)
                            > _VALIDATOR_ZIP_MEMBER_CAP_BYTES
                            or actual_total + len(chunk)
                            > _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
                        ):
                            _validator_reject()
                        member_actual += len(chunk)
                        actual_total += len(chunk)
                        digest.update(chunk)
                if member_actual != info.file_size:
                    _validator_reject()
                members.append(
                    _ValidatorZipMember(
                        name=name,
                        size=info.file_size,
                        compressed_size=info.compress_size,
                        crc32=info.CRC,
                        sha256=digest.hexdigest(),
                    )
                )
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)
    if (
        "yaml/__init__.py" not in names
        or "pyyaml-6.0.3.dist-info/METADATA" not in names
        or not any(name.startswith("_yaml/") for name in names)
    ):
        _validator_reject()
    if actual_total != declared_total:
        _validator_reject()
    expected_paths = tuple(
        sorted(
            ("/".join(exact) for exact, _kind in nodes.values()),
            key=lambda value: (value.casefold(), value),
        )
    )
    return _ValidatorWheelPlan(
        members=tuple(members),
        expected_paths=expected_paths,
    )


def _validator_freeze_checkpoint(_stage: str, _path: Path) -> None:
    """Test interposition point around frozen validator source recapture."""


def _validator_create_directory(
    path: Path,
    *,
    creation_session: file_change_policy._HeldNoFollowCreationSession,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> FilesystemObjectIdentity:
    try:
        if path in created_objects:
            _validator_reject()
        parent_identity = _validator_plain_directory_identity(path.parent)
        identity = creation_session.create_directory(path)
        created_objects[path] = _ValidatorCreatedObject(
            path=str(_validator_absolute_path(path, output=True)),
            parent_identity=_copy_identity(parent_identity),
            kind="directory",
            identity=_copy_identity(identity),
            size=None,
            sha256=None,
        )
        if _validator_plain_directory_identity(path) != identity:
            _validator_reject()
        return identity
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)


def _validator_flush_directory(path: Path) -> None:
    identity_before = _validator_plain_directory_identity(path)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = (
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    )
    create_file.restype = wintypes.HANDLE
    flush_file_buffers = kernel32.FlushFileBuffers
    flush_file_buffers.argtypes = (wintypes.HANDLE,)
    flush_file_buffers.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = (wintypes.HANDLE,)
    close_handle.restype = wintypes.BOOL
    handle = create_file(
        str(path),
        0x40000000,
        0x1 | 0x2 | 0x4,
        None,
        3,
        0x00200000 | 0x02000000,
        None,
    )
    invalid_handle = ctypes.c_void_p(-1).value
    handle_value = getattr(handle, "value", handle)
    if handle_value in (None, invalid_handle):
        _validator_reject()
    flush_failed = False
    try:
        if not flush_file_buffers(handle):
            flush_failed = True
    finally:
        if not close_handle(handle):
            flush_failed = True
    if (
        flush_failed
        or _validator_plain_directory_identity(path) != identity_before
    ):
        _validator_reject()


def _validator_exclusive_write(
    path: Path,
    payload: bytes,
    *,
    creation_session: file_change_policy._HeldNoFollowCreationSession,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> FilesystemObjectIdentity:
    handle: object | None = None
    try:
        if path in created_objects:
            _validator_reject()
        parent_identity = _validator_plain_directory_identity(path.parent)
        handle = creation_session.create_file(path)
        created_identity, created_size = creation_session.snapshot_file(
            handle,
            path=path,
        )
        created_objects[path] = _ValidatorCreatedObject(
            path=str(_validator_absolute_path(path, output=True)),
            parent_identity=_copy_identity(parent_identity),
            kind="file",
            identity=_copy_identity(created_identity),
            size=None,
            sha256=None,
        )
        if created_size != 0:
            _validator_reject()
        offset = 0
        while offset < len(payload):
            end = min(offset + _VALIDATOR_COPY_CHUNK_BYTES, len(payload))
            creation_session.write(handle, payload[offset:end])
            offset = end
        finishing_handle = handle
        handle = None
        identity = creation_session.finish_file(
            finishing_handle,
            path=path,
            expected_size=len(payload),
        )
        captured, reopened_identity = _validator_capture_plain_file(
            path,
            max_bytes=max(len(payload), 1),
        )
        if (
            captured != payload
            or reopened_identity != identity
            or identity != created_identity
        ):
            _validator_reject()
        created_objects[path] = _ValidatorCreatedObject(
            path=str(_validator_absolute_path(path, output=True)),
            parent_identity=_copy_identity(parent_identity),
            kind="file",
            identity=_copy_identity(identity),
            size=len(payload),
            sha256=sha256(payload).hexdigest(),
        )
        return identity
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)
    finally:
        if handle is not None:
            creation_session.close_file(handle)


def _validator_ensure_member_parents(
    runtime_root: Path,
    relative: PurePosixPath,
    *,
    creation_session: file_change_policy._HeldNoFollowCreationSession,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> Path:
    current = runtime_root
    for part in relative.parts[:-1]:
        current = current / part
        if current.exists() or current.is_symlink():
            identity = _validator_plain_directory_identity(current)
            record = created_objects.get(current)
            if (
                record is None
                or record.kind != "directory"
                or record.identity != identity
            ):
                _validator_reject()
        else:
            _validator_create_directory(
                current,
                creation_session=creation_session,
                created_objects=created_objects,
            )
    destination = current / relative.name
    if destination.exists() or destination.is_symlink():
        _validator_reject()
    return destination


def _validator_extract_wheel(
    payload: bytes,
    members: tuple[_ValidatorZipMember, ...],
    runtime_root: Path,
    *,
    creation_session: file_change_policy._HeldNoFollowCreationSession,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> None:
    actual_total = 0
    try:
        with zipfile.ZipFile(io.BytesIO(payload), mode="r") as archive:
            for expected in members:
                info = archive.getinfo(expected.name)
                if (
                    info.file_size != expected.size
                    or info.compress_size != expected.compressed_size
                    or info.CRC != expected.crc32
                ):
                    _validator_reject()
                destination = _validator_ensure_member_parents(
                    runtime_root,
                    PurePosixPath(expected.name),
                    creation_session=creation_session,
                    created_objects=created_objects,
                )
                if destination in created_objects:
                    _validator_reject()
                parent_identity = _validator_plain_directory_identity(
                    destination.parent
                )
                handle: object | None = creation_session.create_file(destination)
                created_identity, created_size = creation_session.snapshot_file(
                    handle,
                    path=destination,
                )
                created_objects[destination] = _ValidatorCreatedObject(
                    path=str(_validator_absolute_path(destination, output=True)),
                    parent_identity=_copy_identity(parent_identity),
                    kind="file",
                    identity=_copy_identity(created_identity),
                    size=None,
                    sha256=None,
                )
                if created_size != 0:
                    _validator_reject()
                member_actual = 0
                digest = sha256()
                try:
                    with archive.open(info, mode="r") as source:
                        while True:
                            chunk = source.read(_VALIDATOR_COPY_CHUNK_BYTES)
                            if not chunk:
                                break
                            if (
                                member_actual + len(chunk) > expected.size
                                or member_actual + len(chunk)
                                > _VALIDATOR_ZIP_MEMBER_CAP_BYTES
                                or actual_total + len(chunk)
                                > _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
                            ):
                                _validator_reject()
                            creation_session.write(handle, chunk)
                            member_actual += len(chunk)
                            actual_total += len(chunk)
                            digest.update(chunk)
                    if (
                        member_actual != expected.size
                        or digest.hexdigest() != expected.sha256
                    ):
                        _validator_reject()
                    finishing_handle = handle
                    handle = None
                    identity = creation_session.finish_file(
                        finishing_handle,
                        path=destination,
                        expected_size=member_actual,
                    )
                finally:
                    if handle is not None:
                        creation_session.close_file(handle)
                captured, reopened_identity = _validator_capture_plain_file(
                    destination,
                    max_bytes=_VALIDATOR_ZIP_MEMBER_CAP_BYTES,
                )
                if (
                    len(captured) != expected.size
                    or sha256(captured).hexdigest() != expected.sha256
                    or reopened_identity != identity
                    or identity != created_identity
                ):
                    _validator_reject()
                created_objects[destination] = _ValidatorCreatedObject(
                    path=str(_validator_absolute_path(destination, output=True)),
                    parent_identity=_copy_identity(parent_identity),
                    kind="file",
                    identity=_copy_identity(identity),
                    size=expected.size,
                    sha256=expected.sha256,
                )
    except RuntimeError:
        raise
    except BaseException as exc:
        _validator_reject(exc)
    if actual_total != sum(member.size for member in members):
        _validator_reject()


def _validator_capture_entries(
    root: Path,
    *,
    max_entries: int,
    max_bytes: int,
) -> tuple[FilesystemSnapshotEntry, ...]:
    try:
        snapshots = preparation.capture_policy_filesystem_roots(
            case_root=root.parent,
            approved_roots=(root,),
        )
    except BaseException as exc:
        _validator_reject(exc)
    if len(snapshots) != 1 or snapshots[0].root_identity is None:
        _validator_reject()
    entries = tuple(
        sorted(
            (
                FilesystemSnapshotEntry(
                    relative_path=entry.relative_path.replace("\\", "/"),
                    kind=entry.kind,
                    size=entry.size,
                    sha256=entry.sha256,
                    link_count=entry.link_count,
                    identity=_copy_identity(entry.identity),
                )
                for entry in snapshots[0].entries
            ),
            key=lambda entry: (entry.relative_path.casefold(), entry.relative_path),
        )
    )
    if (
        len(entries) > max_entries
        or sum(entry.size for entry in entries if entry.kind == "file") > max_bytes
        or len({entry.relative_path.casefold() for entry in entries}) != len(entries)
    ):
        _validator_reject()
    return entries


def _validator_remove_created_root(
    root: Path,
    *,
    expected_root_identity: FilesystemObjectIdentity,
    created_objects: dict[Path, _ValidatorCreatedObject],
    creation_session: file_change_policy._HeldNoFollowCreationSession | None = None,
    max_entries: int = _VALIDATOR_RUNTIME_ENTRY_CAP + 3,
    max_bytes: int = (
        _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
        + _VALIDATOR_SCRIPT_AGGREGATE_CAP_BYTES
    ),
) -> None:
    try:
        if (
            type(max_entries) is not int
            or max_entries < 1
            or type(max_bytes) is not int
            or max_bytes < 0
        ):
            return
        root_record = created_objects.get(root)
        if (
            creation_session is None
            or creation_session.closed
            or root_record is None
            or root_record.kind != "directory"
            or root_record.identity != expected_root_identity
            or root_record.path != str(root)
            or root_record.size is not None
            or root_record.sha256 is not None
        ):
            return
        canonical_root = _validator_absolute_path(root, output=True)
        if canonical_root != root:
            return
        expected_paths = set(created_objects)
        if not expected_paths or len(expected_paths) != len(created_objects):
            return
        for path, record in created_objects.items():
            canonical = _validator_absolute_path(path, output=True)
            if (
                canonical != path
                or record.path != str(path)
                or (path != root and root not in path.parents)
                or _validator_plain_directory_identity(path.parent)
                != record.parent_identity
            ):
                return
            if path == root:
                if record.parent_identity != _validator_plain_directory_identity(
                    root.parent
                ):
                    return
            else:
                parent_record = created_objects.get(path.parent)
                if (
                    parent_record is None
                    or parent_record.kind != "directory"
                    or parent_record.identity != record.parent_identity
                ):
                    return
        captured = _validator_capture_entries(
            root,
            max_entries=max_entries,
            max_bytes=max_bytes,
        )
        observed_paths = {root}
        for entry in captured:
            path = root.joinpath(*PurePosixPath(entry.relative_path).parts)
            if path in observed_paths:
                return
            observed_paths.add(path)
            record = created_objects.get(path)
            if (
                record is None
                or record.kind != entry.kind
                or record.identity != entry.identity
            ):
                return
            if record.kind == "file":
                if (
                    record.size is None
                    or record.sha256 is None
                    or entry.size != record.size
                    or entry.sha256 != record.sha256
                ):
                    return
            elif record.size is not None or record.sha256 is not None:
                return
        if observed_paths != expected_paths:
            return
        remaining = dict(created_objects)

        def membership_matches() -> bool:
            pending = [root]
            observed = {root}
            while pending:
                directory = pending.pop()
                with os.scandir(directory) as iterator:
                    children = list(iterator)
                for item in children:
                    path = Path(item.path)
                    record = remaining.get(path)
                    if record is None or path in observed or item.is_symlink():
                        return False
                    observed.add(path)
                    if item.is_dir(follow_symlinks=False):
                        if record.kind != "directory":
                            return False
                        pending.append(path)
                    elif item.is_file(follow_symlinks=False):
                        if record.kind != "file":
                            return False
                    else:
                        return False
            return observed == set(remaining)

        file_paths = sorted(
            (
                path
                for path, record in remaining.items()
                if record.kind == "file"
            ),
            key=lambda value: (len(value.parts), str(value).casefold(), str(value)),
            reverse=True,
        )
        for path in file_paths:
            record = remaining[path]
            if (
                record.size is None
                or record.sha256 is None
                or not membership_matches()
            ):
                return
            creation_session.revalidate_directories()
            creation_session.remove_file(
                path,
                expected_parent_identity=record.parent_identity,
                expected_identity=record.identity,
                expected_size=record.size,
                expected_sha256=record.sha256,
            )
            del remaining[path]
        directory_paths = sorted(
            remaining,
            key=lambda value: (len(value.parts), str(value).casefold(), str(value)),
            reverse=True,
        )
        for path in directory_paths:
            record = remaining[path]
            if record.kind != "directory" or not membership_matches():
                return
            creation_session.revalidate_directories()
            creation_session.remove_directory(
                path,
                expected_parent_identity=record.parent_identity,
                expected_identity=record.identity,
            )
            del remaining[path]
        if remaining or os.path.lexists(root):
            return
    except BaseException:
        return


@dataclass(frozen=True)
class CapturedLaunchInput:
    path: str
    content: bytes
    utf8_bytes: int
    sha256: str
    identity: FilesystemObjectIdentity

    def __post_init__(self) -> None:
        if (
            not _valid_absolute_path(self.path)
            or type(self.content) is not bytes
            or len(self.content) > _MAX_CAPTURE_BYTES
            or type(self.utf8_bytes) is not int
            or self.utf8_bytes != len(self.content)
            or not _is_sha256(self.sha256)
            or sha256(self.content).hexdigest() != self.sha256
        ):
            _reject(CLIENT_LAUNCH_INPUT_INVALID)
        try:
            self.content.decode("utf-8", errors="strict")
        except UnicodeError as exc:
            raise RuntimeError(CLIENT_LAUNCH_INPUT_INVALID) from exc
        _validate_plain_identity(
            self.identity,
            code=CLIENT_LAUNCH_INPUT_INVALID,
        )


@dataclass(frozen=True, repr=False)
class _DecodedShellClientCapture:
    capture: CapturedLaunchInput
    tool_item_id: str
    started_event_ordinal: int
    completed_event_ordinal: int
    started_event_sha256: str
    completed_event_sha256: str
    extracted: command_plan.ExtractedPowerShellPayload
    aggregated_output_utf8_bytes: int
    aggregated_output_sha256: str
    exit_code: int
    normalized_event_bytes: bytes
    normalized_event_sha256: str


@dataclass(frozen=True)
class FrozenImportEntry:
    relative_path: str
    kind: Literal["file", "directory"]
    byte_count: int
    sha256: str | None
    identity: FilesystemObjectIdentity

    def __post_init__(self) -> None:
        try:
            relative = PurePosixPath(self.relative_path)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
        if (
            type(self.relative_path) is not str
            or not self.relative_path
            or relative.is_absolute()
            or str(relative) != self.relative_path
            or any(part in {"", ".", ".."} for part in relative.parts)
            or "\\" in self.relative_path
            or self.kind not in {"file", "directory"}
            or type(self.byte_count) is not int
            or self.byte_count < 0
            or self.byte_count > _GUARDED_FILE_BYTE_CAP
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        _validate_plain_identity(
            self.identity,
            code=GUARDED_PYTHON_RUNTIME_INVALID,
        )
        if self.kind == "directory":
            if self.byte_count != 0 or self.sha256 is not None:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        elif not _is_sha256(self.sha256):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)


@dataclass(frozen=True)
class FrozenDistribution:
    normalized_name: str
    distribution_version: str
    dist_info_relative_path: str
    metadata_sha256: str
    record_sha256: str
    omitted_launcher_paths: tuple[str, ...]
    omitted_inert_paths: tuple[str, ...]
    entries: tuple[FrozenImportEntry, ...]
    manifest_sha256: str

    def __post_init__(self) -> None:
        if (
            type(self.normalized_name) is not str
            or _GUARDED_NAME.fullmatch(self.normalized_name) is None
            or type(self.distribution_version) is not str
            or not self.distribution_version
            or len(self.distribution_version) > 128
            or type(self.dist_info_relative_path) is not str
            or "/" in self.dist_info_relative_path
            or "\\" in self.dist_info_relative_path
            or not self.dist_info_relative_path.casefold().endswith(".dist-info")
            or not _is_sha256(self.metadata_sha256)
            or not _is_sha256(self.record_sha256)
            or type(self.omitted_launcher_paths) is not tuple
            or type(self.omitted_inert_paths) is not tuple
            or type(self.entries) is not tuple
            or not self.entries
            or len(self.entries) > _GUARDED_RUNTIME_ENTRY_CAP
            or any(type(item) is not str for item in self.omitted_launcher_paths)
            or any(type(item) is not str for item in self.omitted_inert_paths)
            or tuple(sorted(self.omitted_launcher_paths))
            != self.omitted_launcher_paths
            or tuple(sorted(self.omitted_inert_paths)) != self.omitted_inert_paths
            or not _is_sha256(self.manifest_sha256)
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        _guarded_validate_import_entries(self.entries)
        if (
            sha256(
                preparation.canonical_bytes(_guarded_distribution_payload(self))
            ).hexdigest()
            != self.manifest_sha256
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)


@dataclass(frozen=True)
class FrozenImportRoot:
    role: Literal[
        "python_home",
        "stdlib_zip",
        "stdlib_dlls",
        "stdlib_lib",
        "runtime_site",
        "repository_src",
        "repository_tests",
        "repository_skills",
        "repository_integration",
        "installed_target",
        "validator_bundle",
    ]
    path: str
    identity: FilesystemObjectIdentity | None
    entries: tuple[FrozenImportEntry, ...]
    entry_count: int
    byte_count: int
    manifest_sha256: str

    def __post_init__(self) -> None:
        if (
            self.role not in _GUARDED_IMPORT_ROOT_ROLES
            or not _valid_absolute_path(self.path)
            or type(self.entries) is not tuple
            or type(self.entry_count) is not int
            or self.entry_count != len(self.entries)
            or type(self.byte_count) is not int
            or self.byte_count
            != sum(item.byte_count for item in self.entries if item.kind == "file")
            or self.byte_count < 0
            or not _is_sha256(self.manifest_sha256)
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if self.identity is not None:
            _validate_plain_identity(
                self.identity,
                code=GUARDED_PYTHON_RUNTIME_INVALID,
            )
        _guarded_validate_import_entries(self.entries)
        if (
            sha256(
                preparation.canonical_bytes(_guarded_import_root_payload(self))
            ).hexdigest()
            != self.manifest_sha256
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)


@dataclass(frozen=True)
class FrozenGuardedPythonRuntime:
    version: Literal["complete-suite-guarded-python-runtime-v1"]
    root: str
    root_identity: FilesystemObjectIdentity
    python_path: str
    python_size: int
    python_sha256: str
    python_identity: FilesystemObjectIdentity
    bootstrap: CapturedLaunchInput
    project_metadata: CapturedLaunchInput
    python_version: str
    cache_tag: str
    startup_sys_path_roles: tuple[str, ...]
    base_sys_path_roles: tuple[str, ...]
    import_roots: tuple[FrozenImportRoot, ...]
    distributions: tuple[FrozenDistribution, ...]
    entry_count: int
    byte_count: int
    canonical_sha256: str

    def __post_init__(self) -> None:
        root = Path(self.root) if type(self.root) is str else Path()
        if (
            self.version != _GUARDED_RUNTIME_VERSION
            or not _valid_absolute_path(self.root)
            or root.name != "guarded-python-runtime"
            or self.python_path != str(root / "python.exe")
            or type(self.python_size) is not int
            or self.python_size < 1
            or self.python_size > _GUARDED_FILE_BYTE_CAP
            or not _is_sha256(self.python_sha256)
            or type(self.bootstrap) is not CapturedLaunchInput
            or type(self.project_metadata) is not CapturedLaunchInput
            or self.bootstrap.path
            != str(root / "complete_suite_release_python_bootstrap.py")
            or self.project_metadata.path != str(root / "pyproject.toml")
            or type(self.python_version) is not str
            or not self.python_version
            or type(self.cache_tag) is not str
            or not self.cache_tag
            or not _guarded_sys_path_roles_are_valid(
                self.startup_sys_path_roles,
                self.base_sys_path_roles,
            )
            or type(self.import_roots) is not tuple
            or len(self.import_roots) != len(self.startup_sys_path_roles)
            or any(type(item) is not FrozenImportRoot for item in self.import_roots)
            or tuple(item.role for item in self.import_roots)
            != self.startup_sys_path_roles
            or type(self.distributions) is not tuple
            or tuple(item.normalized_name for item in self.distributions)
            != tuple(
                sorted(
                    (item.normalized_name for item in self.distributions),
                    key=lambda value: (value.casefold(), value),
                )
            )
            or len({item.normalized_name for item in self.distributions})
            != len(self.distributions)
            or type(self.entry_count) is not int
            or self.entry_count < 1
            or type(self.byte_count) is not int
            or self.byte_count < 1
            or not _is_sha256(self.canonical_sha256)
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        _validate_plain_identity(
            self.root_identity,
            code=GUARDED_PYTHON_RUNTIME_INVALID,
        )
        _validate_plain_identity(
            self.python_identity,
            code=GUARDED_PYTHON_RUNTIME_INVALID,
        )
        try:
            self.bootstrap.__post_init__()
            self.project_metadata.__post_init__()
            expected_paths = {
                "python_home": str(root),
                **{
                    role: str(root / relative_path)
                    for role, relative_path in _GUARDED_ROLE_RELATIVE_PATHS.items()
                },
            }
            for item in self.import_roots:
                if (
                    type(item) is not FrozenImportRoot
                    or item.path != expected_paths.get(item.role)
                    or item.identity is None
                ):
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                item.__post_init__()
            for item in self.distributions:
                if type(item) is not FrozenDistribution:
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                item.__post_init__()
        except BaseException as exc:
            if (
                isinstance(exc, RuntimeError)
                and str(exc) == GUARDED_PYTHON_RUNTIME_INVALID
            ):
                raise
            raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
        _guarded_validate_limits(
            distribution_count=len(self.distributions),
            runtime_entry_count=self.import_roots[-1].entry_count,
            runtime_byte_count=self.import_roots[-1].byte_count,
            core_entry_count=self.entry_count - self.import_roots[-1].entry_count,
            core_byte_count=self.byte_count - self.import_roots[-1].byte_count,
            file_byte_count=max(
                item.byte_count
                for root_item in self.import_roots
                for item in root_item.entries
                if item.kind == "file"
            ),
            record_byte_bound=max(
                (
                    item.byte_count
                    for distribution in self.distributions
                    for item in distribution.entries
                    if item.relative_path.endswith(".dist-info/RECORD")
                ),
                default=0,
            ),
        )
        if (
            sha256(
                preparation.canonical_bytes(_guarded_runtime_payload(self))
            ).hexdigest()
            != self.canonical_sha256
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)


def _guarded_validate_import_entries(
    entries: tuple[FrozenImportEntry, ...],
) -> None:
    if (
        type(entries) is not tuple
        or any(type(item) is not FrozenImportEntry for item in entries)
        or tuple(item.relative_path for item in entries)
        != tuple(
            sorted(
                (item.relative_path for item in entries),
                key=lambda value: (value.casefold(), value),
            )
        )
        or len({item.relative_path.casefold() for item in entries}) != len(entries)
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    for item in entries:
        item.__post_init__()


def _guarded_import_entry_payload(value: FrozenImportEntry) -> dict[str, object]:
    return {
        "byte_count": value.byte_count,
        "identity": _identity_record(value.identity),
        "kind": value.kind,
        "relative_path": value.relative_path,
        "sha256": value.sha256,
    }


def _guarded_distribution_payload(value: FrozenDistribution) -> dict[str, object]:
    return {
        "dist_info_relative_path": value.dist_info_relative_path,
        "distribution_version": value.distribution_version,
        "entries": [_guarded_import_entry_payload(item) for item in value.entries],
        "metadata_sha256": value.metadata_sha256,
        "normalized_name": value.normalized_name,
        "omitted_inert_paths": list(value.omitted_inert_paths),
        "omitted_launcher_paths": list(value.omitted_launcher_paths),
        "record_sha256": value.record_sha256,
    }


def _guarded_import_root_payload(value: FrozenImportRoot) -> dict[str, object]:
    return {
        "byte_count": value.byte_count,
        "entries": [_guarded_import_entry_payload(item) for item in value.entries],
        "entry_count": value.entry_count,
        "identity": (
            None if value.identity is None else _identity_record(value.identity)
        ),
        "path": value.path,
        "role": value.role,
    }


def _guarded_runtime_payload(value: FrozenGuardedPythonRuntime) -> dict[str, object]:
    return {
        "base_sys_path_roles": list(value.base_sys_path_roles),
        "bootstrap": {
            "identity": _identity_record(value.bootstrap.identity),
            "path": value.bootstrap.path,
            "sha256": value.bootstrap.sha256,
            "utf8_bytes": value.bootstrap.utf8_bytes,
        },
        "byte_count": value.byte_count,
        "cache_tag": value.cache_tag,
        "distributions": [
            {
                **_guarded_distribution_payload(item),
                "manifest_sha256": item.manifest_sha256,
            }
            for item in value.distributions
        ],
        "entry_count": value.entry_count,
        "import_roots": [
            {
                **_guarded_import_root_payload(item),
                "manifest_sha256": item.manifest_sha256,
            }
            for item in value.import_roots
        ],
        "project_metadata": {
            "identity": _identity_record(value.project_metadata.identity),
            "path": value.project_metadata.path,
            "sha256": value.project_metadata.sha256,
            "utf8_bytes": value.project_metadata.utf8_bytes,
        },
        "python_identity": _identity_record(value.python_identity),
        "python_path": value.python_path,
        "python_sha256": value.python_sha256,
        "python_size": value.python_size,
        "python_version": value.python_version,
        "root": value.root,
        "root_identity": _identity_record(value.root_identity),
        "startup_sys_path_roles": list(value.startup_sys_path_roles),
        "version": value.version,
    }


def _guarded_make_distribution(
    *,
    normalized_name: str,
    distribution_version: str,
    dist_info_relative_path: str,
    metadata_sha256: str,
    record_sha256: str,
    omitted_launcher_paths: tuple[str, ...],
    omitted_inert_paths: tuple[str, ...],
    entries: tuple[FrozenImportEntry, ...],
) -> FrozenDistribution:
    prototype = object.__new__(FrozenDistribution)
    values: dict[str, object] = {
        "normalized_name": normalized_name,
        "distribution_version": distribution_version,
        "dist_info_relative_path": dist_info_relative_path,
        "metadata_sha256": metadata_sha256,
        "record_sha256": record_sha256,
        "omitted_launcher_paths": omitted_launcher_paths,
        "omitted_inert_paths": omitted_inert_paths,
        "entries": entries,
    }
    for name, value in values.items():
        object.__setattr__(prototype, name, value)
    manifest = sha256(
        preparation.canonical_bytes(_guarded_distribution_payload(prototype))
    ).hexdigest()
    return FrozenDistribution(**values, manifest_sha256=manifest)


def _guarded_make_import_root(
    *,
    role: str,
    path: str,
    identity: FilesystemObjectIdentity | None,
    entries: tuple[FrozenImportEntry, ...],
) -> FrozenImportRoot:
    prototype = object.__new__(FrozenImportRoot)
    values: dict[str, object] = {
        "role": role,
        "path": path,
        "identity": identity,
        "entries": entries,
        "entry_count": len(entries),
        "byte_count": sum(
            item.byte_count for item in entries if item.kind == "file"
        ),
    }
    for name, value in values.items():
        object.__setattr__(prototype, name, value)
    manifest = sha256(
        preparation.canonical_bytes(_guarded_import_root_payload(prototype))
    ).hexdigest()
    return FrozenImportRoot(**values, manifest_sha256=manifest)


def _guarded_validate_limits(
    distribution_count: int,
    runtime_entry_count: int,
    runtime_byte_count: int,
    core_entry_count: int,
    core_byte_count: int,
    file_byte_count: int,
    record_byte_bound: int,
) -> None:
    values = (
        (distribution_count, _GUARDED_DISTRIBUTION_CAP),
        (runtime_entry_count, _GUARDED_RUNTIME_ENTRY_CAP),
        (runtime_byte_count, _GUARDED_RUNTIME_BYTE_CAP),
        (core_entry_count, _GUARDED_CORE_ENTRY_CAP),
        (core_byte_count, _GUARDED_CORE_BYTE_CAP),
        (file_byte_count, _GUARDED_FILE_BYTE_CAP),
        (record_byte_bound, _GUARDED_RECORD_BYTE_CAP),
    )
    if any(type(value) is not int or value < 0 or value > cap for value, cap in values):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)


def _guarded_runtime_host_facts() -> dict[str, object]:
    import site
    import sysconfig

    user_root = site.getusersitepackages()
    base_root = sysconfig.get_path("purelib")
    if type(user_root) is not str or type(base_root) is not str:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return {
        "python_path": Path(sys.executable),
        "python_version": (
            f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
        ),
        "cache_tag": sys.implementation.cache_tag,
        "distribution_roots": (Path(user_root), Path(base_root)),
    }


@dataclass(frozen=True)
class FrozenValidatorInput:
    role: Literal["plugin", "skill"]
    bundle_path: str
    source_locator: str
    size: int
    sha256: str
    identity: FilesystemObjectIdentity

    def __post_init__(self) -> None:
        expected = {
            role: (locator, filename)
            for role, locator, filename in _VALIDATOR_SOURCE_LOCATORS
        }
        if (
            self.role not in expected
            or not _valid_absolute_path(self.bundle_path)
            or type(self.source_locator) is not str
            or (self.source_locator, Path(self.bundle_path).name)
            != expected[self.role]
            or type(self.size) is not int
            or self.size < 1
            or self.size > _VALIDATOR_SCRIPT_CAP_BYTES
            or not _is_sha256(self.sha256)
        ):
            _validator_reject()
        _validate_plain_identity(self.identity, code=VALIDATOR_BUNDLE_INVALID)


@dataclass(frozen=True)
class FrozenValidatorRuntime:
    root: str
    root_identity: FilesystemObjectIdentity
    source_wheel_name: str
    source_wheel_size: int
    source_wheel_sha256: str
    source_wheel_identity: FilesystemObjectIdentity
    entries: tuple[FilesystemSnapshotEntry, ...]
    manifest_sha256: str

    def __post_init__(self) -> None:
        if (
            not _valid_absolute_path(self.root)
            or Path(self.root).name != "runtime"
            or self.source_wheel_name != _VALIDATOR_WHEEL_NAME
            or type(self.source_wheel_size) is not int
            or self.source_wheel_size != _VALIDATOR_WHEEL_SIZE
            or self.source_wheel_sha256 != _VALIDATOR_WHEEL_SHA256
            or type(self.entries) is not tuple
            or not self.entries
            or len(self.entries) > _VALIDATOR_RUNTIME_ENTRY_CAP
            or any(type(entry) is not FilesystemSnapshotEntry for entry in self.entries)
            or tuple(entry.relative_path for entry in self.entries)
            != tuple(
                sorted(
                    (entry.relative_path for entry in self.entries),
                    key=lambda value: (value.casefold(), value),
                )
            )
            or len({entry.relative_path.casefold() for entry in self.entries})
            != len(self.entries)
            or not _is_sha256(self.manifest_sha256)
        ):
            _validator_reject()
        _validate_plain_identity(self.root_identity, code=VALIDATOR_BUNDLE_INVALID)
        _validate_plain_identity(
            self.source_wheel_identity,
            code=VALIDATOR_BUNDLE_INVALID,
        )
        for entry in self.entries:
            try:
                entry.__post_init__()
            except BaseException as exc:
                _validator_reject(exc)
            first = entry.relative_path.split("/", 1)[0]
            if first not in _VALIDATOR_RUNTIME_TOP_LEVELS:
                _validator_reject()
        file_entries = tuple(entry for entry in self.entries if entry.kind == "file")
        file_paths = {entry.relative_path for entry in file_entries}
        if (
            sum(entry.size for entry in file_entries)
            > _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
            or "yaml/__init__.py" not in file_paths
            or "pyyaml-6.0.3.dist-info/METADATA" not in file_paths
            or not any(path.startswith("_yaml/") for path in file_paths)
            or sha256(
                preparation.canonical_bytes(_validator_runtime_payload(self))
            ).hexdigest()
            != self.manifest_sha256
        ):
            _validator_reject()


@dataclass(frozen=True)
class FrozenValidatorBundle:
    root: str
    root_identity: FilesystemObjectIdentity
    inputs: tuple[FrozenValidatorInput, ...]
    runtime: FrozenValidatorRuntime
    manifest_sha256: str

    def __post_init__(self) -> None:
        if (
            not _valid_absolute_path(self.root)
            or type(self.inputs) is not tuple
            or tuple(item.role for item in self.inputs) != ("plugin", "skill")
            or any(type(item) is not FrozenValidatorInput for item in self.inputs)
            or type(self.runtime) is not FrozenValidatorRuntime
            or self.runtime.root != str(Path(self.root) / "runtime")
            or tuple(item.bundle_path for item in self.inputs)
            != (
                str(Path(self.root) / "validate_plugin.py"),
                str(Path(self.root) / "quick_validate.py"),
            )
            or sum(item.size for item in self.inputs)
            > _VALIDATOR_SCRIPT_AGGREGATE_CAP_BYTES
            or not _is_sha256(self.manifest_sha256)
        ):
            _validator_reject()
        _validate_plain_identity(self.root_identity, code=VALIDATOR_BUNDLE_INVALID)
        try:
            for item in self.inputs:
                item.__post_init__()
            self.runtime.__post_init__()
        except BaseException as exc:
            if isinstance(exc, RuntimeError) and str(exc) == VALIDATOR_BUNDLE_INVALID:
                raise
            _validator_reject(exc)
        if (
            sha256(
                preparation.canonical_bytes(_validator_bundle_payload(self))
            ).hexdigest()
            != self.manifest_sha256
        ):
            _validator_reject()


def _validator_input_payload(value: FrozenValidatorInput) -> dict[str, object]:
    return {
        "bundle_path": value.bundle_path,
        "identity": _identity_record(value.identity),
        "role": value.role,
        "sha256": value.sha256,
        "size": value.size,
        "source_locator": value.source_locator,
    }


def _validator_runtime_payload(
    value: FrozenValidatorRuntime,
    *,
    include_manifest: bool = False,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "entries": [_entry_record(entry) for entry in value.entries],
        "root": value.root,
        "root_identity": _identity_record(value.root_identity),
        "source_wheel_identity": _identity_record(value.source_wheel_identity),
        "source_wheel_name": value.source_wheel_name,
        "source_wheel_sha256": value.source_wheel_sha256,
        "source_wheel_size": value.source_wheel_size,
    }
    if include_manifest:
        payload["manifest_sha256"] = value.manifest_sha256
    return payload


def _validator_bundle_payload(value: FrozenValidatorBundle) -> dict[str, object]:
    return {
        "inputs": [_validator_input_payload(item) for item in value.inputs],
        "root": value.root,
        "root_identity": _identity_record(value.root_identity),
        "runtime": _validator_runtime_payload(
            value.runtime,
            include_manifest=True,
        ),
    }


@dataclass(frozen=True)
class ClientFileChangePreflight:
    version: str
    audit_root: str
    before_snapshot: FilesystemRootSnapshot
    after_add_snapshot: FilesystemRootSnapshot
    after_update_snapshot: FilesystemRootSnapshot
    add_capture_path: str
    add_capture_utf8_bytes: int
    add_capture_sha256: str
    add_capture_identity: FilesystemObjectIdentity
    update_capture_path: str
    update_capture_utf8_bytes: int
    update_capture_sha256: str
    update_capture_identity: FilesystemObjectIdentity
    add_started_sha256: str
    add_completed_sha256: str
    update_started_sha256: str
    update_completed_sha256: str
    add_bytes_sha256: str
    update_bytes_sha256: str
    advertised_tools_sha256: str
    lifecycle_contract_sha256: str
    canonical_sha256: str

    def __post_init__(self) -> None:
        if (
            self.version != _PREFLIGHT_VERSION
            or not _valid_absolute_path(self.audit_root)
            or Path(self.audit_root).name != _AUDIT_ROOT_NAME
            or not _valid_absolute_path(self.add_capture_path)
            or not _valid_absolute_path(self.update_capture_path)
            or type(self.add_capture_utf8_bytes) is not int
            or self.add_capture_utf8_bytes < 0
            or type(self.update_capture_utf8_bytes) is not int
            or self.update_capture_utf8_bytes < 0
            or any(
                not _is_sha256(value)
                for value in (
                    self.add_capture_sha256,
                    self.update_capture_sha256,
                    self.add_started_sha256,
                    self.add_completed_sha256,
                    self.update_started_sha256,
                    self.update_completed_sha256,
                    self.add_bytes_sha256,
                    self.update_bytes_sha256,
                    self.advertised_tools_sha256,
                    self.lifecycle_contract_sha256,
                    self.canonical_sha256,
                )
            )
        ):
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        _validate_plain_identity(
            self.add_capture_identity,
            code=FILE_CHANGE_EVENT_LIFECYCLE_INVALID,
        )
        _validate_plain_identity(
            self.update_capture_identity,
            code=FILE_CHANGE_EVENT_LIFECYCLE_INVALID,
        )
        _validate_distinct_captures(
            add_path=self.add_capture_path,
            add_sha256=self.add_capture_sha256,
            add_identity=self.add_capture_identity,
            update_path=self.update_capture_path,
            update_sha256=self.update_capture_sha256,
            update_identity=self.update_capture_identity,
        )
        _validate_snapshot_contract(
            audit_root=Path(self.audit_root),
            before_snapshot=self.before_snapshot,
            after_add_snapshot=self.after_add_snapshot,
            after_update_snapshot=self.after_update_snapshot,
        )
        if (
            self.add_bytes_sha256 != sha256(_ADD_BYTES).hexdigest()
            or self.update_bytes_sha256 != sha256(_UPDATE_BYTES).hexdigest()
            or sha256(_canonical_json_bytes(_lifecycle_payload(self))).hexdigest()
            != self.lifecycle_contract_sha256
            or sha256(_canonical_json_bytes(_preflight_payload(self))).hexdigest()
            != self.canonical_sha256
        ):
            _reject(FILE_CHANGE_CONTENT_INVALID)


def _validate_distinct_captures(
    *,
    add_path: str,
    add_sha256: str,
    add_identity: FilesystemObjectIdentity,
    update_path: str,
    update_sha256: str,
    update_identity: FilesystemObjectIdentity,
) -> None:
    if (
        ntpath.normcase(ntpath.normpath(add_path))
        == ntpath.normcase(ntpath.normpath(update_path))
        or add_sha256 == update_sha256
        or add_identity == update_identity
    ):
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)


def _validate_snapshot_contract(
    *,
    audit_root: Path,
    before_snapshot: object,
    after_add_snapshot: object,
    after_update_snapshot: object,
) -> None:
    snapshots = (before_snapshot, after_add_snapshot, after_update_snapshot)
    if any(type(snapshot) is not FilesystemRootSnapshot for snapshot in snapshots):
        _reject(FILE_CHANGE_PATH_UNSAFE)
    try:
        for snapshot in snapshots:
            snapshot.__post_init__()
    except Exception as exc:
        raise RuntimeError(FILE_CHANGE_PATH_UNSAFE) from exc
    expected_root = audit_root.name
    if (
        expected_root != _AUDIT_ROOT_NAME
        or any(snapshot.root_index != 0 for snapshot in snapshots)
        or any(snapshot.relative_root != expected_root for snapshot in snapshots)
        or before_snapshot.present
        or before_snapshot.root_identity is not None
        or before_snapshot.entries
        or not after_add_snapshot.present
        or not after_update_snapshot.present
        or after_add_snapshot.root_identity != after_update_snapshot.root_identity
        or before_snapshot.ancestor_identities
        != after_add_snapshot.ancestor_identities
        or before_snapshot.ancestor_identities
        != after_update_snapshot.ancestor_identities
        or len(after_add_snapshot.entries) != 1
        or len(after_update_snapshot.entries) != 1
    ):
        _reject(FILE_CHANGE_PATH_UNSAFE)
    add_entry = after_add_snapshot.entries[0]
    update_entry = after_update_snapshot.entries[0]
    if (
        add_entry.relative_path != _AUDIT_FILENAME
        or update_entry.relative_path != _AUDIT_FILENAME
        or add_entry.kind != "file"
        or update_entry.kind != "file"
        or add_entry.identity != update_entry.identity
    ):
        _reject(FILE_CHANGE_PATH_UNSAFE)
    if (
        add_entry.size != len(_ADD_BYTES)
        or add_entry.sha256 != sha256(_ADD_BYTES).hexdigest()
        or update_entry.size != len(_UPDATE_BYTES)
        or update_entry.sha256 != sha256(_UPDATE_BYTES).hexdigest()
    ):
        _reject(FILE_CHANGE_CONTENT_INVALID)


def _duplicate_key_rejecting_object(
    pairs: list[tuple[str, Any]],
) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if type(key) is not str or key in result:
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        result[key] = value
    return result


def _reject_json_constant(_value: str) -> NoReturn:
    _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)


def _validate_file_change_event_wrappers(
    content: bytes,
) -> tuple[str, str]:
    if not content or not content.endswith(b"\n") or b"\r" in content:
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
    file_change_events: dict[str, str] = {}
    for line in content[:-1].split(b"\n"):
        if not line:
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        try:
            event = json.loads(
                line.decode("utf-8", errors="strict"),
                object_pairs_hook=_duplicate_key_rejecting_object,
                parse_constant=_reject_json_constant,
            )
        except RuntimeError:
            raise
        except (UnicodeError, json.JSONDecodeError, RecursionError, ValueError) as exc:
            raise RuntimeError(FILE_CHANGE_EVENT_LIFECYCLE_INVALID) from exc
        if type(event) is not dict or type(event.get("type")) is not str:
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        if event["type"] not in {"item.started", "item.completed"}:
            continue
        item = event.get("item")
        if type(item) is not dict or type(item.get("type")) is not str:
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        if item["type"] == "command_execution":
            _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
        if item["type"] == "file_change":
            if (
                set(event) != {"type", "item"}
                or event["type"] in file_change_events
            ):
                _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
            file_change_events[event["type"]] = sha256(line).hexdigest()
    if set(file_change_events) != {"item.started", "item.completed"}:
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
    return (
        file_change_events["item.started"],
        file_change_events["item.completed"],
    )


def _decode_preflight_capture(
    capture: CapturedLaunchInput,
    *,
    audit_root: Path,
):
    raw_event_sha256 = _validate_file_change_event_wrappers(capture.content)
    binding = file_change_policy.FileChangeRootBinding(
        token=_AUDIT_TOKEN,
        literal_root=str(audit_root),
    )
    try:
        plan = file_change_policy.decode_file_change_lifecycles(
            capture.content,
            domain="preflight",
            root_bindings=(binding,),
        )
    except RuntimeError as exc:
        code = str(exc)
        if code in {
            file_change_policy.FILE_CHANGE_PATH_INVALID,
            file_change_policy.FILE_CHANGE_ROOT_BINDING_INVALID,
        }:
            raise RuntimeError(FILE_CHANGE_PATH_UNSAFE) from exc
        if code in {
            file_change_policy.FILE_CHANGE_SESSION_INVALID,
            file_change_policy.FILE_CHANGE_DOMAIN_INVALID,
            file_change_policy.FILE_CHANGE_EVENT_TYPE_INVALID,
            file_change_policy.FILE_CHANGE_LIFECYCLE_INVALID,
            file_change_policy.FILE_CHANGE_KIND_INVALID,
            file_change_policy.FILE_CHANGE_RESOURCE_LIMIT_EXCEEDED,
        }:
            raise RuntimeError(FILE_CHANGE_EVENT_LIFECYCLE_INVALID) from exc
        raise
    return plan, raw_event_sha256


def _validate_decoded_change(
    plan: object,
    *,
    expected_kind: str,
    expected_raw_path: str,
):
    if (
        type(plan) is not file_change_policy.DecodedFileChangePlan
        or plan.domain != "preflight"
        or plan.lifecycles != 1
        or plan.transition_entries != 1
        or len(plan.changes) != 1
    ):
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
    change = plan.changes[0]
    if (
        change.lifecycle_index != 0
        or change.change_ordinal != 0
        or change.started_event_ordinal >= change.completed_event_ordinal
    ):
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
    if change.kind != expected_kind:
        _reject(FILE_CHANGE_EVENT_LIFECYCLE_INVALID)
    if (
        change.path != expected_raw_path
        or change.normalized_path != _AUDIT_TOKEN + "\\" + _AUDIT_FILENAME
    ):
        _reject(FILE_CHANGE_PATH_UNSAFE)
    return change


def _lifecycle_payload(value: ClientFileChangePreflight) -> dict[str, object]:
    return {
        "raw_event_framing": "utf8-json-object-bytes-without-lf",
        "invocations": [
            {
                "bytes_sha256": value.add_bytes_sha256,
                "capture_sha256": value.add_capture_sha256,
                "completed_sha256": value.add_completed_sha256,
                "invocation_ordinal": 0,
                "kind": "add",
                "normalized_path": _AUDIT_FILENAME,
                "started_sha256": value.add_started_sha256,
            },
            {
                "bytes_sha256": value.update_bytes_sha256,
                "capture_sha256": value.update_capture_sha256,
                "completed_sha256": value.update_completed_sha256,
                "invocation_ordinal": 1,
                "kind": "update",
                "normalized_path": _AUDIT_FILENAME,
                "started_sha256": value.update_started_sha256,
            },
        ],
        "version": _LIFECYCLE_VERSION,
    }


def _preflight_payload(value: ClientFileChangePreflight) -> dict[str, object]:
    return {
        "add_bytes_sha256": value.add_bytes_sha256,
        "add_capture_identity": _identity_record(value.add_capture_identity),
        "add_capture_path": value.add_capture_path,
        "add_capture_sha256": value.add_capture_sha256,
        "add_capture_utf8_bytes": value.add_capture_utf8_bytes,
        "add_completed_sha256": value.add_completed_sha256,
        "add_started_sha256": value.add_started_sha256,
        "advertised_tools_sha256": value.advertised_tools_sha256,
        "after_add_snapshot": _snapshot_record(value.after_add_snapshot),
        "after_update_snapshot": _snapshot_record(value.after_update_snapshot),
        "audit_root": value.audit_root,
        "before_snapshot": _snapshot_record(value.before_snapshot),
        "lifecycle_contract_sha256": value.lifecycle_contract_sha256,
        "update_bytes_sha256": value.update_bytes_sha256,
        "update_capture_identity": _identity_record(value.update_capture_identity),
        "update_capture_path": value.update_capture_path,
        "update_capture_sha256": value.update_capture_sha256,
        "update_capture_utf8_bytes": value.update_capture_utf8_bytes,
        "update_completed_sha256": value.update_completed_sha256,
        "update_started_sha256": value.update_started_sha256,
        "version": value.version,
    }


def _validate_capture(value: object) -> CapturedLaunchInput:
    if type(value) is not CapturedLaunchInput:
        _reject(CLIENT_LAUNCH_INPUT_INVALID)
    try:
        value.__post_init__()
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError(CLIENT_LAUNCH_INPUT_INVALID) from exc
    return value


def _shell_json_object_pairs(
    pairs: list[tuple[str, object]],
) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
        result[key] = value
    return result


def _shell_reject_json_constant(_value: str) -> NoReturn:
    _reject(COMMAND_EVENT_LIFECYCLE_INVALID)


def _shell_decode_json_object(line: bytes) -> dict[str, object]:
    try:
        decoded = json.loads(
            line.decode("utf-8", errors="strict"),
            object_pairs_hook=_shell_json_object_pairs,
            parse_constant=_shell_reject_json_constant,
        )
    except RuntimeError as exc:
        if str(exc) == COMMAND_EVENT_LIFECYCLE_INVALID:
            raise
        if isinstance(exc, RecursionError):
            raise RuntimeError(COMMAND_EVENT_LIFECYCLE_INVALID) from None
        raise
    except (UnicodeError, ValueError, TypeError):
        raise RuntimeError(COMMAND_EVENT_LIFECYCLE_INVALID) from None
    if type(decoded) is not dict:
        _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
    return decoded


def _shell_json_string_spans(
    line: bytes,
) -> tuple[tuple[int, int, str], ...]:
    spans: list[tuple[int, int, str]] = []
    cursor = 0
    while cursor < len(line):
        if line[cursor] != 0x22:
            cursor += 1
            continue
        start = cursor
        cursor += 1
        while cursor < len(line):
            if line[cursor] == 0x5C:
                cursor += 2
                continue
            if line[cursor] == 0x22:
                cursor += 1
                try:
                    value = json.loads(
                        line[start:cursor].decode("utf-8", errors="strict")
                    )
                except (UnicodeError, ValueError, TypeError) as exc:
                    raise RuntimeError(
                        COMMAND_EVENT_LIFECYCLE_INVALID
                    ) from exc
                if type(value) is not str:
                    _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
                spans.append((start, cursor, value))
                break
            cursor += 1
        else:
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
    return tuple(spans)


def _shell_json_value_start(line: bytes, key_end: int) -> int | None:
    cursor = key_end
    while cursor < len(line) and line[cursor] in b" \t":
        cursor += 1
    if cursor >= len(line) or line[cursor] != 0x3A:
        return None
    cursor += 1
    while cursor < len(line) and line[cursor] in b" \t":
        cursor += 1
    return cursor


def _shell_json_object_end(
    line: bytes,
    start: int,
    spans_by_start: dict[int, tuple[int, str]],
) -> int:
    depth = 0
    cursor = start
    while cursor < len(line):
        string_span = spans_by_start.get(cursor)
        if string_span is not None:
            cursor = string_span[0]
            continue
        if line[cursor] == 0x7B:
            depth += 1
        elif line[cursor] == 0x7D:
            depth -= 1
            if depth == 0:
                return cursor + 1
            if depth < 0:
                break
        cursor += 1
    _reject(COMMAND_EVENT_LIFECYCLE_INVALID)


def _shell_normalize_item_id_span(
    line: bytes,
    *,
    expected_tool_item_id: str,
) -> bytes:
    spans = _shell_json_string_spans(line)
    spans_by_start = {
        start: (end, value) for start, end, value in spans
    }
    item_objects: list[tuple[int, int]] = []
    for _start, key_end, value in spans:
        if value != "item":
            continue
        object_start = _shell_json_value_start(line, key_end)
        if object_start is None or line[object_start : object_start + 1] != b"{":
            continue
        item_objects.append(
            (
                object_start,
                _shell_json_object_end(line, object_start, spans_by_start),
            )
        )
    if len(item_objects) != 1:
        _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
    object_start, object_end = item_objects[0]
    candidates: list[tuple[int, int]] = []
    for key_start, key_end, value in spans:
        if value != "id" or not object_start < key_start < object_end:
            continue
        value_start = _shell_json_value_start(line, key_end)
        value_span = spans_by_start.get(value_start) if value_start is not None else None
        if value_span is None or value_span[1] != expected_tool_item_id:
            continue
        candidates.append((value_start, value_span[0]))
    if len(candidates) != 1:
        _reject(COMMAND_EVENT_PAIR_MISMATCH)
    value_start, value_end = candidates[0]
    return (
        line[:value_start]
        + _canonical_json_bytes(_SHELL_NORMALIZED_ITEM_ID)
        + line[value_end:]
    )


def _decode_shell_client_capture(
    value: CapturedLaunchInput,
    *,
    shell: command_plan.ShellIdentity,
    expected_tool_item_id: str,
) -> _DecodedShellClientCapture:
    if (
        type(value) is not CapturedLaunchInput
        or type(shell) is not command_plan.ShellIdentity
        or type(expected_tool_item_id) is not str
        or not expected_tool_item_id
    ):
        _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
    try:
        capture = _validate_capture(value)
        content = capture.content
        if (
            not content
            or len(content) > _SHELL_CLIENT_CAPTURE_MAX_BYTES
            or not content.endswith(b"\n")
            or content.startswith(b"\xef\xbb\xbf")
            or b"\r" in content
            or b"\x00" in content
        ):
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
        lines = content[:-1].split(b"\n")
        if (
            not lines
            or len(lines) > _SHELL_CLIENT_EVENT_CAP
            or any(
                not line or len(line) > _SHELL_CLIENT_LINE_MAX_BYTES
                for line in lines
            )
        ):
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)

        command_events: list[
            tuple[int, str, bytes, dict[str, object]]
        ] = []
        for ordinal, line in enumerate(lines):
            event = _shell_decode_json_object(line)
            event_type = event.get("type")
            if type(event_type) is not str or not event_type:
                _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
            if event_type in _SHELL_PASSIVE_EVENT_TYPES:
                if "item" in event:
                    _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
                continue
            if event_type not in {"item.started", "item.completed"}:
                _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
            item = event.get("item")
            if type(item) is not dict:
                _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
            item_type = item.get("type")
            if type(item_type) is not str or not item_type:
                _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
            if item_type == "command_execution":
                if frozenset(event) != frozenset({"type", "item"}):
                    _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
                command_events.append((ordinal, event_type, line, item))
            elif item_type not in _SHELL_PASSIVE_ITEM_TYPES:
                _reject(COMMAND_EVENT_LIFECYCLE_INVALID)

        if (
            len(command_events) != 2
            or command_events[0][1] != "item.started"
            or command_events[1][1] != "item.completed"
            or command_events[0][0] >= command_events[1][0]
        ):
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
        started_ordinal, _started_type, started_line, started = command_events[0]
        completed_ordinal, _completed_type, completed_line, completed = (
            command_events[1]
        )
        if (
            frozenset(started) != _SHELL_COMMAND_ITEM_FIELDS
            or frozenset(completed) != _SHELL_COMMAND_ITEM_FIELDS
            or type(started["id"]) is not str
            or type(completed["id"]) is not str
            or type(started["command"]) is not str
            or type(completed["command"]) is not str
            or type(started["aggregated_output"]) is not str
            or type(completed["aggregated_output"]) is not str
            or started["aggregated_output"] != ""
            or started["exit_code"] is not None
            or started["status"] != "in_progress"
            or type(started["status"]) is not str
            or type(completed["exit_code"]) is not int
            or completed["exit_code"] != 0
            or type(completed["status"]) is not str
            or completed["status"] != "completed"
        ):
            _reject(COMMAND_EVENT_LIFECYCLE_INVALID)
        if (
            started["id"] != completed["id"]
            or started["id"] != expected_tool_item_id
            or started["command"] != completed["command"]
        ):
            _reject(COMMAND_EVENT_PAIR_MISMATCH)

        try:
            started_command_bytes = started["command"].encode("utf-8")
            completed_command_bytes = completed["command"].encode("utf-8")
        except UnicodeError:
            raise RuntimeError(COMMAND_EVENT_LIFECYCLE_INVALID) from None
        started_extracted = command_plan.extract_powershell_payload(
            started_command_bytes,
            shell=shell,
        )
        completed_extracted = command_plan.extract_powershell_payload(
            completed_command_bytes,
            shell=shell,
        )
        if (
            started_extracted != completed_extracted
            or started_extracted.payload != _SHELL_PREFLIGHT_PAYLOAD
        ):
            _reject(COMMAND_EVENT_PAIR_MISMATCH)

        normalized_started = _shell_normalize_item_id_span(
            started_line,
            expected_tool_item_id=expected_tool_item_id,
        )
        normalized_completed = _shell_normalize_item_id_span(
            completed_line,
            expected_tool_item_id=expected_tool_item_id,
        )
        normalized = normalized_started + b"\n" + normalized_completed + b"\n"
        try:
            output_bytes = completed["aggregated_output"].encode("utf-8")
        except UnicodeError:
            raise RuntimeError(COMMAND_EVENT_LIFECYCLE_INVALID) from None
        detached = CapturedLaunchInput(
            path=str(capture.path),
            content=bytes(capture.content),
            utf8_bytes=capture.utf8_bytes,
            sha256=str(capture.sha256),
            identity=_copy_identity(capture.identity),
        )
        return _DecodedShellClientCapture(
            capture=detached,
            tool_item_id=str(started["id"]),
            started_event_ordinal=started_ordinal,
            completed_event_ordinal=completed_ordinal,
            started_event_sha256=sha256(started_line).hexdigest(),
            completed_event_sha256=sha256(completed_line).hexdigest(),
            extracted=completed_extracted,
            aggregated_output_utf8_bytes=len(output_bytes),
            aggregated_output_sha256=sha256(output_bytes).hexdigest(),
            exit_code=completed["exit_code"],
            normalized_event_bytes=normalized,
            normalized_event_sha256=sha256(normalized).hexdigest(),
        )
    except RuntimeError as exc:
        code = str(exc)
        if code in {COMMAND_EVENT_LIFECYCLE_INVALID, COMMAND_EVENT_PAIR_MISMATCH}:
            raise
        if code == CLIENT_LAUNCH_INPUT_INVALID:
            raise RuntimeError(COMMAND_EVENT_LIFECYCLE_INVALID) from None
        if code in {
            command_plan.COMMAND_WRAPPER_INVALID,
            command_plan.COMMAND_WRAPPER_IDENTITY_MISMATCH,
            command_plan.COMMAND_PAYLOAD_LIMIT_EXCEEDED,
        }:
            raise RuntimeError(COMMAND_EVENT_PAIR_MISMATCH) from None
        raise


def _validate_repeated_shell_client_captures(
    first: CapturedLaunchInput,
    second: CapturedLaunchInput,
    *,
    shell: command_plan.ShellIdentity,
    expected_tool_item_ids: tuple[str, str],
) -> tuple[_DecodedShellClientCapture, _DecodedShellClientCapture]:
    if (
        type(expected_tool_item_ids) is not tuple
        or len(expected_tool_item_ids) != 2
        or any(
            type(item_id) is not str or not item_id
            for item_id in expected_tool_item_ids
        )
    ):
        _reject(COMMAND_EVENT_PAIR_MISMATCH)
    first_capture = _validate_capture(first)
    second_capture = _validate_capture(second)
    if (
        ntpath.normcase(ntpath.normpath(first_capture.path))
        == ntpath.normcase(ntpath.normpath(second_capture.path))
        or first_capture.sha256 == second_capture.sha256
        or first_capture.identity == second_capture.identity
    ):
        _reject(COMMAND_EVENT_PAIR_MISMATCH)
    decoded = (
        _decode_shell_client_capture(
            first_capture,
            shell=shell,
            expected_tool_item_id=expected_tool_item_ids[0],
        ),
        _decode_shell_client_capture(
            second_capture,
            shell=shell,
            expected_tool_item_id=expected_tool_item_ids[1],
        ),
    )
    if decoded[0].normalized_event_bytes != decoded[1].normalized_event_bytes:
        _reject(COMMAND_EVENT_PAIR_MISMATCH)
    return decoded


def validate_client_file_change_preflight(
    add_client_jsonl: CapturedLaunchInput,
    update_client_jsonl: CapturedLaunchInput,
    *,
    audit_root: Path,
    before_snapshot: FilesystemRootSnapshot,
    after_add_snapshot: FilesystemRootSnapshot,
    after_update_snapshot: FilesystemRootSnapshot,
    advertised_tools_sha256: str,
) -> ClientFileChangePreflight:
    add_capture = _validate_capture(add_client_jsonl)
    update_capture = _validate_capture(update_client_jsonl)
    if (
        not isinstance(audit_root, Path)
        or not _valid_absolute_path(str(audit_root))
        or audit_root.name != _AUDIT_ROOT_NAME
        or not _is_sha256(advertised_tools_sha256)
    ):
        _reject(FILE_CHANGE_PATH_UNSAFE)
    _validate_distinct_captures(
        add_path=add_capture.path,
        add_sha256=add_capture.sha256,
        add_identity=add_capture.identity,
        update_path=update_capture.path,
        update_sha256=update_capture.sha256,
        update_identity=update_capture.identity,
    )
    frozen_before = _copy_snapshot(before_snapshot)
    frozen_after_add = _copy_snapshot(after_add_snapshot)
    frozen_after_update = _copy_snapshot(after_update_snapshot)
    _validate_snapshot_contract(
        audit_root=audit_root,
        before_snapshot=frozen_before,
        after_add_snapshot=frozen_after_add,
        after_update_snapshot=frozen_after_update,
    )
    expected_raw_path = str(audit_root / _AUDIT_FILENAME)
    add_plan, add_raw_event_sha256 = _decode_preflight_capture(
        add_capture,
        audit_root=audit_root,
    )
    update_plan, update_raw_event_sha256 = _decode_preflight_capture(
        update_capture,
        audit_root=audit_root,
    )
    add_change = _validate_decoded_change(
        add_plan,
        expected_kind="add",
        expected_raw_path=expected_raw_path,
    )
    update_change = _validate_decoded_change(
        update_plan,
        expected_kind="update",
        expected_raw_path=expected_raw_path,
    )

    values: dict[str, object] = {
        "version": _PREFLIGHT_VERSION,
        "audit_root": str(audit_root),
        "before_snapshot": frozen_before,
        "after_add_snapshot": frozen_after_add,
        "after_update_snapshot": frozen_after_update,
        "add_capture_path": add_capture.path,
        "add_capture_utf8_bytes": add_capture.utf8_bytes,
        "add_capture_sha256": add_capture.sha256,
        "add_capture_identity": _copy_identity(add_capture.identity),
        "update_capture_path": update_capture.path,
        "update_capture_utf8_bytes": update_capture.utf8_bytes,
        "update_capture_sha256": update_capture.sha256,
        "update_capture_identity": _copy_identity(update_capture.identity),
        "add_started_sha256": add_raw_event_sha256[0],
        "add_completed_sha256": add_raw_event_sha256[1],
        "update_started_sha256": update_raw_event_sha256[0],
        "update_completed_sha256": update_raw_event_sha256[1],
        "add_bytes_sha256": sha256(_ADD_BYTES).hexdigest(),
        "update_bytes_sha256": sha256(_UPDATE_BYTES).hexdigest(),
        "advertised_tools_sha256": advertised_tools_sha256,
    }
    prototype = object.__new__(ClientFileChangePreflight)
    for name, value in values.items():
        object.__setattr__(prototype, name, value)
    lifecycle_sha256 = sha256(
        _canonical_json_bytes(_lifecycle_payload(prototype))
    ).hexdigest()
    object.__setattr__(prototype, "lifecycle_contract_sha256", lifecycle_sha256)
    canonical_sha256 = sha256(
        _canonical_json_bytes(_preflight_payload(prototype))
    ).hexdigest()
    return ClientFileChangePreflight(
        **values,
        lifecycle_contract_sha256=lifecycle_sha256,
        canonical_sha256=canonical_sha256,
    )


@dataclass(frozen=True)
class _GuardedCapturedFile:
    relative_path: str
    source_path: Path | None
    content: bytes
    source_identity: FilesystemObjectIdentity | None
    source_max_bytes: int | None
    owner: str | None


@dataclass(frozen=True)
class _GuardedDistributionSource:
    normalized_name: str
    version: str
    root: Path
    dist_info: Path
    metadata: bytes
    metadata_identity: FilesystemObjectIdentity
    record: bytes
    record_identity: FilesystemObjectIdentity
    requirements: tuple[str, ...]


@dataclass(frozen=True)
class _GuardedDistributionCopyPlan:
    source: _GuardedDistributionSource
    file_paths: tuple[str, ...]
    directory_paths: tuple[str, ...]
    omitted_launcher_paths: tuple[str, ...]
    omitted_inert_paths: tuple[str, ...]


@dataclass(frozen=True)
class _GuardedRecordClaim:
    relative_path: str
    relative: PurePosixPath
    expected_digest: str | None
    expected_size: int | None
    is_record: bool
    is_outside: bool


def _guarded_normalize_name(value: object) -> str:
    if type(value) is not str or not value or len(value) > 256:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    normalized = re.sub(r"[-_.]+", "-", value).casefold()
    if _GUARDED_NAME.fullmatch(normalized) is None:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return normalized


def _guarded_split_requirement(value: object) -> tuple[str, str, str | None]:
    if type(value) is not str or not value or len(value) > 4096 or "@" in value:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    requirement, separator, marker = value.partition(";")
    match = re.fullmatch(
        r"\s*([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[A-Za-z0-9._,-]+\])?\s*(.*?)\s*",
        requirement,
    )
    if match is None:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    specification = match.group(2)
    if specification and not re.fullmatch(
        r"(?:===|==|!=|~=|<=|>=|<|>)\s*[A-Za-z0-9*+!._-]+"
        r"(?:\s*,\s*(?:===|==|!=|~=|<=|>=|<|>)\s*[A-Za-z0-9*+!._-]+)*",
        specification,
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return (
        _guarded_normalize_name(match.group(1)),
        specification,
        marker.strip() if separator else None,
    )


_GUARDED_MARKER_TOKEN = re.compile(
    r"\s*(not\s+in\b|==|!=|<=|>=|<|>|\(|\)|\band\b|\bor\b|\bin\b|"
    r"[A-Za-z_][A-Za-z0-9_]*|'[^'\\]*'|\"[^\"\\]*\")",
    re.IGNORECASE,
)


def _guarded_marker_applies(marker: str | None, *, python_version: str) -> bool:
    if marker is None:
        return True
    tokens: list[str] = []
    offset = 0
    while offset < len(marker):
        match = _GUARDED_MARKER_TOKEN.match(marker, offset)
        if match is None or match.end() == offset:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        tokens.append(match.group(1))
        offset = match.end()
    position = 0
    facts = {
        "extra": "",
        "implementation_name": "cpython",
        "os_name": "nt",
        "platform_machine": "AMD64",
        "platform_python_implementation": "CPython",
        "platform_release": "",
        "platform_system": "Windows",
        "platform_version": "",
        "python_full_version": python_version,
        "python_version": ".".join(python_version.split(".")[:2]),
        "sys_platform": "win32",
    }

    def operand() -> tuple[str, bool]:
        nonlocal position
        if position >= len(tokens):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        token = tokens[position]
        position += 1
        if token[:1] in {"'", '"'}:
            return token[1:-1], False
        key = token.casefold()
        if key not in facts:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        return facts[key], key in {"python_version", "python_full_version"}

    def version_key(value: str) -> tuple[int, ...]:
        if not re.fullmatch(r"[0-9]+(?:\.[0-9]+)*", value):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        return tuple(int(part) for part in value.split("."))

    def comparison() -> bool:
        nonlocal position
        left, left_version = operand()
        if position >= len(tokens):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        operator = re.sub(r"\s+", " ", tokens[position].casefold())
        position += 1
        right, right_version = operand()
        if operator in {"in", "not in"}:
            result = left in right
            return not result if operator == "not in" else result
        if left_version or right_version:
            left_value: object = version_key(left)
            right_value: object = version_key(right)
        else:
            left_value = left.casefold()
            right_value = right.casefold()
        return {
            "==": left_value == right_value,
            "!=": left_value != right_value,
            "<": left_value < right_value,
            "<=": left_value <= right_value,
            ">": left_value > right_value,
            ">=": left_value >= right_value,
        }.get(operator, False)

    def atom() -> bool:
        nonlocal position
        if position < len(tokens) and tokens[position] == "(":
            position += 1
            result = disjunction()
            if position >= len(tokens) or tokens[position] != ")":
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            position += 1
            return result
        return comparison()

    def conjunction() -> bool:
        nonlocal position
        result = atom()
        while position < len(tokens) and tokens[position].casefold() == "and":
            position += 1
            following = atom()
            result = result and following
        return result

    def disjunction() -> bool:
        nonlocal position
        result = conjunction()
        while position < len(tokens) and tokens[position].casefold() == "or":
            position += 1
            following = conjunction()
            result = result or following
        return result

    result = disjunction()
    if position != len(tokens):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return result


def _guarded_version_key(value: str) -> tuple[int, ...]:
    match = re.match(r"[0-9]+(?:\.[0-9]+)*", value)
    if match is None:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return tuple(int(part) for part in match.group(0).split("."))


def _guarded_version_satisfies(version: str, specification: str) -> bool:
    if not specification:
        return True
    current = _guarded_version_key(version)
    for clause in specification.split(","):
        match = re.fullmatch(
            r"\s*(===|==|!=|~=|<=|>=|<|>)\s*([A-Za-z0-9*+!._-]+)\s*",
            clause,
        )
        if match is None:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        operator, expected_text = match.groups()
        wildcard = expected_text.endswith(".*")
        expected = _guarded_version_key(expected_text[:-2] if wildcard else expected_text)
        if wildcard:
            result = current[: len(expected)] == expected
        elif operator == "~=":
            upper = (expected[0] + 1,) if len(expected) == 1 else (*expected[:-2], expected[-2] + 1)
            result = current >= expected and current < upper
        else:
            result = {
                "===": current == expected,
                "==": current == expected,
                "!=": current != expected,
                "<": current < expected,
                "<=": current <= expected,
                ">": current > expected,
                ">=": current >= expected,
            }[operator]
        if not result:
            return False
    return True


def _guarded_parse_metadata(
    content: bytes,
) -> tuple[str, str, tuple[str, ...]]:
    if not content or len(content) > _GUARDED_FILE_BYTE_CAP or b"\x00" in content:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    try:
        message = BytesParser(policy=compat32).parsebytes(content)
    except BaseException as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    names = message.get_all("Name", [])
    versions = message.get_all("Version", [])
    requirements = message.get_all("Requires-Dist", [])
    if (
        len(names) != 1
        or len(versions) != 1
        or type(names[0]) is not str
        or type(versions[0]) is not str
        or not versions[0].strip()
        or len(versions[0].strip()) > 128
        or any(type(item) is not str for item in requirements)
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return (
        _guarded_normalize_name(names[0]),
        versions[0].strip(),
        tuple(item.strip() for item in requirements),
    )


def _guarded_capture_file(path: Path) -> tuple[bytes, FilesystemObjectIdentity]:
    content, identity = _validator_capture_plain_file(
        path,
        max_bytes=_GUARDED_FILE_BYTE_CAP,
    )
    if len(content) > _GUARDED_FILE_BYTE_CAP:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return content, identity


def _guarded_project_constraints(content: bytes) -> dict[str, tuple[str, ...]]:
    try:
        document = tomllib.loads(content.decode("utf-8", errors="strict"))
        project = document["project"]
        optional = project["optional-dependencies"]
        build_system = document["build-system"]
        groups = (
            (project["dependencies"], _GUARDED_PROJECT_RUNTIME_ROOTS),
            (optional["dev"], _GUARDED_PROJECT_DEV_ROOTS),
            (build_system["requires"], _GUARDED_PROJECT_BUILD_ROOTS),
        )
    except (KeyError, TypeError, UnicodeError, tomllib.TOMLDecodeError) as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    constraints: dict[str, list[str]] = {}
    for values, expected_names in groups:
        if type(values) is not list or any(type(item) is not str for item in values):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        parsed = tuple(_guarded_split_requirement(item) for item in values)
        if tuple(item[0] for item in parsed) != expected_names:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for name, specification, marker in parsed:
            if marker is not None:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            constraints.setdefault(name, []).append(specification)
    constraints.setdefault("pip", [])
    return {name: tuple(values) for name, values in constraints.items()}


def _guarded_catalog_distributions(
    roots: Sequence[Path],
) -> dict[str, tuple[_GuardedDistributionSource, ...]]:
    catalog: dict[str, list[_GuardedDistributionSource]] = {}
    seen_paths: set[str] = set()
    count = 0
    for root in roots:
        with os.scandir(root) as iterator:
            children = sorted(
                list(iterator),
                key=lambda item: (item.name.casefold(), item.name),
            )
        if len({item.name.casefold() for item in children}) != len(children):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for item in children:
            if not item.name.casefold().endswith(".dist-info"):
                continue
            count += 1
            if count > _GUARDED_CORE_ENTRY_CAP or item.is_symlink():
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            dist_info = Path(item.path)
            if not item.is_dir(follow_symlinks=False):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            _validator_plain_directory_identity(dist_info)
            metadata_path = dist_info / "METADATA"
            record_path = dist_info / "RECORD"
            record, record_identity = _guarded_capture_file(record_path)
            claims = _guarded_record_claims(record, dist_info.name)
            metadata_relative = f"{dist_info.name}/METADATA"
            metadata_claim = next(
                (
                    claim
                    for claim in claims
                    if claim.relative_path == metadata_relative
                ),
                None,
            )
            if (
                metadata_claim is None
                or metadata_claim.is_record
                or metadata_claim.is_outside
                or metadata_claim.expected_size is None
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            metadata, metadata_identity = _validator_capture_plain_file(
                metadata_path,
                max_bytes=max(metadata_claim.expected_size, 1),
            )
            if (
                len(metadata) != metadata_claim.expected_size
                or sha256(metadata).hexdigest() != metadata_claim.expected_digest
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            name, version, requirements = _guarded_parse_metadata(metadata)
            canonical = str(_validator_absolute_path(dist_info))
            key = ntpath.normcase(canonical)
            if key in seen_paths:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            seen_paths.add(key)
            catalog.setdefault(name, []).append(
                _GuardedDistributionSource(
                    normalized_name=name,
                    version=version,
                    root=root,
                    dist_info=dist_info,
                    metadata=metadata,
                    metadata_identity=metadata_identity,
                    record=record,
                    record_identity=record_identity,
                    requirements=requirements,
                )
            )
    return {name: tuple(values) for name, values in catalog.items()}


def _guarded_resolve_distribution_closure(
    catalog: dict[str, tuple[_GuardedDistributionSource, ...]],
    constraints: dict[str, tuple[str, ...]],
    *,
    python_version: str,
) -> tuple[_GuardedDistributionSource, ...]:
    pending = list(constraints)
    selected: dict[str, _GuardedDistributionSource] = {}
    all_constraints = {name: list(values) for name, values in constraints.items()}
    while pending:
        name = pending.pop(0)
        if name in selected:
            continue
        candidates = catalog.get(name, ())
        if len(candidates) != 1:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        source = candidates[0]
        if any(
            not _guarded_version_satisfies(source.version, specification)
            for specification in all_constraints.get(name, ())
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        selected[name] = source
        if len(selected) > _GUARDED_DISTRIBUTION_CAP:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for requirement in source.requirements:
            dependency, specification, marker = _guarded_split_requirement(requirement)
            if not _guarded_marker_applies(marker, python_version=python_version):
                continue
            all_constraints.setdefault(dependency, []).append(specification)
            if dependency in selected:
                if not _guarded_version_satisfies(
                    selected[dependency].version,
                    specification,
                ):
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            elif dependency not in pending:
                pending.append(dependency)
    return tuple(
        selected[name]
        for name in sorted(selected, key=lambda value: (value.casefold(), value))
    )


def _guarded_record_digest(value: str) -> str:
    if not value.startswith("sha256="):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    encoded = value.removeprefix("sha256=")
    try:
        decoded = base64.b64decode(
            encoded + "=" * (-len(encoded) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (ValueError, TypeError) as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    if len(decoded) != 32:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return decoded.hex()


def _guarded_record_member_claim(
    declared_hash: str,
    declared_size: str,
) -> tuple[str, int]:
    if (
        not declared_size
        or len(declared_size) > 20
        or not declared_size.isdecimal()
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    size = int(declared_size)
    if size > _GUARDED_FILE_BYTE_CAP:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return _guarded_record_digest(declared_hash), size


def _guarded_record_claims(
    record: bytes,
    dist_info_name: str,
) -> tuple[_GuardedRecordClaim, ...]:
    try:
        text = record.decode("utf-8", errors="strict")
        rows = list(csv.reader(io.StringIO(text, newline=""), strict=True))
    except (UnicodeError, csv.Error) as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    if not rows or len(rows) > _GUARDED_RUNTIME_ENTRY_CAP:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    record_relative = f"{dist_info_name}/RECORD"
    metadata_relative = f"{dist_info_name}/METADATA"
    seen: set[str] = set()
    claims: list[_GuardedRecordClaim] = []
    for row in rows:
        if len(row) != 3 or any(type(value) is not str for value in row):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        relative_path, declared_hash, declared_size = row
        if (
            not relative_path
            or "\\" in relative_path
            or "\x00" in relative_path
            or relative_path.casefold() in seen
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        seen.add(relative_path.casefold())
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or str(relative) != relative_path:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        is_record = relative_path == record_relative
        if is_record:
            if declared_hash or declared_size:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            expected_digest: str | None = None
            expected_size: int | None = None
        else:
            expected_digest, expected_size = _guarded_record_member_claim(
                declared_hash,
                declared_size,
            )
        is_outside = any(part == ".." for part in relative.parts)
        if is_outside:
            if relative.parts[:3] != ("..", "..", ".."):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        else:
            if any(part in {"", ".", ".."} for part in relative.parts):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            for part in relative.parts:
                _validator_win32_component_key(part)
        claims.append(
            _GuardedRecordClaim(
                relative_path=relative_path,
                relative=relative,
                expected_digest=expected_digest,
                expected_size=expected_size,
                is_record=is_record,
                is_outside=is_outside,
            )
        )
    if (
        sum(claim.is_record for claim in claims) != 1
        or not any(claim.relative_path == metadata_relative for claim in claims)
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return tuple(claims)


def _guarded_console_scripts(content: bytes | None) -> frozenset[str]:
    if content is None:
        return frozenset()
    try:
        lines = content.decode("utf-8", errors="strict").splitlines()
    except UnicodeError as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    section = ""
    names: set[str] = set()
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith(("#", ";")):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip().casefold()
            continue
        if section == "console_scripts":
            name, separator, _target = line.partition("=")
            name = name.strip()
            if not separator or not re.fullmatch(r"[A-Za-z0-9._-]+", name):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            names.add(name.casefold())
    return frozenset(names)


def _guarded_is_console_launcher(
    relative_path: str,
    console_scripts: frozenset[str],
) -> bool:
    parts = PurePosixPath(relative_path).parts
    if len(parts) != 5 or parts[:3] != ("..", "..", "..") or parts[3].casefold() != "scripts":
        return False
    filename = parts[4].casefold()
    return filename in {
        candidate
        for name in console_scripts
        for candidate in (f"{name}.exe", f"{name}-script.py")
    }


def _guarded_distribution_copy_plan(
    source: _GuardedDistributionSource,
    *,
    copies: dict[str, _GuardedCapturedFile],
    owned_casefold: dict[str, str],
) -> _GuardedDistributionCopyPlan:
    claims = _guarded_record_claims(source.record, source.dist_info.name)
    record_relative = f"{source.dist_info.name}/RECORD"
    metadata_relative = f"{source.dist_info.name}/METADATA"
    entry_points_relative = f"{source.dist_info.name}/entry_points.txt"
    pre_captured: dict[str, tuple[bytes, FilesystemObjectIdentity]] = {}
    entry_points_claim = next(
        (
            claim
            for claim in claims
            if claim.relative_path == entry_points_relative
        ),
        None,
    )
    if entry_points_claim is not None:
        if (
            entry_points_claim.is_record
            or entry_points_claim.is_outside
            or entry_points_claim.expected_size is None
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        entry_points_path = source.root.joinpath(*entry_points_claim.relative.parts)
        entry_points_content, entry_points_identity = _validator_capture_plain_file(
            entry_points_path,
            max_bytes=max(entry_points_claim.expected_size, 1),
        )
        if (
            len(entry_points_content) != entry_points_claim.expected_size
            or sha256(entry_points_content).hexdigest()
            != entry_points_claim.expected_digest
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        pre_captured[entry_points_relative] = (
            entry_points_content,
            entry_points_identity,
        )
    console_scripts = _guarded_console_scripts(
        None
        if entry_points_claim is None
        else pre_captured[entry_points_relative][0]
    )
    file_paths: list[str] = []
    omitted_launchers: list[str] = []
    omitted_inert: list[str] = []
    for claim in claims:
        relative_path = claim.relative_path
        relative = claim.relative
        if claim.is_outside:
            if not _guarded_is_console_launcher(relative_path, console_scripts):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            omitted_launchers.append(relative_path)
            continue
        source_path = source.root.joinpath(*relative.parts)
        if claim.is_record:
            content = source.record
            identity = source.record_identity
            source_max_bytes = max(len(content), 1)
        else:
            if claim.expected_digest is None or claim.expected_size is None:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            source_max_bytes = max(claim.expected_size, 1)
            captured = pre_captured.get(relative_path)
            if captured is None:
                content, identity = _validator_capture_plain_file(
                    source_path,
                    max_bytes=source_max_bytes,
                )
            else:
                content, identity = captured
            if (
                claim.expected_size != len(content)
                or claim.expected_digest != sha256(content).hexdigest()
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if relative_path == metadata_relative and (
            content != source.metadata or identity != source.metadata_identity
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if relative.suffix.casefold() == ".pyc" or any(
            part.casefold() == "__pycache__" for part in relative.parts
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if relative.suffix.casefold() == ".pth":
            if not (
                source.normalized_name == "setuptools"
                and relative_path == "distutils-precedence.pth"
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            omitted_inert.append(relative_path)
            continue
        key = relative_path.casefold()
        prior = owned_casefold.get(key)
        if prior is not None:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        owned_casefold[key] = source.normalized_name
        copies[relative_path] = _GuardedCapturedFile(
            relative_path=relative_path,
            source_path=source_path,
            content=content,
            source_identity=identity,
            source_max_bytes=source_max_bytes,
            owner=source.normalized_name,
        )
        file_paths.append(relative_path)
    if record_relative not in file_paths:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    directory_paths = {
        "/".join(PurePosixPath(path).parts[:index])
        for path in file_paths
        for index in range(1, len(PurePosixPath(path).parts))
    }
    return _GuardedDistributionCopyPlan(
        source=source,
        file_paths=tuple(sorted(file_paths, key=lambda value: (value.casefold(), value))),
        directory_paths=tuple(
            sorted(directory_paths, key=lambda value: (value.casefold(), value))
        ),
        omitted_launcher_paths=tuple(sorted(omitted_launchers)),
        omitted_inert_paths=tuple(sorted(omitted_inert)),
    )


def _guarded_source_member_can_affect_import(relative_path: str) -> bool:
    suffix = PurePosixPath(relative_path).suffix.casefold()
    return suffix in {
        ".dll",
        ".egg",
        ".pth",
        ".py",
        ".pyd",
        ".pyi",
        ".pyw",
        ".so",
        ".zip",
    }


def _guarded_validate_owned_source_trees(
    plans: tuple[_GuardedDistributionCopyPlan, ...],
) -> None:
    expected_by_root: dict[Path, dict[str, str]] = {}
    expected_directories_by_root: dict[Path, dict[str, str]] = {}
    top_levels_by_root: dict[Path, set[str]] = {}
    for plan in plans:
        expected = expected_by_root.setdefault(plan.source.root, {})
        expected_directories = expected_directories_by_root.setdefault(
            plan.source.root,
            {},
        )
        top_levels = top_levels_by_root.setdefault(plan.source.root, set())
        for relative_path in (*plan.file_paths, *plan.omitted_inert_paths):
            relative = PurePosixPath(relative_path)
            if (
                relative.is_absolute()
                or not relative.parts
                or any(part in {"", ".", ".."} for part in relative.parts)
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            key = relative_path.casefold()
            prior = expected.get(key)
            if prior is not None and prior != relative_path:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            expected[key] = relative_path
            top_levels.add(relative.parts[0])
            for index in range(1, len(relative.parts)):
                directory = "/".join(relative.parts[:index])
                directory_key = directory.casefold()
                prior_directory = expected_directories.get(directory_key)
                if prior_directory is not None and prior_directory != directory:
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                expected_directories[directory_key] = directory

    entry_count = 0
    for root in sorted(expected_by_root, key=lambda path: (str(path).casefold(), str(path))):
        expected = expected_by_root[root]
        expected_directories = expected_directories_by_root[root]
        for top_level in sorted(
            top_levels_by_root[root],
            key=lambda value: (value.casefold(), value),
        ):
            pending = [root / top_level]
            while pending:
                path = pending.pop()
                relative_path = path.relative_to(root).as_posix()
                entry_count += 1
                if entry_count > _GUARDED_RUNTIME_ENTRY_CAP:
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                _validator_win32_component_key(path.name)
                if path.is_symlink():
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                if path.is_dir():
                    if expected_directories.get(relative_path.casefold()) != relative_path:
                        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                    identity_before = _validator_plain_directory_identity(path)
                    with os.scandir(path) as iterator:
                        children = sorted(
                            list(iterator),
                            key=lambda item: (item.name.casefold(), item.name),
                        )
                    if (
                        len({item.name.casefold() for item in children})
                        != len(children)
                        or _validator_plain_directory_identity(path) != identity_before
                    ):
                        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                    for child in reversed(children):
                        if child.name.casefold() == "__pycache__":
                            continue
                        if child.is_symlink():
                            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                        if not (
                            child.is_dir(follow_symlinks=False)
                            or child.is_file(follow_symlinks=False)
                        ):
                            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                        pending.append(Path(child.path))
                    continue
                if not path.is_file():
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                if path.suffix.casefold() == ".pyc":
                    continue
                expected_path = expected.get(relative_path.casefold())
                if expected_path is not None:
                    if expected_path != relative_path:
                        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                    continue
                if _guarded_source_member_can_affect_import(relative_path):
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)


def _guarded_distribution_from_closed_runtime(
    source: _GuardedDistributionSource,
    runtime_site: dict[str, FrozenImportEntry],
) -> FrozenDistribution:
    claims = _guarded_record_claims(source.record, source.dist_info.name)
    entry_points_relative = f"{source.dist_info.name}/entry_points.txt"
    entry_points_claim = next(
        (
            claim
            for claim in claims
            if claim.relative_path == entry_points_relative
        ),
        None,
    )
    entry_points_content: bytes | None = None
    if entry_points_claim is not None:
        if (
            entry_points_claim.is_record
            or entry_points_claim.is_outside
            or entry_points_claim.expected_size is None
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        entry_points_content, entry_points_identity = _validator_capture_plain_file(
            source.root.joinpath(*entry_points_claim.relative.parts),
            max_bytes=max(entry_points_claim.expected_size, 1),
        )
        entry_points_entry = runtime_site.get(entry_points_relative)
        if (
            entry_points_entry is None
            or entry_points_entry.kind != "file"
            or entry_points_entry.byte_count != len(entry_points_content)
            or entry_points_entry.sha256
            != sha256(entry_points_content).hexdigest()
            or entry_points_entry.identity != entry_points_identity
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    console_scripts = _guarded_console_scripts(entry_points_content)
    file_paths: list[str] = []
    omitted_launchers: list[str] = []
    omitted_inert: list[str] = []
    for claim in claims:
        relative_path = claim.relative_path
        if claim.is_outside:
            if not _guarded_is_console_launcher(relative_path, console_scripts):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            omitted_launchers.append(relative_path)
            continue
        if claim.relative.suffix.casefold() == ".pyc" or any(
            part.casefold() == "__pycache__" for part in claim.relative.parts
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if claim.relative.suffix.casefold() == ".pth":
            if not (
                source.normalized_name == "setuptools"
                and relative_path == "distutils-precedence.pth"
                and relative_path not in runtime_site
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            omitted_inert.append(relative_path)
            continue
        entry = runtime_site.get(relative_path)
        if entry is None or entry.kind != "file":
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if claim.is_record:
            expected_size = len(source.record)
            expected_digest = sha256(source.record).hexdigest()
        else:
            expected_size = claim.expected_size
            expected_digest = claim.expected_digest
        if (
            expected_size is None
            or expected_digest is None
            or entry.byte_count != expected_size
            or entry.sha256 != expected_digest
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        file_paths.append(relative_path)
    directory_paths = {
        "/".join(PurePosixPath(path).parts[:index])
        for path in file_paths
        for index in range(1, len(PurePosixPath(path).parts))
    }
    if any(
        runtime_site.get(path) is None or runtime_site[path].kind != "directory"
        for path in directory_paths
    ):
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    entry_paths = set(file_paths) | directory_paths
    entries = tuple(
        runtime_site[path]
        for path in sorted(entry_paths, key=lambda value: (value.casefold(), value))
    )
    return _guarded_make_distribution(
        normalized_name=source.normalized_name,
        distribution_version=source.version,
        dist_info_relative_path=source.dist_info.name,
        metadata_sha256=sha256(source.metadata).hexdigest(),
        record_sha256=sha256(source.record).hexdigest(),
        omitted_launcher_paths=tuple(sorted(omitted_launchers)),
        omitted_inert_paths=tuple(sorted(omitted_inert)),
        entries=entries,
    )


def _guarded_capture_stdlib_tree(
    source_root: Path,
    *,
    output_prefix: str,
    copies: dict[str, _GuardedCapturedFile],
    directories: set[str],
) -> None:
    pending = [(source_root, PurePosixPath(output_prefix))]
    while pending:
        directory, relative_directory = pending.pop()
        _validator_plain_directory_identity(directory)
        with os.scandir(directory) as iterator:
            children = sorted(
                list(iterator),
                key=lambda item: (item.name.casefold(), item.name),
            )
        if len({item.name.casefold() for item in children}) != len(children):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for item in children:
            source_path = Path(item.path)
            relative = relative_directory / item.name
            relative_text = relative.as_posix()
            if item.is_symlink():
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            if item.name.casefold() in {"site-packages", "__pycache__"}:
                continue
            _validator_win32_component_key(item.name)
            if item.is_dir(follow_symlinks=False):
                directories.add(relative_text)
                pending.append((source_path, relative))
            elif item.is_file(follow_symlinks=False):
                if source_path.suffix.casefold() in {".pyc", ".pth"}:
                    continue
                content, identity = _guarded_capture_file(source_path)
                copies[relative_text] = _GuardedCapturedFile(
                    relative_path=relative_text,
                    source_path=source_path,
                    content=content,
                    source_identity=identity,
                    source_max_bytes=max(len(content), 1),
                    owner=None,
                )
            else:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)


def _guarded_frozen_entry(
    path: Path,
    *,
    relative_path: str,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> FrozenImportEntry:
    record = created_objects.get(path)
    if record is None:
        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
    return FrozenImportEntry(
        relative_path=relative_path,
        kind=record.kind,
        byte_count=0 if record.kind == "directory" else int(record.size),
        sha256=record.sha256,
        identity=_copy_identity(record.identity),
    )


def _guarded_entries_for_root(
    root: Path,
    *,
    created_objects: dict[Path, _ValidatorCreatedObject],
    direct_only: bool = False,
) -> tuple[FrozenImportEntry, ...]:
    entries: list[FrozenImportEntry] = []
    for path in created_objects:
        if path == root:
            continue
        if root not in path.parents:
            continue
        relative = path.relative_to(root)
        if direct_only and len(relative.parts) != 1:
            continue
        entries.append(
            _guarded_frozen_entry(
                path,
                relative_path=relative.as_posix(),
                created_objects=created_objects,
            )
        )
    return tuple(
        sorted(entries, key=lambda item: (item.relative_path.casefold(), item.relative_path))
    )


def _guarded_import_entry_from_snapshot(
    entry: FilesystemSnapshotEntry,
) -> FrozenImportEntry:
    return FrozenImportEntry(
        relative_path=entry.relative_path,
        kind=entry.kind,
        byte_count=entry.size,
        sha256=entry.sha256,
        identity=_copy_identity(entry.identity),
    )


def _freeze_guarded_python_runtime_core(
    *,
    python_path: Path,
    project_metadata: CapturedLaunchInput,
    expected_project_metadata_sha256: str,
    bootstrap_path: Path,
    expected_bootstrap_sha256: str,
    distribution_roots: Sequence[Path],
    bundle_root: Path,
    creation_session: file_change_policy._HeldNoFollowCreationSession | None,
    created_objects: dict[Path, _ValidatorCreatedObject] | None,
    owns_creation_authority: bool,
    shared_entry_cap: int | None,
    shared_byte_cap: int | None,
    shared_file_bytes: int,
) -> FrozenGuardedPythonRuntime:
    try:
        if (
            type(owns_creation_authority) is not bool
            or type(shared_file_bytes) is not int
            or shared_file_bytes < 0
            or (
                owns_creation_authority
                and (
                    creation_session is not None
                    or created_objects is not None
                    or shared_entry_cap is not None
                    or shared_byte_cap is not None
                    or shared_file_bytes != 0
                )
            )
            or (
                not owns_creation_authority
                and (
                    creation_session is None
                    or creation_session.closed
                    or type(created_objects) is not dict
                    or type(shared_entry_cap) is not int
                    or shared_entry_cap < 1
                    or type(shared_byte_cap) is not int
                    or shared_byte_cap < 0
                )
            )
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if not _is_sha256(expected_project_metadata_sha256) or not _is_sha256(
            expected_bootstrap_sha256
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        project = _validate_capture(project_metadata)
        python_source = _validator_absolute_path(python_path)
        output_parent = _validator_absolute_path(bundle_root, output=True)
        if not output_parent.is_dir() or output_parent.is_symlink():
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        _validator_plain_directory_identity(output_parent)
        runtime_root = _validator_absolute_path(
            output_parent / "guarded-python-runtime",
            output=True,
        )
        if runtime_root.exists() or runtime_root.is_symlink():
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if python_source.name.casefold() != "python.exe":
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        python_home = python_source.parent
        facts = _guarded_runtime_host_facts()
        if type(facts) is not dict or set(facts) != {
            "python_path",
            "python_version",
            "cache_tag",
            "distribution_roots",
        }:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        fact_python = facts["python_path"]
        python_version = facts["python_version"]
        cache_tag = facts["cache_tag"]
        fact_roots = facts["distribution_roots"]
        if (
            not isinstance(fact_python, Path)
            or _validator_absolute_path(fact_python) != python_source
            or type(python_version) is not str
            or not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", python_version)
            or type(cache_tag) is not str
            or not cache_tag
            or type(fact_roots) is not tuple
            or len(fact_roots) != 2
            or type(distribution_roots) not in {tuple, list}
            or len(distribution_roots) != 2
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        roots = tuple(_validator_absolute_path(path) for path in distribution_roots)
        expected_roots = tuple(_validator_absolute_path(path) for path in fact_roots)
        if roots != expected_roots or roots[0] == roots[1]:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        try:
            common = ntpath.commonpath((str(roots[0]), str(roots[1])))
        except ValueError as exc:
            raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
        if ntpath.normcase(common) in {
            ntpath.normcase(str(roots[0])),
            ntpath.normcase(str(roots[1])),
        }:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for root in roots:
            _validator_plain_directory_identity(root)

        source_root = Path(project.path).parent
        expected_project_path = source_root / "pyproject.toml"
        expected_bootstrap_path = (
            source_root
            / "tests"
            / "skills"
            / "complete_suite_release_python_bootstrap.py"
        )
        bootstrap_source = _validator_absolute_path(bootstrap_path)
        if (
            _validator_absolute_path(Path(project.path)) != expected_project_path
            or bootstrap_source != expected_bootstrap_path
            or project.sha256 != expected_project_metadata_sha256
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        project_content, project_identity = _guarded_capture_file(expected_project_path)
        if project_content != project.content or project_identity != project.identity:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        bootstrap_content, bootstrap_identity = _guarded_capture_file(bootstrap_source)
        if sha256(bootstrap_content).hexdigest() != expected_bootstrap_sha256:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        constraints = _guarded_project_constraints(project.content)

        copies: dict[str, _GuardedCapturedFile] = {}
        directories: set[str] = {"runtime-site"}
        present_stdlib_roles: list[str] = []
        for name in _GUARDED_REQUIRED_CORE_FILES:
            source_path = python_home / name
            content, identity = _guarded_capture_file(source_path)
            copies[name] = _GuardedCapturedFile(
                relative_path=name,
                source_path=source_path,
                content=content,
                source_identity=identity,
                source_max_bytes=max(len(content), 1),
                owner=None,
            )
        source_path = python_home / "python314.zip"
        if os.path.lexists(source_path):
            content, identity = _guarded_capture_file(source_path)
            copies["python314.zip"] = _GuardedCapturedFile(
                relative_path="python314.zip",
                source_path=source_path,
                content=content,
                source_identity=identity,
                source_max_bytes=max(len(content), 1),
                owner=None,
            )
            present_stdlib_roles.append("stdlib_zip")
        for role, directory_name in (
            ("stdlib_dlls", "DLLs"),
            ("stdlib_lib", "Lib"),
        ):
            source_directory = python_home / directory_name
            if not os.path.lexists(source_directory):
                continue
            _validator_plain_directory_identity(source_directory)
            directories.add(directory_name)
            _guarded_capture_stdlib_tree(
                source_directory,
                output_prefix=directory_name,
                copies=copies,
                directories=directories,
            )
            present_stdlib_roles.append(role)

        catalog = _guarded_catalog_distributions(roots)
        selected = _guarded_resolve_distribution_closure(
            catalog,
            constraints,
            python_version=python_version,
        )
        runtime_copies: dict[str, _GuardedCapturedFile] = {}
        owned_casefold: dict[str, str] = {}
        distribution_plans = tuple(
            _guarded_distribution_copy_plan(
                source,
                copies=runtime_copies,
                owned_casefold=owned_casefold,
            )
            for source in selected
        )
        _guarded_validate_owned_source_trees(distribution_plans)
        for relative, captured in runtime_copies.items():
            destination_relative = f"runtime-site/{relative}"
            if destination_relative.casefold() in {
                path.casefold() for path in copies
            }:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            copies[destination_relative] = _GuardedCapturedFile(
                relative_path=destination_relative,
                source_path=captured.source_path,
                content=captured.content,
                source_identity=captured.source_identity,
                source_max_bytes=captured.source_max_bytes,
                owner=captured.owner,
            )
        for plan in distribution_plans:
            directories.update(f"runtime-site/{path}" for path in plan.directory_paths)
        startup_sys_path_roles = (
            "python_home",
            *present_stdlib_roles,
            "runtime_site",
        )
        base_sys_path_roles = startup_sys_path_roles[:-1]
        pth_lines = ["."] + [
            _GUARDED_ROLE_RELATIVE_PATHS[role]
            for role in startup_sys_path_roles[1:]
        ]
        generated = {
            "python314._pth": ("\n".join(pth_lines) + "\n").encode("ascii"),
            "pyproject.toml": project.content,
            "complete_suite_release_python_bootstrap.py": bootstrap_content,
        }
        for relative, content in generated.items():
            copies[relative] = _GuardedCapturedFile(
                relative_path=relative,
                source_path=(
                    expected_project_path
                    if relative == "pyproject.toml"
                    else bootstrap_source
                    if relative == "complete_suite_release_python_bootstrap.py"
                    else None
                ),
                content=content,
                source_identity=(
                    project.identity
                    if relative == "pyproject.toml"
                    else bootstrap_identity
                    if relative == "complete_suite_release_python_bootstrap.py"
                    else None
                ),
                source_max_bytes=(
                    max(len(content), 1)
                    if relative != "python314._pth"
                    else None
                ),
                owner=None,
            )
        for relative in tuple(copies):
            pure = PurePosixPath(relative)
            for index in range(1, len(pure.parts)):
                directories.add("/".join(pure.parts[:index]))
            for part in pure.parts:
                _validator_win32_component_key(part)
        if len({path.casefold() for path in copies}) != len(copies) or any(
            path.casefold() in {item.casefold() for item in copies}
            for path in directories
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        runtime_entry_count = sum(
            1 for path in directories if path.startswith("runtime-site/")
        ) + len(runtime_copies)
        runtime_bytes = sum(len(item.content) for item in runtime_copies.values())
        core_entry_count = len(directories) + len(copies) - runtime_entry_count
        core_bytes = sum(len(item.content) for item in copies.values()) - runtime_bytes
        _guarded_validate_limits(
            distribution_count=len(selected),
            runtime_entry_count=runtime_entry_count,
            runtime_byte_count=runtime_bytes,
            core_entry_count=core_entry_count,
            core_byte_count=core_bytes,
            file_byte_count=max(len(item.content) for item in copies.values()),
            record_byte_bound=max(len(item.record) for item in selected),
        )

        if not owns_creation_authority:
            if (
                created_objects is None
                or shared_entry_cap is None
                or shared_byte_cap is None
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            existing_file_bytes = 0
            for record in created_objects.values():
                if record.kind == "file":
                    if type(record.size) is not int or record.size < 0:
                        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
                    existing_file_bytes += record.size
            planned_entry_count = len(directories) + len(copies) + 1
            planned_byte_count = runtime_bytes + core_bytes
            if (
                existing_file_bytes != shared_file_bytes
                or len(created_objects) - 1
                > shared_entry_cap - planned_entry_count
                or existing_file_bytes
                > shared_byte_cap - planned_byte_count
            ):
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

        if owns_creation_authority:
            created_objects = {}
            creation_session = file_change_policy._HeldNoFollowCreationSession(
                output_parent,
                code=GUARDED_PYTHON_RUNTIME_INVALID,
            )
        if creation_session is None or created_objects is None:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        root_identity = _validator_create_directory(
            runtime_root,
            creation_session=creation_session,
            created_objects=created_objects,
        )
        for relative in sorted(
            directories,
            key=lambda value: (
                len(PurePosixPath(value).parts),
                value.casefold(),
                value,
            ),
        ):
            _validator_create_directory(
                runtime_root.joinpath(*PurePosixPath(relative).parts),
                creation_session=creation_session,
                created_objects=created_objects,
            )
        for relative in sorted(copies, key=lambda value: (value.casefold(), value)):
            captured = copies[relative]
            if captured.source_path is not None:
                if captured.source_max_bytes is None:
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                _validator_revalidate_plain_file(
                    captured.source_path,
                    expected_content=captured.content,
                    expected_identity=captured.source_identity,
                    max_bytes=captured.source_max_bytes,
                )
            _validator_exclusive_write(
                runtime_root.joinpath(*PurePosixPath(relative).parts),
                captured.content,
                creation_session=creation_session,
                created_objects=created_objects,
            )
        if owns_creation_authority:
            for directory in sorted(
                (
                    path
                    for path, record in created_objects.items()
                    if record.kind == "directory"
                ),
                key=lambda path: len(path.parts),
                reverse=True,
            ):
                _validator_flush_directory(directory)
            _validator_flush_directory(output_parent)
            creation_session.revalidate_directories()
            creation_session.close()
            creation_session = None

        python_record = created_objects[runtime_root / "python.exe"]
        bootstrap_record = created_objects[
            runtime_root / "complete_suite_release_python_bootstrap.py"
        ]
        project_record = created_objects[runtime_root / "pyproject.toml"]
        frozen_bootstrap = CapturedLaunchInput(
            path=str(runtime_root / "complete_suite_release_python_bootstrap.py"),
            content=bootstrap_content,
            utf8_bytes=len(bootstrap_content),
            sha256=sha256(bootstrap_content).hexdigest(),
            identity=_copy_identity(bootstrap_record.identity),
        )
        frozen_project = CapturedLaunchInput(
            path=str(runtime_root / "pyproject.toml"),
            content=project.content,
            utf8_bytes=len(project.content),
            sha256=project.sha256,
            identity=_copy_identity(project_record.identity),
        )
        import_root_values = [
            _guarded_make_import_root(
                role="python_home",
                path=str(runtime_root),
                identity=_copy_identity(root_identity),
                entries=_guarded_entries_for_root(
                    runtime_root,
                    created_objects=created_objects,
                    direct_only=True,
                ),
            ),
        ]
        for role in present_stdlib_roles:
            relative_path = _GUARDED_ROLE_RELATIVE_PATHS[role]
            path = runtime_root / relative_path
            entries = (
                (
                    _guarded_frozen_entry(
                        path,
                        relative_path=relative_path,
                        created_objects=created_objects,
                    ),
                )
                if role == "stdlib_zip"
                else _guarded_entries_for_root(
                    path,
                    created_objects=created_objects,
                )
            )
            import_root_values.append(
                _guarded_make_import_root(
                    role=role,
                    path=str(path),
                    identity=_copy_identity(created_objects[path].identity),
                    entries=entries,
                )
            )
        import_root_values.append(
            _guarded_make_import_root(
                role="runtime_site",
                path=str(runtime_root / "runtime-site"),
                identity=_copy_identity(
                    created_objects[runtime_root / "runtime-site"].identity
                ),
                entries=_guarded_entries_for_root(
                    runtime_root / "runtime-site",
                    created_objects=created_objects,
                ),
            ),
        )
        import_roots = tuple(import_root_values)
        runtime_site_entries = {
            item.relative_path: item for item in import_roots[-1].entries
        }
        distributions: list[FrozenDistribution] = []
        for plan in distribution_plans:
            paths = set(plan.file_paths) | set(plan.directory_paths)
            entries = tuple(
                runtime_site_entries[path]
                for path in sorted(paths, key=lambda value: (value.casefold(), value))
            )
            distributions.append(
                _guarded_make_distribution(
                    normalized_name=plan.source.normalized_name,
                    distribution_version=plan.source.version,
                    dist_info_relative_path=plan.source.dist_info.name,
                    metadata_sha256=sha256(plan.source.metadata).hexdigest(),
                    record_sha256=sha256(plan.source.record).hexdigest(),
                    omitted_launcher_paths=plan.omitted_launcher_paths,
                    omitted_inert_paths=plan.omitted_inert_paths,
                    entries=entries,
                )
            )
        root_entries = _validator_capture_entries(
            runtime_root,
            max_entries=_GUARDED_CORE_ENTRY_CAP + _GUARDED_RUNTIME_ENTRY_CAP,
            max_bytes=_GUARDED_CORE_BYTE_CAP + _GUARDED_RUNTIME_BYTE_CAP,
        )
        values: dict[str, object] = {
            "version": _GUARDED_RUNTIME_VERSION,
            "root": str(runtime_root),
            "root_identity": _copy_identity(root_identity),
            "python_path": str(runtime_root / "python.exe"),
            "python_size": int(python_record.size),
            "python_sha256": python_record.sha256,
            "python_identity": _copy_identity(python_record.identity),
            "bootstrap": frozen_bootstrap,
            "project_metadata": frozen_project,
            "python_version": python_version,
            "cache_tag": cache_tag,
            "startup_sys_path_roles": startup_sys_path_roles,
            "base_sys_path_roles": base_sys_path_roles,
            "import_roots": import_roots,
            "distributions": tuple(distributions),
            "entry_count": len(root_entries),
            "byte_count": sum(entry.size for entry in root_entries if entry.kind == "file"),
        }
        prototype = object.__new__(FrozenGuardedPythonRuntime)
        for name, value in values.items():
            object.__setattr__(prototype, name, value)
        canonical = sha256(
            preparation.canonical_bytes(_guarded_runtime_payload(prototype))
        ).hexdigest()
        return validate_frozen_guarded_python_runtime(
            FrozenGuardedPythonRuntime(**values, canonical_sha256=canonical)
        )
    except RuntimeError as exc:
        if owns_creation_authority and creation_session is not None:
            creation_session.close()
        if str(exc) in {
            GUARDED_PYTHON_RUNTIME_INVALID,
            LAUNCH_PREFLIGHT_BUNDLE_INVALID,
        }:
            raise
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    except BaseException as exc:
        if owns_creation_authority and creation_session is not None:
            creation_session.close()
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc


def freeze_guarded_python_runtime(
    *,
    python_path: Path,
    project_metadata: CapturedLaunchInput,
    expected_project_metadata_sha256: str,
    bootstrap_path: Path,
    expected_bootstrap_sha256: str,
    distribution_roots: Sequence[Path],
    bundle_root: Path,
) -> FrozenGuardedPythonRuntime:
    return _freeze_guarded_python_runtime_core(
        python_path=python_path,
        project_metadata=project_metadata,
        expected_project_metadata_sha256=expected_project_metadata_sha256,
        bootstrap_path=bootstrap_path,
        expected_bootstrap_sha256=expected_bootstrap_sha256,
        distribution_roots=distribution_roots,
        bundle_root=bundle_root,
        creation_session=None,
        created_objects=None,
        owns_creation_authority=True,
        shared_entry_cap=None,
        shared_byte_cap=None,
        shared_file_bytes=0,
    )


def validate_frozen_guarded_python_runtime(
    runtime: FrozenGuardedPythonRuntime,
) -> FrozenGuardedPythonRuntime:
    try:
        if type(runtime) is not FrozenGuardedPythonRuntime:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        runtime.__post_init__()
        root = _validator_absolute_path(Path(runtime.root), output=True)
        if _validator_plain_directory_identity(root) != runtime.root_identity:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        python_content, python_identity = _guarded_capture_file(Path(runtime.python_path))
        if (
            len(python_content) != runtime.python_size
            or sha256(python_content).hexdigest() != runtime.python_sha256
            or python_identity != runtime.python_identity
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        for capture in (runtime.bootstrap, runtime.project_metadata):
            content, identity = _guarded_capture_file(Path(capture.path))
            if (
                content != capture.content
                or identity != capture.identity
                or sha256(content).hexdigest() != capture.sha256
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        actual_roots: list[tuple[FrozenImportEntry, ...]] = []
        for import_root in runtime.import_roots:
            path = _validator_absolute_path(Path(import_root.path), output=True)
            if import_root.role == "python_home":
                entries = tuple(
                    _guarded_import_entry_from_snapshot(entry)
                    for entry in _validator_capture_entries(
                        path,
                        max_entries=_GUARDED_CORE_ENTRY_CAP + _GUARDED_RUNTIME_ENTRY_CAP,
                        max_bytes=_GUARDED_CORE_BYTE_CAP + _GUARDED_RUNTIME_BYTE_CAP,
                    )
                    if "/" not in entry.relative_path
                )
                identity = _validator_plain_directory_identity(path)
            elif import_root.role == "stdlib_zip":
                content, identity = _guarded_capture_file(path)
                entries = (
                    FrozenImportEntry(
                        relative_path=path.name,
                        kind="file",
                        byte_count=len(content),
                        sha256=sha256(content).hexdigest(),
                        identity=_copy_identity(identity),
                    ),
                )
            else:
                identity = _validator_plain_directory_identity(path)
                entries = tuple(
                    _guarded_import_entry_from_snapshot(entry)
                    for entry in _validator_capture_entries(
                        path,
                        max_entries=(
                            _GUARDED_RUNTIME_ENTRY_CAP
                            if import_root.role == "runtime_site"
                            else _GUARDED_CORE_ENTRY_CAP
                        ),
                        max_bytes=(
                            _GUARDED_RUNTIME_BYTE_CAP
                            if import_root.role == "runtime_site"
                            else _GUARDED_CORE_BYTE_CAP
                        ),
                    )
                )
            if identity != import_root.identity or entries != import_root.entries:
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
            actual_roots.append(entries)
        expected_pth = (
            "\n".join(
                ["."]
                + [
                    _GUARDED_ROLE_RELATIVE_PATHS[role]
                    for role in runtime.startup_sys_path_roles[1:]
                ]
            )
            + "\n"
        ).encode("ascii")
        pth_content, _pth_identity = _guarded_capture_file(root / "python314._pth")
        if pth_content != expected_pth or b"import site" in pth_content:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        runtime_site = {item.relative_path: item for item in actual_roots[-1]}
        closed_catalog = _guarded_catalog_distributions((root / "runtime-site",))
        closed_selected = _guarded_resolve_distribution_closure(
            closed_catalog,
            _guarded_project_constraints(runtime.project_metadata.content),
            python_version=runtime.python_version,
        )
        if len(closed_selected) != sum(
            len(candidates) for candidates in closed_catalog.values()
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        expected_distributions = tuple(
            _guarded_distribution_from_closed_runtime(source, runtime_site)
            for source in closed_selected
        )
        if runtime.distributions != expected_distributions:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        owned_files: set[str] = set()
        for distribution in runtime.distributions:
            for entry in distribution.entries:
                if runtime_site.get(entry.relative_path) != entry:
                    _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                if entry.kind == "file":
                    if entry.relative_path in owned_files:
                        _reject(GUARDED_PYTHON_RUNTIME_INVALID)
                    owned_files.add(entry.relative_path)
            metadata = runtime_site.get(
                f"{distribution.dist_info_relative_path}/METADATA"
            )
            record = runtime_site.get(f"{distribution.dist_info_relative_path}/RECORD")
            if (
                metadata is None
                or record is None
                or metadata.sha256 != distribution.metadata_sha256
                or record.sha256 != distribution.record_sha256
            ):
                _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        if owned_files != {
            item.relative_path for item in actual_roots[-1] if item.kind == "file"
        }:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        root_entries = _validator_capture_entries(
            root,
            max_entries=_GUARDED_CORE_ENTRY_CAP + _GUARDED_RUNTIME_ENTRY_CAP,
            max_bytes=_GUARDED_CORE_BYTE_CAP + _GUARDED_RUNTIME_BYTE_CAP,
        )
        if (
            len(root_entries) != runtime.entry_count
            or sum(entry.size for entry in root_entries if entry.kind == "file")
            != runtime.byte_count
        ):
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        expected: dict[str, FrozenImportEntry] = {
            item.relative_path: item for item in actual_roots[0]
        }
        for import_root, entries in zip(runtime.import_roots[1:], actual_roots[1:]):
            if import_root.role == "stdlib_zip":
                continue
            prefix = _GUARDED_ROLE_RELATIVE_PATHS[import_root.role]
            for entry in entries:
                expected[f"{prefix}/{entry.relative_path}"] = FrozenImportEntry(
                    relative_path=f"{prefix}/{entry.relative_path}",
                    kind=entry.kind,
                    byte_count=entry.byte_count,
                    sha256=entry.sha256,
                    identity=entry.identity,
                )
        actual = {
            entry.relative_path: _guarded_import_entry_from_snapshot(entry)
            for entry in root_entries
        }
        if actual != expected:
            _reject(GUARDED_PYTHON_RUNTIME_INVALID)
        return runtime
    except RuntimeError as exc:
        if str(exc) == GUARDED_PYTHON_RUNTIME_INVALID:
            raise
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc
    except BaseException as exc:
        raise RuntimeError(GUARDED_PYTHON_RUNTIME_INVALID) from exc


def _validator_make_runtime(
    *,
    root: str,
    root_identity: FilesystemObjectIdentity,
    source_wheel_name: str,
    source_wheel_size: int,
    source_wheel_sha256: str,
    source_wheel_identity: FilesystemObjectIdentity,
    entries: tuple[FilesystemSnapshotEntry, ...],
) -> FrozenValidatorRuntime:
    prototype = object.__new__(FrozenValidatorRuntime)
    values: dict[str, object] = {
        "root": root,
        "root_identity": root_identity,
        "source_wheel_name": source_wheel_name,
        "source_wheel_size": source_wheel_size,
        "source_wheel_sha256": source_wheel_sha256,
        "source_wheel_identity": source_wheel_identity,
        "entries": entries,
    }
    for name, value in values.items():
        object.__setattr__(prototype, name, value)
    manifest_sha256 = sha256(
        preparation.canonical_bytes(_validator_runtime_payload(prototype))
    ).hexdigest()
    return FrozenValidatorRuntime(
        **values,
        manifest_sha256=manifest_sha256,
    )


def _validator_make_bundle(
    *,
    root: str,
    root_identity: FilesystemObjectIdentity,
    inputs: tuple[FrozenValidatorInput, ...],
    runtime: FrozenValidatorRuntime,
) -> FrozenValidatorBundle:
    prototype = object.__new__(FrozenValidatorBundle)
    values: dict[str, object] = {
        "root": root,
        "root_identity": root_identity,
        "inputs": inputs,
        "runtime": runtime,
    }
    for name, value in values.items():
        object.__setattr__(prototype, name, value)
    manifest_sha256 = sha256(
        preparation.canonical_bytes(_validator_bundle_payload(prototype))
    ).hexdigest()
    return FrozenValidatorBundle(
        **values,
        manifest_sha256=manifest_sha256,
    )


def _validator_copy_entry(
    entry: FilesystemSnapshotEntry,
    *,
    relative_path: str | None = None,
) -> FilesystemSnapshotEntry:
    return FilesystemSnapshotEntry(
        relative_path=(
            entry.relative_path if relative_path is None else relative_path
        ),
        kind=entry.kind,
        size=entry.size,
        sha256=entry.sha256,
        link_count=entry.link_count,
        identity=_copy_identity(entry.identity),
    )


def _validator_expected_runtime_entries(
    plan: _ValidatorWheelPlan,
    runtime_root: Path,
    created_objects: dict[Path, _ValidatorCreatedObject],
) -> tuple[FilesystemSnapshotEntry, ...]:
    members = {member.name: member for member in plan.members}
    entries: list[FilesystemSnapshotEntry] = []
    for relative_path in plan.expected_paths:
        path = runtime_root.joinpath(*relative_path.split("/"))
        record = created_objects.get(path)
        member = members.get(relative_path)
        expected_kind: Literal["file", "directory"] = (
            "file" if member is not None else "directory"
        )
        if record is None or record.kind != expected_kind:
            _validator_reject()
        entries.append(
            FilesystemSnapshotEntry(
                relative_path=relative_path,
                kind=expected_kind,
                size=0 if member is None else member.size,
                sha256=None if member is None else member.sha256,
                link_count=record.identity.link_count,
                identity=_copy_identity(record.identity),
            )
        )
    return tuple(entries)


def _validator_expected_bundle_entries(
    bundle: FrozenValidatorBundle,
) -> tuple[FilesystemSnapshotEntry, ...]:
    entries: list[FilesystemSnapshotEntry] = []
    for item in bundle.inputs:
        entries.append(
            FilesystemSnapshotEntry(
                relative_path=Path(item.bundle_path).name,
                kind="file",
                size=item.size,
                sha256=item.sha256,
                link_count=item.identity.link_count,
                identity=_copy_identity(item.identity),
            )
        )
    entries.append(
        FilesystemSnapshotEntry(
            relative_path="runtime",
            kind="directory",
            size=0,
            sha256=None,
            link_count=bundle.runtime.root_identity.link_count,
            identity=_copy_identity(bundle.runtime.root_identity),
        )
    )
    entries.extend(
        _validator_copy_entry(
            entry,
            relative_path=f"runtime/{entry.relative_path}",
        )
        for entry in bundle.runtime.entries
    )
    return tuple(
        sorted(
            entries,
            key=lambda entry: (entry.relative_path.casefold(), entry.relative_path),
        )
    )


def _validator_detached_bundle(
    bundle: FrozenValidatorBundle,
) -> FrozenValidatorBundle:
    inputs = tuple(
        FrozenValidatorInput(
            role=item.role,
            bundle_path=item.bundle_path,
            source_locator=item.source_locator,
            size=item.size,
            sha256=item.sha256,
            identity=_copy_identity(item.identity),
        )
        for item in bundle.inputs
    )
    runtime = _validator_make_runtime(
        root=bundle.runtime.root,
        root_identity=_copy_identity(bundle.runtime.root_identity),
        source_wheel_name=bundle.runtime.source_wheel_name,
        source_wheel_size=bundle.runtime.source_wheel_size,
        source_wheel_sha256=bundle.runtime.source_wheel_sha256,
        source_wheel_identity=_copy_identity(
            bundle.runtime.source_wheel_identity
        ),
        entries=tuple(_validator_copy_entry(entry) for entry in bundle.runtime.entries),
    )
    detached = _validator_make_bundle(
        root=bundle.root,
        root_identity=_copy_identity(bundle.root_identity),
        inputs=inputs,
        runtime=runtime,
    )
    if detached.manifest_sha256 != bundle.manifest_sha256:
        _validator_reject()
    return detached


def freeze_validator_bundle(
    *,
    codex_home: Path,
    pyyaml_wheel: Path,
    output_root: Path,
) -> FrozenValidatorBundle:
    created_objects: dict[Path, _ValidatorCreatedObject] = {}
    created_root_identity: FilesystemObjectIdentity | None = None
    creation_session: (
        file_change_policy._HeldNoFollowCreationSession | None
    ) = None
    try:
        codex_root = _validator_absolute_path(codex_home)
        wheel_path = _validator_absolute_path(pyyaml_wheel)
        bundle_root = _validator_absolute_path(output_root, output=True)
        codex_identity = _validator_plain_directory_identity(codex_root)
        source_records: list[
            tuple[
                Literal["plugin", "skill"],
                str,
                str,
                Path,
                bytes,
                FilesystemObjectIdentity,
            ]
        ] = []
        script_total = 0
        for raw_role, locator, bundle_name in _VALIDATOR_SOURCE_LOCATORS:
            role: Literal["plugin", "skill"] = raw_role
            source_path = codex_root.joinpath(*PurePosixPath(locator).parts)
            content, identity = _validator_capture_plain_file(
                source_path,
                max_bytes=_VALIDATOR_SCRIPT_CAP_BYTES,
            )
            if not content:
                _validator_reject()
            script_total += len(content)
            if script_total > _VALIDATOR_SCRIPT_AGGREGATE_CAP_BYTES:
                _validator_reject()
            source_records.append(
                (role, locator, bundle_name, source_path, content, identity)
            )
        if wheel_path.name != _VALIDATOR_WHEEL_NAME:
            _validator_reject()
        wheel_content, wheel_identity = _validator_capture_plain_file(
            wheel_path,
            max_bytes=_VALIDATOR_WHEEL_SIZE,
        )
        if (
            len(wheel_content) != _VALIDATOR_WHEEL_SIZE
            or sha256(wheel_content).hexdigest() != _VALIDATOR_WHEEL_SHA256
        ):
            _validator_reject()
        wheel_plan = _validator_preflight_wheel(wheel_content)
        runtime_root = bundle_root / "runtime"
        for relative_path in wheel_plan.expected_paths:
            destination = runtime_root.joinpath(*relative_path.split("/"))
            try:
                destination_units = len(
                    str(destination).encode("utf-16-le", errors="strict")
                ) // 2
            except UnicodeEncodeError as exc:
                _validator_reject(exc)
            if destination_units > _MAX_PATH_CHARS:
                _validator_reject()

        _validator_freeze_checkpoint("after-input-capture", wheel_path)
        if _validator_plain_directory_identity(codex_root) != codex_identity:
            _validator_reject()
        for _role, _locator, _bundle_name, path, content, identity in source_records:
            _validator_revalidate_plain_file(
                path,
                expected_content=content,
                expected_identity=identity,
                max_bytes=_VALIDATOR_SCRIPT_CAP_BYTES,
            )
        _validator_revalidate_plain_file(
            wheel_path,
            expected_content=wheel_content,
            expected_identity=wheel_identity,
            max_bytes=_VALIDATOR_WHEEL_SIZE,
        )
        if bundle_root.exists() or bundle_root.is_symlink():
            _validator_reject()
        parent_identity = _validator_plain_directory_identity(bundle_root.parent)
        creation_session = file_change_policy._HeldNoFollowCreationSession(
            bundle_root.parent,
            code=VALIDATOR_BUNDLE_INVALID,
        )
        created_root_identity = _validator_create_directory(
            bundle_root,
            creation_session=creation_session,
            created_objects=created_objects,
        )
        _validator_create_directory(
            runtime_root,
            creation_session=creation_session,
            created_objects=created_objects,
        )
        for _role, _locator, bundle_name, _path, content, _identity in source_records:
            _validator_exclusive_write(
                bundle_root / bundle_name,
                content,
                creation_session=creation_session,
                created_objects=created_objects,
            )
        _validator_extract_wheel(
            wheel_content,
            wheel_plan.members,
            runtime_root,
            creation_session=creation_session,
            created_objects=created_objects,
        )
        created_directories = tuple(
            sorted(
                (
                    path
                    for path, record in created_objects.items()
                    if record.kind == "directory"
                ),
                key=lambda path: len(path.parts),
                reverse=True,
            )
        )
        for created_directory in created_directories:
            _validator_flush_directory(created_directory)
        _validator_flush_directory(bundle_root.parent)
        creation_session.revalidate_directories()
        _validator_freeze_checkpoint("after-output-write", bundle_root)
        creation_session.revalidate_directories()

        if (
            _validator_plain_directory_identity(codex_root) != codex_identity
            or _validator_plain_directory_identity(bundle_root.parent)
            != parent_identity
            or _validator_plain_directory_identity(bundle_root)
            != created_root_identity
        ):
            _validator_reject()
        for _role, _locator, _bundle_name, path, content, identity in source_records:
            _validator_revalidate_plain_file(
                path,
                expected_content=content,
                expected_identity=identity,
                max_bytes=_VALIDATOR_SCRIPT_CAP_BYTES,
            )
        _validator_revalidate_plain_file(
            wheel_path,
            expected_content=wheel_content,
            expected_identity=wheel_identity,
            max_bytes=_VALIDATOR_WHEEL_SIZE,
        )

        runtime_identity = _validator_plain_directory_identity(runtime_root)
        runtime_creation = created_objects.get(runtime_root)
        if (
            runtime_creation is None
            or runtime_creation.kind != "directory"
            or runtime_creation.identity != runtime_identity
        ):
            _validator_reject()
        runtime_entries = _validator_capture_entries(
            runtime_root,
            max_entries=_VALIDATOR_RUNTIME_ENTRY_CAP,
            max_bytes=_VALIDATOR_ZIP_AGGREGATE_CAP_BYTES,
        )
        if runtime_entries != _validator_expected_runtime_entries(
            wheel_plan,
            runtime_root,
            created_objects,
        ):
            _validator_reject()
        runtime = _validator_make_runtime(
            root=str(runtime_root),
            root_identity=_copy_identity(runtime_identity),
            source_wheel_name=_VALIDATOR_WHEEL_NAME,
            source_wheel_size=len(wheel_content),
            source_wheel_sha256=sha256(wheel_content).hexdigest(),
            source_wheel_identity=_copy_identity(wheel_identity),
            entries=runtime_entries,
        )
        inputs: list[FrozenValidatorInput] = []
        for role, locator, bundle_name, _path, content, _identity in source_records:
            destination = bundle_root / bundle_name
            copied, copied_identity = _validator_capture_plain_file(
                destination,
                max_bytes=_VALIDATOR_SCRIPT_CAP_BYTES,
            )
            if copied != content:
                _validator_reject()
            creation = created_objects.get(destination)
            if (
                creation is None
                or creation.kind != "file"
                or creation.identity != copied_identity
            ):
                _validator_reject()
            inputs.append(
                FrozenValidatorInput(
                    role=role,
                    bundle_path=str(destination),
                    source_locator=locator,
                    size=len(copied),
                    sha256=sha256(copied).hexdigest(),
                    identity=_copy_identity(copied_identity),
                )
            )
        bundle = _validator_make_bundle(
            root=str(bundle_root),
            root_identity=_copy_identity(created_root_identity),
            inputs=tuple(inputs),
            runtime=runtime,
        )
        captured_bundle_entries = _validator_capture_entries(
            bundle_root,
            max_entries=_VALIDATOR_RUNTIME_ENTRY_CAP + 3,
            max_bytes=(
                _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
                + _VALIDATOR_SCRIPT_AGGREGATE_CAP_BYTES
            ),
        )
        if captured_bundle_entries != _validator_expected_bundle_entries(bundle):
            _validator_reject()
        creation_session.revalidate_directories()
        creation_session.close()
        creation_session = None
        return validate_frozen_validator_bundle(bundle)
    except RuntimeError as exc:
        root_creation = created_objects.get(output_root)
        cleanup_identity = created_root_identity
        if cleanup_identity is None and root_creation is not None:
            cleanup_identity = root_creation.identity
        if cleanup_identity is not None:
            _validator_remove_created_root(
                output_root,
                expected_root_identity=cleanup_identity,
                created_objects=created_objects,
                creation_session=creation_session,
            )
        if creation_session is not None:
            creation_session.close()
            creation_session = None
        if str(exc) == VALIDATOR_BUNDLE_INVALID:
            raise
        _validator_reject(exc)
    except BaseException as exc:
        root_creation = created_objects.get(output_root)
        cleanup_identity = created_root_identity
        if cleanup_identity is None and root_creation is not None:
            cleanup_identity = root_creation.identity
        if cleanup_identity is not None:
            _validator_remove_created_root(
                output_root,
                expected_root_identity=cleanup_identity,
                created_objects=created_objects,
                creation_session=creation_session,
            )
        if creation_session is not None:
            creation_session.close()
            creation_session = None
        _validator_reject(exc)


def validate_frozen_validator_bundle(
    bundle: FrozenValidatorBundle,
) -> FrozenValidatorBundle:
    try:
        if type(bundle) is not FrozenValidatorBundle:
            _validator_reject()
        bundle.__post_init__()
        root = _validator_absolute_path(Path(bundle.root), output=True)
        if _validator_plain_directory_identity(root) != bundle.root_identity:
            _validator_reject()
        for item in bundle.inputs:
            expected_path = root / Path(item.bundle_path).name
            if str(expected_path) != item.bundle_path:
                _validator_reject()
            content, identity = _validator_capture_plain_file(
                expected_path,
                max_bytes=_VALIDATOR_SCRIPT_CAP_BYTES,
            )
            if (
                len(content) != item.size
                or sha256(content).hexdigest() != item.sha256
                or identity != item.identity
            ):
                _validator_reject()
        runtime_root = root / "runtime"
        if (
            str(runtime_root) != bundle.runtime.root
            or _validator_plain_directory_identity(runtime_root)
            != bundle.runtime.root_identity
        ):
            _validator_reject()
        runtime_entries = _validator_capture_entries(
            runtime_root,
            max_entries=_VALIDATOR_RUNTIME_ENTRY_CAP,
            max_bytes=_VALIDATOR_ZIP_AGGREGATE_CAP_BYTES,
        )
        if runtime_entries != bundle.runtime.entries:
            _validator_reject()
        all_entries = _validator_capture_entries(
            root,
            max_entries=_VALIDATOR_RUNTIME_ENTRY_CAP + 3,
            max_bytes=(
                _VALIDATOR_ZIP_AGGREGATE_CAP_BYTES
                + _VALIDATOR_SCRIPT_AGGREGATE_CAP_BYTES
            ),
        )
        if all_entries != _validator_expected_bundle_entries(bundle):
            _validator_reject()
        return _validator_detached_bundle(bundle)
    except RuntimeError as exc:
        if str(exc) == VALIDATOR_BUNDLE_INVALID:
            raise
        _validator_reject(exc)
    except BaseException as exc:
        _validator_reject(exc)


