@dataclass(frozen=True)
class FrozenCodexClientIdentity:
    version: Literal["complete-suite-codex-client-identity-v1"]
    executable_path: str
    executable_size: int
    executable_sha256: str
    executable_identity: FilesystemObjectIdentity
    distribution_manifest: CapturedLaunchInput
    platform_manifest: CapturedLaunchInput
    distribution_name: Literal["@openai/codex"]
    distribution_version: Literal["0.149.0"]
    platform_package_key: Literal["@openai/codex-win32-x64"]
    platform_name: Literal["@openai/codex"]
    platform_version: Literal["0.149.0-win32-x64"]
    client_label: Literal["codex-cli 0.149.0"]
    canonical_sha256: str

    def __post_init__(self) -> None:
        if (
            self.version != "complete-suite-codex-client-identity-v1"
            or self.distribution_name != "@openai/codex"
            or self.distribution_version != "0.149.0"
            or self.platform_package_key != "@openai/codex-win32-x64"
            or self.platform_name != "@openai/codex"
            or self.platform_version != "0.149.0-win32-x64"
            or self.client_label != "codex-cli 0.149.0"
            or type(self.executable_size) is not int
            or self.executable_size < 1
            or not _is_sha256(self.executable_sha256)
            or not _is_sha256(self.canonical_sha256)
            or type(self.distribution_manifest) is not CapturedLaunchInput
            or type(self.platform_manifest) is not CapturedLaunchInput
            or self.distribution_manifest.path == self.platform_manifest.path
            or self.distribution_manifest.identity
            == self.platform_manifest.identity
        ):
            _launch_reject()
        _launch_absolute_path(self.executable_path)
        try:
            _validate_plain_identity(
                self.executable_identity,
                code=COMMAND_LAUNCH_SPEC_MISMATCH,
            )
            self.distribution_manifest.__post_init__()
            self.platform_manifest.__post_init__()
        except BaseException as exc:
            if (
                isinstance(exc, RuntimeError)
                and str(exc) == COMMAND_LAUNCH_SPEC_MISMATCH
            ):
                raise
            _launch_reject(exc)
        if self.canonical_sha256 != sha256(
            _canonical_json_bytes(_frozen_codex_identity_payload(self))
        ).hexdigest():
            _launch_reject()


