def _native_leaf_compact_ascii_array(
    records: tuple[dict[str, object], ...],
) -> bytes:
    if (
        type(records) is not tuple
        or not records
        or any(type(record) is not dict for record in records)
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    try:
        return json.dumps(
            list(records),
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=False,
            separators=(",", ":"),
        ).encode("ascii", errors="strict")
    except (UnicodeError, TypeError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc


