_NATIVE_LEAF_CONSTRUCTOR_SOURCE_CAP_BYTES = 4 * 1024 * 1024
_NATIVE_LEAF_CONSTRUCTOR_SOURCE_FRAGMENTS_VERSION = (
    "complete-suite-native-leaf-constructor-source-fragments-v1"
)
_NATIVE_LEAF_CONSTRUCTOR_IMPLEMENTATION_FRAGMENT_VERSION = (
    "complete-suite-native-leaf-constructor-implementation-fragment-v1"
)
_NATIVE_LEAF_CONSTRUCTOR_REGISTRY_FRAGMENT_VERSION = (
    "complete-suite-native-leaf-constructor-registry-fragment-v1"
)
_NATIVE_LEAF_CONSTRUCTOR_MINIMUM_BODY_BYTES = 128
_HOST_NATIVE_VECTOR_SOURCE_FRAGMENT_VERSION = (
    "complete-suite-host-native-vector-source-fragment-v1"
)
_HOST_NATIVE_VECTOR_FUNCTION_NAMES = (
    "Assert-C6HostNativeVectorString",
    "ConvertTo-C6HostNativeArgument",
    "New-C6HostNativeVector",
)
_HOST_NATIVE_VECTOR_SOURCE_BYTES = rb"""function Assert-C6HostNativeVectorString {
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyString()]
        [object]$Value
    )
    if ($null -eq $Value) { throw 'host native vector contains null string' }
    if ($Value -isnot [string]) {
        throw 'host native vector value is not a string'
    }
    [string]$text=$Value
    for ($index=0; $index -lt $text.Length; $index++) {
        $character=$text[$index]
        if ($character -eq [char]0) { throw 'host native vector contains NUL' }
        if ([char]::IsHighSurrogate($character)) {
            if ($index + 1 -ge $text.Length -or
                -not [char]::IsLowSurrogate($text[$index + 1])) {
                throw 'host native vector contains unpaired high surrogate'
            }
            $index++
        } elseif ([char]::IsLowSurrogate($character)) {
            throw 'host native vector contains unpaired low surrogate'
        }
    }
}

function ConvertTo-C6HostNativeArgument {
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyString()]
        [object]$Value
    )
    Assert-C6HostNativeVectorString -Value $Value
    [string]$text=$Value
    $requiresQuotes=($text.Length -eq 0)
    if (-not $requiresQuotes) {
        foreach ($character in $text.ToCharArray()) {
            if ($character -eq '"' -or $character -eq ' ' -or
                $character -eq [char]9) {
                $requiresQuotes=$true
                break
            }
        }
    }
    if (-not $requiresQuotes) { return $text }
    $builder=[Text.StringBuilder]::new()
    [void]$builder.Append('"')
    $backslashes=0
    foreach ($character in $text.ToCharArray()) {
        if ($character -eq '\') {
            $backslashes++
            continue
        }
        if ($character -eq '"') {
            if ($backslashes -gt 0) {
                [void]$builder.Append(('\' * (2 * $backslashes)))
            }
            [void]$builder.Append('\')
            [void]$builder.Append('"')
            $backslashes=0
            continue
        }
        if ($backslashes -gt 0) {
            [void]$builder.Append(('\' * $backslashes))
            $backslashes=0
        }
        [void]$builder.Append($character)
    }
    if ($backslashes -gt 0) {
        [void]$builder.Append(('\' * (2 * $backslashes)))
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function New-C6HostNativeVector {
    param(
        [Parameter(Mandatory)][AllowNull()][object]$Executable,
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyCollection()]
        [object]$ArgumentList
    )
    Assert-C6HostNativeVectorString -Value $Executable
    [string]$executableText=$Executable
    if ($executableText.Length -eq 0 -or
        -not [IO.Path]::IsPathFullyQualified($executableText) -or
        [IO.Path]::GetFullPath($executableText) -cne $executableText) {
        throw 'host native vector executable is not canonical absolute'
    }
    if ($null -eq $ArgumentList -or $ArgumentList -isnot [object[]]) {
        throw 'host native vector argument list is not an array'
    }
    $serialized=[Collections.Generic.List[string]]::new()
    [void]$serialized.Add(
        (ConvertTo-C6HostNativeArgument -Value $executableText)
    )
    foreach ($argument in [object[]]$ArgumentList) {
        [void]$serialized.Add(
            (ConvertTo-C6HostNativeArgument -Value $argument)
        )
    }
    $commandLine=[string]::Join(' ',$serialized)
    [long]$unitCount=[long]$commandLine.Length + 1
    if ($unitCount -lt 1 -or $unitCount -gt 30000) {
        throw 'host native vector exceeds 30000 UTF-16 units'
    }
    $serializedBytes=[Text.Encoding]::Unicode.GetBytes(
        $commandLine + [char]0
    )
    $digest=[Convert]::ToHexString(
        [Security.Cryptography.SHA256]::HashData($serializedBytes)
    ).ToLowerInvariant()
    return [pscustomobject]@{
        contract='complete-suite-windows-native-vector-v1'
        utf16_units=[int]$unitCount
        utf16le_sha256=$digest
        command_line=$commandLine
    }
}
"""
_HOST_NATIVE_VECTOR_FUNCTION_DEFINITION = re.compile(
    (
        rb"(?i)(?<![A-Za-z0-9_-])(?:function|filter)[ \t]+"
        rb"(?:(?:global|script|local|private):)?"
        rb"([A-Za-z][A-Za-z0-9-]*)[ \t]*\{"
    )
)
def _native_leaf_constructor_implementation_spec(
    implementation_id: str,
) -> tuple[str, bytes, bytes]:
    if implementation_id == "host-native-core-v1":
        return (
            "tests/skills/complete_suite_control_plane.ps1",
            b"# C6-HOST-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
            b"# C6-HOST-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
        )
    if implementation_id == "broker-native-core-v1":
        return (
            "tests/skills/complete_suite_release_python_bootstrap.py",
            b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
            b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
        )
    _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _native_leaf_constructor_registry_spec(
    registry_id: str,
) -> tuple[bytes, bytes, bytes]:
    if registry_id == "constructor-implementation-set":
        return (
            b"# C6-CONSTRUCTOR-IMPLEMENTATION-SET-BEGIN",
            b"# C6-CONSTRUCTOR-IMPLEMENTATION-SET-END",
            b"C6ConstructorImplementationSetJson",
        )
    if registry_id == "constructor-attribute-set":
        return (
            b"# C6-CONSTRUCTOR-ATTRIBUTE-SET-BEGIN",
            b"# C6-CONSTRUCTOR-ATTRIBUTE-SET-END",
            b"C6ConstructorAttributeSetJson",
        )
    if registry_id == "job-topology":
        return (
            b"# C6-JOB-TOPOLOGY-BEGIN",
            b"# C6-JOB-TOPOLOGY-END",
            b"C6JobTopologyJson",
        )
    _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _launch_native_leaf_constructor_source_bytes(value: object) -> bytes:
    if (
        type(value) is not bytes
        or not value
        or len(value) > _NATIVE_LEAF_CONSTRUCTOR_SOURCE_CAP_BYTES
        or not value.endswith(b"\n")
        or b"\xef\xbb\xbf" in value
        or b"\r" in value
        or b"\x00" in value
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    try:
        value.decode("utf-8", errors="strict")
    except UnicodeError as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    return memoryview(value).tobytes()


@dataclass(frozen=True, repr=False, slots=True)
class _HostNativeVectorSourceFragment:
    version: Literal[
        "complete-suite-host-native-vector-source-fragment-v1"
    ]
    implementation_id: Literal["host-native-core-v1"]
    function_names: tuple[str, str, str]
    source_bytes: bytes

    def __post_init__(self) -> None:
        if (
            self.version != _HOST_NATIVE_VECTOR_SOURCE_FRAGMENT_VERSION
            or self.implementation_id != "host-native-core-v1"
            or type(self.function_names) is not tuple
            or self.function_names != _HOST_NATIVE_VECTOR_FUNCTION_NAMES
            or type(self.source_bytes) is not bytes
            or self.source_bytes != _HOST_NATIVE_VECTOR_SOURCE_BYTES
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

    @property
    def source_sha256(self) -> str:
        return sha256(self.source_bytes).hexdigest()


def _launch_extract_host_native_vector_source_fragment(
    host_body_bytes: bytes,
) -> _HostNativeVectorSourceFragment:
    body = _launch_native_leaf_constructor_source_bytes(host_body_bytes)
    if body != _HOST_NATIVE_VECTOR_SOURCE_BYTES:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    try:
        function_names = tuple(
            match.group(1).decode("ascii", errors="strict")
            for match in _HOST_NATIVE_VECTOR_FUNCTION_DEFINITION.finditer(body)
        )
    except UnicodeError as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    folded_names = tuple(name.casefold() for name in function_names)
    expected_folded = tuple(
        name.casefold() for name in _HOST_NATIVE_VECTOR_FUNCTION_NAMES
    )
    if (
        folded_names != expected_folded
        or any(
            folded_names.count(expected_name) != 1
            for expected_name in expected_folded
        )
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return _HostNativeVectorSourceFragment(
        version=_HOST_NATIVE_VECTOR_SOURCE_FRAGMENT_VERSION,
        implementation_id="host-native-core-v1",
        function_names=_HOST_NATIVE_VECTOR_FUNCTION_NAMES,
        source_bytes=memoryview(_HOST_NATIVE_VECTOR_SOURCE_BYTES).tobytes(),
    )


