def _launch_broker_native_api_ownership_components() -> tuple[
    tuple[tuple[str, str, int, str], ...],
    tuple[str, ...],
    tuple[tuple[str, str], ...],
]:
    owner_specs = _broker_native_api_owner_specs()
    owner_ids = tuple(spec[0] for spec in owner_specs)
    if owner_ids != _BROKER_NATIVE_API_OWNER_IDS:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    api_tables = tuple(
        record
        for record in _broker_native_abi_contract_facts_records()
        if record.get("table") == "api-declaration"
    )
    if len(api_tables) != 1:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    api_table = api_tables[0]
    if api_table.get("columns") != [
        "dll",
        "name",
        "signature",
        "charset",
        "calling_convention",
        "exact_spelling",
        "set_last_error",
        "return_discipline",
    ]:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    rows = api_table.get("rows")
    if type(rows) is not list or any(
        type(row) is not list
        or len(row) != 8
        or type(row[1]) is not str
        for row in rows
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    api_names = tuple(row[1] for row in rows)
    if len(api_names) != 58 or len(frozenset(api_names)) != 58:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

    owner_by_api: dict[str, str] = {}
    duplicate_names: set[str] = set()
    for owner_id, _version, _size, _source_sha256, owned_names in owner_specs:
        if type(owned_names) is not tuple or any(
            type(name) is not str for name in owned_names
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        for name in owned_names:
            if name in owner_by_api:
                duplicate_names.add(name)
            else:
                owner_by_api[name] = owner_id
    expected_names = frozenset(api_names)
    actual_names = frozenset(owner_by_api)
    missing_names = tuple(sorted(expected_names - actual_names))
    unexpected_names = tuple(sorted(actual_names - expected_names))
    if duplicate_names or missing_names or unexpected_names:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    api_owner_pairs = tuple((name, owner_by_api[name]) for name in api_names)
    if (
        len(api_owner_pairs) != 58
        or len(frozenset(api_owner_pairs)) != 58
        or frozenset(owner for _name, owner in api_owner_pairs)
        != frozenset(_BROKER_NATIVE_API_OWNER_IDS)
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    owner_source_bindings = tuple(
        (owner_id, version, source_size, source_sha256)
        for owner_id, version, source_size, source_sha256, _names in owner_specs
    )
    if any(
        type(version) is not str
        or type(source_size) is not int
        or source_size <= 0
        or type(source_sha256) is not str
        or _SHA256.fullmatch(source_sha256) is None
        for _owner_id, version, source_size, source_sha256 in owner_source_bindings
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return owner_source_bindings, api_names, api_owner_pairs


def _launch_broker_native_api_ownership_material() -> bytes:
    owner_source_bindings, api_names, api_owner_pairs = (
        _launch_broker_native_api_ownership_components()
    )
    owner_specs = _broker_native_api_owner_specs()
    api_names_by_owner = {
        owner_id: owned_names
        for owner_id, _version, _size, _sha256, owned_names in owner_specs
    }
    payload = {
        "version": _BROKER_NATIVE_API_OWNERSHIP_VERSION,
        "implementation_id": "broker-native-core-v1",
        "activation_state": _BROKER_NATIVE_API_OWNERSHIP_ACTIVATION_STATE,
        "completeness_state": _BROKER_NATIVE_API_OWNERSHIP_COMPLETENESS_STATE,
        "abi_contract_facts_version": _BROKER_NATIVE_ABI_CONTRACT_FACTS_VERSION,
        "abi_contract_facts_size": _BROKER_NATIVE_ABI_CONTRACT_FACTS_SIZE,
        "abi_contract_facts_sha256": _BROKER_NATIVE_ABI_CONTRACT_FACTS_SHA256,
        "owner_count": len(owner_source_bindings),
        "api_count": len(api_names),
        "owner_sources": [
            {
                "owner_id": owner_id,
                "fragment_version": version,
                "source_size": source_size,
                "source_sha256": source_sha256,
                "api_names": list(api_names_by_owner[owner_id]),
            }
            for owner_id, version, source_size, source_sha256 in (
                owner_source_bindings
            )
        ],
        "api_owners": [
            {"api_name": api_name, "owner_id": owner_id}
            for api_name, owner_id in api_owner_pairs
        ],
    }
    try:
        canonical = json.dumps(
            payload,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=False,
            separators=(",", ":"),
        ).encode("ascii", errors="strict") + b"\n"
    except (MemoryError, RecursionError, UnicodeError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    if (
        len(canonical) != _BROKER_NATIVE_API_OWNERSHIP_CANONICAL_SIZE
        or sha256(canonical).hexdigest()
        != _BROKER_NATIVE_API_OWNERSHIP_CANONICAL_SHA256
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return canonical


