    if (
        type(attempt_authority)
        is not _C6BrokerNativeCoreV1FailureCleanupAttemptAuthority
        or attempt_authority._success_ack_status_expectation_authority
        is not expectation_authority
        or type(resource_manifest)
        is not _C6BrokerNativeCoreV1SuccessResourceManifest
        or resource_manifest.attempt_authority is not attempt_authority
        or attempt_authority._success_resource_manifest
        is not resource_manifest
        or resource_manifest.state is not attempt_authority._state
        or resource_manifest.core is not attempt_authority._core
        or attempt_authority._state._phase != "registering"
        or attempt_authority._state._manifest is not None
        or attempt_authority._success_resource_phase
        not in ("poll-ready", "resource-converged")
        or type(attempt_authority._success_resource_results) is not tuple
        or type(attempt_authority._success_resource_last_monotonic_ns)
        is not int
        or type(process_target)
        is not _C6BrokerNativeCoreV1SuccessProcessTarget
        or sum(
            process_target is candidate
            for candidate in resource_manifest.process_targets
        )
        != 1
        or type(connected_endpoint)
        is not _C6BrokerNativeCoreV1InternalChannelEndpoint
        or connected_endpoint.connect_completion_consumed is not True
        or connected_endpoint.channel_address.fixed_role != "ack-status"
        or connected_endpoint.channel_address.parent_action != "reads"
        or not _c6_broker_native_core_v1_valid_pipe_handle(
            connected_endpoint.server_handle
        )
        or not _c6_broker_native_core_v1_valid_pipe_handle(
            connected_endpoint.child_handle
        )
        or connected_endpoint.server_handle
        == connected_endpoint.child_handle
        or type(attempt_authority._state._prepared_endpoints) is not tuple
    ):
        _reject(GUARDED_BOOTSTRAP_INVALID)
