def _launch_broker_native_constructor_runtime_prefix_fragments(
    *,
    draft_fragment: object,
) -> tuple[object, ...]:
    fragments = []
    for index, descriptor in enumerate(
        _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_DESCRIPTORS
    ):
        (
            _component_id,
            expected_type_name,
            expected_version,
            factory_name,
            expected_size,
            expected_sha256,
        ) = descriptor
        expected_type = globals().get(expected_type_name)
        if type(expected_type) is not type:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        if index == 0:
            if factory_name is not None:
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
            fragment = draft_fragment
        else:
            if type(factory_name) is not str:
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
            factory = globals().get(factory_name)
            if not callable(factory):
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
            try:
                fragment = factory()
            except BaseException as exc:
                if (
                    isinstance(exc, RuntimeError)
                    and str(exc) == LAUNCH_PREFLIGHT_BUNDLE_INVALID
                ):
                    raise
                raise RuntimeError(
                    LAUNCH_PREFLIGHT_BUNDLE_INVALID
                ) from exc
        if (
            type(fragment) is not expected_type
            or type(fragment.version) is not str
            or fragment.version != expected_version
            or type(fragment.source_bytes) is not bytes
            or not fragment.source_bytes.endswith(b"\n")
            or len(fragment.source_bytes) != expected_size
            or sha256(fragment.source_bytes).hexdigest() != expected_sha256
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        fragment.__post_init__()
        fragments.append(fragment)
    result = tuple(fragments)
    if len(result) != len(
        _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_DESCRIPTORS
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return result


def _launch_broker_native_constructor_runtime_prefix_components(
    *,
    draft_fragment: object,
) -> tuple[bytes, ...]:
    return tuple(
        memoryview(fragment.source_bytes).tobytes()
        for fragment in _launch_broker_native_constructor_runtime_prefix_fragments(
            draft_fragment=draft_fragment
        )
    )


def _launch_broker_native_constructor_runtime_prefix_records_sha256(
    records: tuple[tuple[str, int, str], ...],
) -> str:
    try:
        payload = b"".join(
            f"{name}|{count}|{digest}\n".encode("ascii", errors="strict")
            for name, count, digest in records
        )
    except (TypeError, UnicodeError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    return sha256(payload).hexdigest()


def _launch_broker_native_constructor_runtime_prefix_bound_names(
    target: ast.expr,
) -> tuple[str, ...]:
    if isinstance(target, ast.Name):
        return (target.id,)
    if isinstance(target, (ast.Tuple, ast.List)):
        names = tuple(
            name
            for item in target.elts
            for name in (
                _launch_broker_native_constructor_runtime_prefix_bound_names(
                    item
                )
            )
        )
        if not names or len(set(names)) != len(names):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        return names
    _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


@lru_cache(maxsize=4)
def _launch_cached_analyze_broker_native_constructor_runtime_prefix_bindings(
    source: bytes,
) -> tuple[object, ...]:
    try:
        tree = ast.parse(
            source.decode("utf-8", errors="strict"),
            filename="<broker-native-constructor-runtime-prefix-bindings>",
            mode="exec",
        )
    except (
        MemoryError,
        RecursionError,
        SyntaxError,
        UnicodeError,
        ValueError,
    ) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc

    simple_assignment_values: dict[str, list[str]] = {}
    import_binding_values: dict[str, list[str]] = {}
    compound_assignment_values: list[str] = []
    delete_binding_values: list[str] = []
    assignment_binding_names: set[str] = set()
    import_binding_names: set[str] = set()
    class_names = []
    function_names = []
    async_function_seen = False
    try:
        for node in tree.body:
            if isinstance(node, ast.Assign):
                if (
                    len(node.targets) == 1
                    and isinstance(node.targets[0], ast.Name)
                ):
                    name = node.targets[0].id
                    simple_assignment_values.setdefault(name, []).append(
                        ast.dump(
                            node.value,
                            annotate_fields=True,
                            include_attributes=False,
                        )
                    )
                    assignment_binding_names.add(name)
                else:
                    compound_assignment_values.append(
                        ast.dump(
                            node,
                            annotate_fields=True,
                            include_attributes=False,
                        )
                    )
                    for target in node.targets:
                        assignment_binding_names.update(
                            _launch_broker_native_constructor_runtime_prefix_bound_names(
                                target
                            )
                        )
            elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
                compound_assignment_values.append(
                    ast.dump(
                        node,
                        annotate_fields=True,
                        include_attributes=False,
                    )
                )
                assignment_binding_names.update(
                    _launch_broker_native_constructor_runtime_prefix_bound_names(
                        node.target
                    )
                )
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                normalized = ast.dump(
                    node,
                    annotate_fields=True,
                    include_attributes=False,
                )
                for alias in node.names:
                    if alias.name == "*":
                        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
                    if alias.asname is not None:
                        name = alias.asname
                    elif isinstance(node, ast.Import):
                        name = alias.name.split(".", 1)[0]
                    else:
                        name = alias.name
                    import_binding_values.setdefault(name, []).append(
                        normalized
                    )
                    import_binding_names.add(name)
            elif isinstance(node, ast.Delete):
                delete_binding_values.append(
                    ast.dump(
                        node,
                        annotate_fields=True,
                        include_attributes=False,
                    )
                )
                for target in node.targets:
                    _launch_broker_native_constructor_runtime_prefix_bound_names(
                        target
                    )
            elif isinstance(node, ast.ClassDef):
                class_names.append(node.name)
            elif isinstance(node, ast.FunctionDef):
                function_names.append(node.name)
            elif isinstance(node, ast.AsyncFunctionDef):
                async_function_seen = True
                function_names.append(node.name)
            else:
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

        def make_records(
            values_by_name: dict[str, list[str]],
        ) -> tuple[tuple[str, int, str], ...]:
            return tuple(
                (
                    name,
                    len(values),
                    sha256(
                        "\n".join(values).encode(
                            "ascii",
                            errors="strict",
                        )
                    ).hexdigest(),
                )
                for name, values in sorted(values_by_name.items())
            )

        simple_assignment_records = make_records(simple_assignment_values)
        rebinding_records = tuple(
            record for record in simple_assignment_records if record[1] > 1
        )
        import_binding_records = make_records(import_binding_values)
        compound_assignment_sha256 = sha256(
            "\n".join(compound_assignment_values).encode(
                "ascii",
                errors="strict",
            )
        ).hexdigest()
        delete_binding_sha256 = sha256(
            "\n".join(delete_binding_values).encode(
                "ascii",
                errors="strict",
            )
        ).hexdigest()
    except (MemoryError, TypeError, UnicodeError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc

    identical_rebinding_names = tuple(
        record[0] for record in rebinding_records
    )
    simple_assignment_records_sha256 = (
        _launch_broker_native_constructor_runtime_prefix_records_sha256(
            simple_assignment_records
        )
    )
    rebinding_records_sha256 = (
        _launch_broker_native_constructor_runtime_prefix_records_sha256(
            rebinding_records
        )
    )
    import_binding_records_sha256 = (
        _launch_broker_native_constructor_runtime_prefix_records_sha256(
            import_binding_records
        )
    )
    class_names_tuple = tuple(class_names)
    function_names_tuple = tuple(function_names)
    try:
        class_binding_sha256 = sha256(
            b"".join(
                f"{index}|{name}\n".encode("ascii", errors="strict")
                for index, name in enumerate(class_names_tuple)
            )
        ).hexdigest()
        function_binding_sha256 = sha256(
            b"".join(
                f"{index}|{name}\n".encode("ascii", errors="strict")
                for index, name in enumerate(function_names_tuple)
            )
        ).hexdigest()
    except (MemoryError, TypeError, UnicodeError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    binding_inventory_material = (
        "simple-assignments|"
        f"{len(simple_assignment_records)}|"
        f"{sum(record[1] for record in simple_assignment_records)}|"
        f"{simple_assignment_records_sha256}\n"
        "permitted-rebindings|"
        f"{len(rebinding_records)}|{rebinding_records_sha256}\n"
        "import-bindings|"
        f"{len(import_binding_records)}|"
        f"{sum(record[1] for record in import_binding_records)}|"
        f"{import_binding_records_sha256}\n"
        "compound-assignments|"
        f"{len(compound_assignment_values)}|"
        f"{compound_assignment_sha256}\n"
        "delete-bindings|"
        f"{len(delete_binding_values)}|{delete_binding_sha256}\n"
        "class-bindings|"
        f"{len(class_names_tuple)}|{class_binding_sha256}\n"
        "function-bindings|"
        f"{len(function_names_tuple)}|{function_binding_sha256}\n"
    ).encode("ascii", errors="strict")
    binding_inventory_sha256 = sha256(
        binding_inventory_material
    ).hexdigest()
    class_binding_names = set(class_names_tuple)
    function_binding_names = set(function_names_tuple)
    binding_name_sets = (
        assignment_binding_names,
        import_binding_names,
        class_binding_names,
        function_binding_names,
    )
    return (
        class_names_tuple,
        function_names_tuple,
        async_function_seen,
        len(class_binding_names),
        class_binding_sha256,
        len(function_binding_names),
        function_binding_sha256,
        len(simple_assignment_records),
        sum(record[1] for record in simple_assignment_records),
        simple_assignment_records_sha256,
        identical_rebinding_names,
        rebinding_records_sha256,
        not any(
            len(set(values)) != 1
            for values in simple_assignment_values.values()
            if len(values) > 1
        ),
        import_binding_records,
        import_binding_records_sha256,
        len(compound_assignment_values),
        compound_assignment_sha256,
        len(delete_binding_values),
        delete_binding_sha256,
        binding_inventory_sha256,
        any(
            left & right
            for index, left in enumerate(binding_name_sets)
            for right in binding_name_sets[index + 1 :]
        ),
    )


def _launch_analyze_broker_native_constructor_runtime_prefix_bindings(
    source_bytes: bytes,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...], str]:
    source = _launch_native_leaf_constructor_source_bytes(source_bytes)
    (
        class_names,
        function_names,
        async_function_seen,
        distinct_class_name_count,
        class_binding_sha256,
        distinct_function_name_count,
        function_binding_sha256,
        simple_assignment_distinct_count,
        simple_assignment_occurrence_count,
        simple_assignment_records_sha256,
        identical_rebinding_names,
        rebinding_records_sha256,
        all_rebindings_identical,
        import_binding_records,
        import_binding_records_sha256,
        compound_assignment_count,
        compound_assignment_sha256,
        delete_binding_count,
        delete_binding_sha256,
        binding_inventory_sha256,
        cross_kind_shadowing_seen,
    ) = _launch_cached_analyze_broker_native_constructor_runtime_prefix_bindings(
        source
    )
    if (
        async_function_seen
        or len(class_names)
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_CLASS_COUNT
        or distinct_class_name_count != len(class_names)
        or class_binding_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_CLASS_BINDING_SHA256
        or len(function_names)
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_FUNCTION_COUNT
        or distinct_function_name_count != len(function_names)
        or function_binding_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_FUNCTION_BINDING_SHA256
        or simple_assignment_distinct_count
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SIMPLE_ASSIGNMENT_DISTINCT_COUNT
        or simple_assignment_occurrence_count
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SIMPLE_ASSIGNMENT_OCCURRENCE_COUNT
        or simple_assignment_records_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SIMPLE_ASSIGNMENT_RECORDS_SHA256
        or identical_rebinding_names
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IDENTICAL_REBINDING_NAMES
        or rebinding_records_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_REBINDING_RECORDS_SHA256
        or not all_rebindings_identical
        or import_binding_records
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IMPORT_BINDING_RECORDS
        or import_binding_records_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IMPORT_BINDING_RECORDS_SHA256
        or compound_assignment_count
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPOUND_ASSIGNMENT_COUNT
        or compound_assignment_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPOUND_ASSIGNMENT_SHA256
        or delete_binding_count
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_DELETE_BINDING_COUNT
        or delete_binding_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_DELETE_BINDING_SHA256
        or binding_inventory_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_TOP_LEVEL_BINDING_INVENTORY_SHA256
        or cross_kind_shadowing_seen
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return (
        class_names,
        function_names,
        identical_rebinding_names,
        binding_inventory_sha256,
    )


@lru_cache(maxsize=4)
def _launch_cached_compute_broker_native_constructor_runtime_prefix_components(
    source: bytes,
    component_sizes: tuple[int, ...],
) -> tuple[tuple[int, ...], tuple[str, ...], int]:
    cursor = 0
    observed_sizes = []
    observed_sha256s = []
    for expected_size in component_sizes:
        component = source[cursor : cursor + expected_size]
        cursor += expected_size
        observed_sizes.append(len(component))
        observed_sha256s.append(sha256(component).hexdigest())
    return tuple(observed_sizes), tuple(observed_sha256s), cursor


def _launch_validate_broker_native_constructor_runtime_prefix_components(
    source_bytes: bytes,
) -> tuple[tuple[int, ...], tuple[str, ...]]:
    source = _launch_native_leaf_constructor_source_bytes(source_bytes)
    descriptors = (
        _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_DESCRIPTORS
    )
    if type(descriptors) is not tuple or not descriptors:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    for descriptor in descriptors:
        if type(descriptor) is not tuple or len(descriptor) != 6:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        expected_size = descriptor[4]
        expected_sha256 = descriptor[5]
        if (
            type(expected_size) is not int
            or expected_size <= 0
            or type(expected_sha256) is not str
            or len(expected_sha256) != 64
            or any(
                character not in "0123456789abcdef"
                for character in expected_sha256
            )
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    expected_sizes = tuple(
        descriptor[4] for descriptor in descriptors
    )
    expected_sha256s = tuple(
        descriptor[5] for descriptor in descriptors
    )
    observed_sizes, observed_sha256s, cursor = (
        _launch_cached_compute_broker_native_constructor_runtime_prefix_components(
            source,
            expected_sizes,
        )
    )
    if (
        cursor != len(source)
        or observed_sizes != expected_sizes
        or observed_sha256s != expected_sha256s
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return observed_sizes, observed_sha256s


def _launch_scan_broker_native_constructor_runtime_prefix_source(
    source_bytes: bytes,
) -> tuple[
    tuple[str, ...],
    tuple[int, ...],
    tuple[str, ...],
    tuple[str, ...],
    tuple[str, ...],
]:
    source = _launch_native_leaf_constructor_source_bytes(source_bytes)
    if (
        len(source) != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_SIZE
        or sha256(source).hexdigest()
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_SHA256
        or b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" in source
        or b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" in source
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    component_sizes, component_sha256s = (
        _launch_validate_broker_native_constructor_runtime_prefix_components(
            source
        )
    )
    draft_size = _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_SIZES[0]
    draft_fragment = (
        _launch_extract_broker_native_control_plane_candidate_source_fragment(
            memoryview(source[:draft_size]).tobytes()
        )
    )
    fragments = _launch_broker_native_constructor_runtime_prefix_fragments(
        draft_fragment=draft_fragment
    )
    components = tuple(
        memoryview(fragment.source_bytes).tobytes() for fragment in fragments
    )
    component_versions = tuple(fragment.version for fragment in fragments)
    component_type_names = tuple(
        type(fragment).__name__ for fragment in fragments
    )
    (
        class_names,
        function_names,
        identical_rebinding_names,
        binding_inventory_sha256,
    ) = _launch_analyze_broker_native_constructor_runtime_prefix_bindings(
        source
    )
    if (
        b"".join(components) != source
        or component_type_names
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_TYPE_NAMES
        or component_versions
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_VERSIONS
        or component_sizes
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_SIZES
        or component_sha256s
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_SHA256S
        or identical_rebinding_names
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IDENTICAL_REBINDING_NAMES
        or binding_inventory_sha256
        != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_TOP_LEVEL_BINDING_INVENTORY_SHA256
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return (
        component_versions,
        component_sizes,
        component_sha256s,
        class_names,
        function_names,
    )


@dataclass(frozen=True, repr=False, slots=True)
class _BrokerNativeConstructorRuntimePrefixSourceFragment:
    version: Literal[
        "complete-suite-broker-native-constructor-runtime-prefix-source-fragment-v1"
    ]
    implementation_id: Literal["broker-native-core-v1"]
    activation_state: Literal["dormant-source-only"]
    completeness_state: Literal[
        "maximal-implemented-constructor-runtime-prefix-production-tail-absent"
    ]
    component_ids: tuple[str, ...]
    component_type_names: tuple[str, ...]
    component_versions: tuple[str, ...]
    component_sizes: tuple[int, ...]
    component_sha256s: tuple[str, ...]
    identical_rebinding_names: tuple[str, ...]
    top_level_binding_inventory_sha256: str
    class_names: tuple[str, ...]
    function_names: tuple[str, ...]
    source_bytes: bytes

    def __post_init__(self) -> None:
        if (
            type(self.version) is not str
            or self.version
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_FRAGMENT_VERSION
            or type(self.implementation_id) is not str
            or self.implementation_id != "broker-native-core-v1"
            or type(self.activation_state) is not str
            or self.activation_state
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_ACTIVATION_STATE
            or type(self.completeness_state) is not str
            or self.completeness_state
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPLETENESS_STATE
            or type(self.component_ids) is not tuple
            or self.component_ids
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_IDS
            or type(self.component_type_names) is not tuple
            or self.component_type_names
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_TYPE_NAMES
            or type(self.component_versions) is not tuple
            or self.component_versions
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_VERSIONS
            or type(self.component_sizes) is not tuple
            or self.component_sizes
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_SIZES
            or type(self.component_sha256s) is not tuple
            or self.component_sha256s
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_SHA256S
            or type(self.identical_rebinding_names) is not tuple
            or self.identical_rebinding_names
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IDENTICAL_REBINDING_NAMES
            or type(self.top_level_binding_inventory_sha256) is not str
            or self.top_level_binding_inventory_sha256
            != _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_TOP_LEVEL_BINDING_INVENTORY_SHA256
            or type(self.class_names) is not tuple
            or type(self.function_names) is not tuple
            or type(self.source_bytes) is not bytes
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        (
            component_versions,
            component_sizes,
            component_sha256s,
            class_names,
            function_names,
        ) = _launch_scan_broker_native_constructor_runtime_prefix_source(
            self.source_bytes
        )
        if (
            self.component_versions != component_versions
            or self.component_sizes != component_sizes
            or self.component_sha256s != component_sha256s
            or self.class_names != class_names
            or self.function_names != function_names
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

    @property
    def source_sha256(self) -> str:
        return sha256(self.source_bytes).hexdigest()


def _launch_extract_broker_native_constructor_runtime_prefix_source_fragment(
    source_bytes: bytes,
) -> _BrokerNativeConstructorRuntimePrefixSourceFragment:
    source = _launch_native_leaf_constructor_source_bytes(source_bytes)
    component_sizes, component_sha256s = (
        _launch_validate_broker_native_constructor_runtime_prefix_components(
            source
        )
    )
    class_names, function_names, _rebinding_names, _binding_sha256 = (
        _launch_analyze_broker_native_constructor_runtime_prefix_bindings(
            source
        )
    )
    fragment = _BrokerNativeConstructorRuntimePrefixSourceFragment(
        version=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_FRAGMENT_VERSION
        ),
        implementation_id="broker-native-core-v1",
        activation_state=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_ACTIVATION_STATE
        ),
        completeness_state=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPLETENESS_STATE
        ),
        component_ids=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_IDS
        ),
        component_type_names=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_TYPE_NAMES
        ),
        component_versions=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_VERSIONS
        ),
        component_sizes=component_sizes,
        component_sha256s=component_sha256s,
        identical_rebinding_names=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_IDENTICAL_REBINDING_NAMES
        ),
        top_level_binding_inventory_sha256=(
            _BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_TOP_LEVEL_BINDING_INVENTORY_SHA256
        ),
        class_names=class_names,
        function_names=function_names,
        source_bytes=memoryview(source).tobytes(),
    )
    return fragment


def _launch_broker_native_constructor_runtime_prefix_source_fragment(
    *,
    draft_fragment: object,
) -> _BrokerNativeConstructorRuntimePrefixSourceFragment:
    components = _launch_broker_native_constructor_runtime_prefix_components(
        draft_fragment=draft_fragment
    )
    return _launch_extract_broker_native_constructor_runtime_prefix_source_fragment(
        memoryview(b"".join(components)).tobytes()
    )


