        rb"SetLastError = (?P<last_error>true|false)\)\]\n"
        rb"(?P<bool_return>    \[return: MarshalAs\(UnmanagedType\.Bool\)\]\n)?"
        rb"    public static extern (?P<return_type>bool|void|uint|IntPtr|int) "
