def _launch_host_native_process_limit_payload(
    *,
    field_names: tuple[str, ...],
    rows: tuple[tuple[object, ...], ...],
    expected_size: int,
    expected_sha256: str,
) -> bytes:
    if (
        type(field_names) is not tuple
        or not field_names
        or any(type(field) is not str or not field for field in field_names)
        or len(set(field_names)) != len(field_names)
        or type(rows) is not tuple
        or not rows
        or any(
            type(row) is not tuple
            or len(row) != len(field_names)
            or type(row[0]) is not str
            or not row[0]
            or any(type(value) is not int for value in row[1:])
            for row in rows
        )
        or len({row[0] for row in rows}) != len(rows)
        or type(expected_size) is not int
        or expected_size <= 0
        or not _is_sha256(expected_sha256)
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    records = tuple(
        {field: value for field, value in zip(field_names, row, strict=True)}
        for row in rows
    )
    try:
        payload = json.dumps(
            records,
            ensure_ascii=True,
            allow_nan=False,
            sort_keys=False,
            separators=(",", ":"),
        ).encode("ascii", errors="strict") + b"\n"
    except (UnicodeError, RecursionError, ValueError) as exc:
        raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
    if (
        len(payload) != expected_size
        or sha256(payload).hexdigest() != expected_sha256
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return payload


