def _launch_scan_host_native_environment_block_source(
    source_bytes: bytes,
) -> None:
    source = _launch_native_leaf_constructor_source_bytes(source_bytes)
    ordered_tokens = (
        b"$Environment.GetType() -ne",
        b"$Environment.GetEnumerator()",
        b"[StringComparer]::OrdinalIgnoreCase",
        b"Assert-C6HostNativeVectorString -Value $name",
        b"Assert-C6HostNativeVectorString -Value $value",
        b"-not $caseKeys.Add($name)",
        b"$names.Sort([StringComparer]::Ordinal)",
        b"[void]$builder.Append([char]0)",
        b"[void]$builder.Append([char]0)",
        b"[Text.Encoding]::Unicode.GetBytes($blockText)",
        b"[Security.Cryptography.SHA256]::HashData($serializedBytes)",
        b"contract='complete-suite-windows-environment-block-v1'",
    )
    cursor = 0
    for token in ordered_tokens:
        token_index = source.find(token, cursor)
        if token_index < 0:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        cursor = token_index + len(token)
    forbidden_tokens = (
        b"$env:",
        b"GetEnvironmentVariable",
        b"GetEnvironmentVariables",
        b"ConvertFrom-Json",
        b"Invoke-Expression",
        b"Set-Alias",
        b"Import-Module",
        b"Add-Type",
        b"CreateProcessW",
        b"Start-Process",
        b"Process.Start",
        b"|",
    )
    if (
        source != _HOST_NATIVE_ENVIRONMENT_BLOCK_SOURCE_BYTES
        or len(source) != _HOST_NATIVE_ENVIRONMENT_BLOCK_SOURCE_SIZE
        or sha256(source).hexdigest()
        != _HOST_NATIVE_ENVIRONMENT_BLOCK_SOURCE_SHA256
        or source.count(
            b"function New-C6HostNativeEnvironmentBlock {"
        )
        != 1
        or source.count(b"[void]$builder.Append([char]0)") != 2
        or source.count(b"Assert-C6HostNativeVectorString") != 2
        or any(token in source for token in forbidden_tokens)
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


