@dataclass(frozen=True, repr=False)
class _NativeLeafConstructorSourceFragments:
    version: Literal[
        "complete-suite-native-leaf-constructor-source-fragments-v1"
    ]
    source_root: str
    source_root_identity: FilesystemObjectIdentity
    control_source: CapturedLaunchInput
    broker_source: CapturedLaunchInput
    implementations: tuple[
        _NativeLeafConstructorImplementationFragment,
        _NativeLeafConstructorImplementationFragment,
    ]
    registries: tuple[
        _NativeLeafConstructorRegistryFragment,
        _NativeLeafConstructorRegistryFragment,
        _NativeLeafConstructorRegistryFragment,
    ]

    def __post_init__(self) -> None:
        if (
            self.version != _NATIVE_LEAF_CONSTRUCTOR_SOURCE_FRAGMENTS_VERSION
            or not _valid_absolute_path(self.source_root)
            or ntpath.normpath(self.source_root) != self.source_root
            or type(self.implementations) is not tuple
            or len(self.implementations) != 2
            or any(
                type(fragment)
                is not _NativeLeafConstructorImplementationFragment
                for fragment in self.implementations
            )
            or type(self.registries) is not tuple
            or len(self.registries) != 3
            or any(
                type(fragment) is not _NativeLeafConstructorRegistryFragment
                for fragment in self.registries
            )
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        _validate_plain_identity(
            self.source_root_identity,
            code=LAUNCH_PREFLIGHT_BUNDLE_INVALID,
        )
        control = _launch_validate_native_leaf_constructor_capture(
            self.control_source
        )
        broker = _launch_validate_native_leaf_constructor_capture(
            self.broker_source
        )
        expected_control_path = Path(self.source_root).joinpath(
            "tests",
            "skills",
            "complete_suite_control_plane.ps1",
        )
        expected_broker_path = Path(self.source_root).joinpath(
            "tests",
            "skills",
            "complete_suite_release_python_bootstrap.py",
        )
        if (
            control.path != str(expected_control_path)
            or broker.path != str(expected_broker_path)
            or control.path == broker.path
            or control.identity == broker.identity
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        for fragment in self.implementations:
            fragment.__post_init__()
        for fragment in self.registries:
            fragment.__post_init__()
        if (
            tuple(fragment.implementation_id for fragment in self.implementations)
            != ("host-native-core-v1", "broker-native-core-v1")
            or self.implementations[0].source_capture != control
            or self.implementations[1].source_capture != broker
            or tuple(fragment.registry_id for fragment in self.registries)
            != (
                "constructor-implementation-set",
                "constructor-attribute-set",
                "job-topology",
            )
            or any(fragment.source_capture != control for fragment in self.registries)
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        implementation_hashes = {
            fragment.implementation_id: fragment.body_sha256
            for fragment in self.implementations
        }
        expected_registries = (
            _native_leaf_compact_ascii_array(
                _native_leaf_constructor_implementation_records(
                    implementation_hashes
                )
            ),
            _native_leaf_compact_ascii_array(
                _native_leaf_constructor_attribute_records()
            ),
            _native_leaf_compact_ascii_array(_native_leaf_job_topology_records()),
        )
        extracted_registries = _launch_native_leaf_constructor_registry_material(
            control.content
        )
        if (
            tuple(fragment.payload_bytes for fragment in self.registries)
            != expected_registries
            or extracted_registries != expected_registries
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _launch_copy_native_leaf_constructor_source_capture(
    value: CapturedLaunchInput,
) -> CapturedLaunchInput:
    capture = _launch_validate_native_leaf_constructor_capture(value)
    return CapturedLaunchInput(
        path=capture.path,
        content=memoryview(capture.content).tobytes(),
        utf8_bytes=capture.utf8_bytes,
        sha256=capture.sha256,
        identity=_launch_copy_plain_identity(capture.identity),
    )


def _launch_capture_native_leaf_constructor_source(
    *,
    expected_path: Path,
    supplied: CapturedLaunchInput,
) -> CapturedLaunchInput:
    capture = _launch_validate_native_leaf_constructor_capture(supplied)
    if capture.path != str(expected_path):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    content, identity = _validator_capture_plain_file(
        expected_path,
        max_bytes=_NATIVE_LEAF_CONSTRUCTOR_SOURCE_CAP_BYTES,
    )
    _launch_native_leaf_constructor_source_bytes(content)
    if (
        content != capture.content
        or len(content) != capture.utf8_bytes
        or sha256(content).hexdigest() != capture.sha256
        or identity != capture.identity
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return _launch_copy_native_leaf_constructor_source_capture(capture)


def _launch_extract_native_leaf_construction_source_fragments(
    *,
    source_root: Path,
    control_source: CapturedLaunchInput,
    broker_source: CapturedLaunchInput,
) -> _NativeLeafConstructorSourceFragments:
    try:
        canonical_root = _validator_absolute_path(source_root)
        root_identity_before = _validator_plain_directory_identity(canonical_root)
        control_path = canonical_root.joinpath(
            "tests",
            "skills",
            "complete_suite_control_plane.ps1",
        )
        broker_path = canonical_root.joinpath(
            "tests",
            "skills",
            "complete_suite_release_python_bootstrap.py",
        )
        captured_control = _launch_capture_native_leaf_constructor_source(
            expected_path=control_path,
            supplied=control_source,
        )
        captured_broker = _launch_capture_native_leaf_constructor_source(
            expected_path=broker_path,
            supplied=broker_source,
        )
        if (
            _validator_plain_directory_identity(canonical_root)
            != root_identity_before
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        implementations = tuple(
            _NativeLeafConstructorImplementationFragment(
                version=(
                    _NATIVE_LEAF_CONSTRUCTOR_IMPLEMENTATION_FRAGMENT_VERSION
                ),
                implementation_id=implementation_id,
                source_relative_path=source_relative_path,
                source_capture=source_capture,
                body_bytes=_launch_extract_native_leaf_constructor_body(
                    source_capture.content,
                    begin_marker=begin_marker,
                    end_marker=end_marker,
                ),
            )
            for implementation_id, source_capture in (
                ("host-native-core-v1", captured_control),
                ("broker-native-core-v1", captured_broker),
            )
            for source_relative_path, begin_marker, end_marker in (
                _native_leaf_constructor_implementation_spec(implementation_id),
            )
        )
        registry_payloads = _launch_native_leaf_constructor_registry_material(
            captured_control.content
        )
        registries = tuple(
            _NativeLeafConstructorRegistryFragment(
                version=_NATIVE_LEAF_CONSTRUCTOR_REGISTRY_FRAGMENT_VERSION,
                registry_id=registry_id,
                source_relative_path=(
                    "tests/skills/complete_suite_control_plane.ps1"
                ),
                source_capture=captured_control,
                payload_bytes=memoryview(payload).tobytes(),
            )
            for registry_id, payload in zip(
                (
                    "constructor-implementation-set",
                    "constructor-attribute-set",
                    "job-topology",
                ),
                registry_payloads,
                strict=True,
            )
        )
        fragments = _NativeLeafConstructorSourceFragments(
            version=_NATIVE_LEAF_CONSTRUCTOR_SOURCE_FRAGMENTS_VERSION,
            source_root=str(canonical_root),
            source_root_identity=_launch_copy_plain_identity(
                root_identity_before
            ),
            control_source=captured_control,
            broker_source=captured_broker,
            implementations=implementations,
            registries=registries,
        )
        _validator_revalidate_plain_file(
            control_path,
            expected_content=captured_control.content,
            expected_identity=captured_control.identity,
            max_bytes=_NATIVE_LEAF_CONSTRUCTOR_SOURCE_CAP_BYTES,
        )
        _validator_revalidate_plain_file(
            broker_path,
            expected_content=captured_broker.content,
            expected_identity=captured_broker.identity,
            max_bytes=_NATIVE_LEAF_CONSTRUCTOR_SOURCE_CAP_BYTES,
        )
        if (
            _validator_plain_directory_identity(canonical_root)
            != root_identity_before
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        fragments.__post_init__()
        return fragments
    except RuntimeError as exc:
        if str(exc) == LAUNCH_PREFLIGHT_BUNDLE_INVALID:
            raise
        if str(exc) in {
            CLIENT_LAUNCH_INPUT_INVALID,
            VALIDATOR_BUNDLE_INVALID,
            COMMAND_LAUNCH_SPEC_MISMATCH,
        }:
            raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from exc
        raise


@dataclass(frozen=True, repr=False)
class _NativeLeafRoleConstructionPolicy:
    role: Literal["git", "node"]
    source_relative_path: str
    source_sha256: str
    argv_grammar_bytes: bytes
    argv_grammar_sha256: str
    environment_grammar_bytes: bytes
    environment_grammar_sha256: str
    cwd_policy_bytes: bytes
    cwd_policy_sha256: str
    cwd_role: str
    permitted_constructor_implementations: tuple[
        tuple[
            Literal["host-native-core-v1", "broker-native-core-v1"],
            str,
        ],
        ...,
    ]
    constructor_implementation_set_sha256: str

    def __post_init__(self) -> None:
        _NativeLeafRoleSourcePolicy(
            role=self.role,
            source_relative_path=self.source_relative_path,
            source_sha256=self.source_sha256,
            argv_grammar_bytes=self.argv_grammar_bytes,
            argv_grammar_sha256=self.argv_grammar_sha256,
            environment_grammar_bytes=self.environment_grammar_bytes,
            environment_grammar_sha256=self.environment_grammar_sha256,
            cwd_policy_bytes=self.cwd_policy_bytes,
            cwd_policy_sha256=self.cwd_policy_sha256,
            cwd_role=self.cwd_role,
        )
        expected_ids = (
            ("host-native-core-v1", "broker-native-core-v1")
            if self.role == "git"
            else ("broker-native-core-v1",)
            if self.role == "node"
            else ()
        )
        if (
            not expected_ids
            or type(self.permitted_constructor_implementations) is not tuple
            or tuple(
                item[0] for item in self.permitted_constructor_implementations
            )
            != expected_ids
            or any(
                type(item) is not tuple
                or len(item) != 2
                or not _is_sha256(item[1])
                for item in self.permitted_constructor_implementations
            )
            or not _is_sha256(self.constructor_implementation_set_sha256)
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _launch_native_leaf_authority_material(
    *,
    source_policy_authority: _NativeLeafSourcePolicyAuthority,
) -> tuple[
    bytes,
    str,
    bytes,
    str,
    bytes,
    str,
    tuple[_NativeLeafRoleConstructionPolicy, ...],
]:
    if type(source_policy_authority) is not _NativeLeafSourcePolicyAuthority:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    source_policy_authority.__post_init__()
    implementation_hashes = _native_leaf_source_implementation_hashes(
        source_policy_authority.constructor_implementations
    )
    implementation_records = _native_leaf_constructor_implementation_records(
        implementation_hashes
    )
    implementation_registry_bytes = _native_leaf_compact_ascii_array(
        implementation_records
    )
    implementation_registry_sha256 = sha256(
        implementation_registry_bytes
    ).hexdigest()
    attribute_set_bytes = _native_leaf_compact_ascii_array(
        _native_leaf_constructor_attribute_records()
    )
    attribute_set_sha256 = sha256(attribute_set_bytes).hexdigest()
    topology_bytes = _native_leaf_compact_ascii_array(
        _native_leaf_job_topology_records()
    )
    topology_sha256 = sha256(topology_bytes).hexdigest()
    policies: list[_NativeLeafRoleConstructionPolicy] = []
    for source_policy in source_policy_authority.role_policies:
        implementation_ids = (
            ("host-native-core-v1", "broker-native-core-v1")
            if source_policy.role == "git"
            else ("broker-native-core-v1",)
        )
        implementations = tuple(
            (implementation_id, implementation_hashes[implementation_id])
            for implementation_id in implementation_ids
        )
        policies.append(
            _NativeLeafRoleConstructionPolicy(
                role=source_policy.role,
                source_relative_path=source_policy.source_relative_path,
                source_sha256=source_policy.source_sha256,
                argv_grammar_bytes=source_policy.argv_grammar_bytes,
                argv_grammar_sha256=source_policy.argv_grammar_sha256,
                environment_grammar_bytes=(
                    source_policy.environment_grammar_bytes
                ),
                environment_grammar_sha256=(
                    source_policy.environment_grammar_sha256
                ),
                cwd_policy_bytes=source_policy.cwd_policy_bytes,
                cwd_policy_sha256=source_policy.cwd_policy_sha256,
                cwd_role=source_policy.cwd_role,
                permitted_constructor_implementations=implementations,
                constructor_implementation_set_sha256=(
                    implementation_registry_sha256
                ),
            )
        )
    return (
        implementation_registry_bytes,
        implementation_registry_sha256,
        attribute_set_bytes,
        attribute_set_sha256,
        topology_bytes,
        topology_sha256,
        tuple(policies),
    )


@dataclass(frozen=True, repr=False)
class _NativeLeafConstructionAuthority:
    version: Literal["complete-suite-native-leaf-construction-authority-v1"]
    source_policy_authority: _NativeLeafSourcePolicyAuthority
    constructor_implementation_registry_bytes: bytes
    constructor_implementation_registry_sha256: str
    constructor_attribute_set_bytes: bytes
    constructor_attribute_set_sha256: str
    job_topology_bytes: bytes
    job_topology_sha256: str
    role_policies: tuple[_NativeLeafRoleConstructionPolicy, ...]

    def __post_init__(self) -> None:
        if type(self.source_policy_authority) is not _NativeLeafSourcePolicyAuthority:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        self.source_policy_authority.__post_init__()
        expected = _launch_native_leaf_authority_material(
            source_policy_authority=self.source_policy_authority,
        )
        if (
            self.version != _NATIVE_LEAF_CONSTRUCTION_AUTHORITY_VERSION
            or type(self.role_policies) is not tuple
            or any(
                type(policy) is not _NativeLeafRoleConstructionPolicy
                for policy in self.role_policies
            )
            or (
                self.constructor_implementation_registry_bytes,
                self.constructor_implementation_registry_sha256,
                self.constructor_attribute_set_bytes,
                self.constructor_attribute_set_sha256,
                self.job_topology_bytes,
                self.job_topology_sha256,
                self.role_policies,
            )
            != expected
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _launch_build_native_leaf_construction_authority(
    *,
    source_policy_authority: _NativeLeafSourcePolicyAuthority,
) -> _NativeLeafConstructionAuthority:
    if type(source_policy_authority) is not _NativeLeafSourcePolicyAuthority:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    source_policy_authority.__post_init__()
    (
        implementation_registry_bytes,
        implementation_registry_sha256,
        attribute_set_bytes,
        attribute_set_sha256,
        topology_bytes,
        topology_sha256,
        policies,
    ) = _launch_native_leaf_authority_material(
        source_policy_authority=source_policy_authority,
    )
    return _NativeLeafConstructionAuthority(
        version=_NATIVE_LEAF_CONSTRUCTION_AUTHORITY_VERSION,
        source_policy_authority=source_policy_authority,
        constructor_implementation_registry_bytes=(
            implementation_registry_bytes
        ),
        constructor_implementation_registry_sha256=(
            implementation_registry_sha256
        ),
        constructor_attribute_set_bytes=attribute_set_bytes,
        constructor_attribute_set_sha256=attribute_set_sha256,
        job_topology_bytes=topology_bytes,
        job_topology_sha256=topology_sha256,
        role_policies=policies,
    )


def _launch_load_native_leaf_construction_authority(
) -> _NativeLeafConstructionAuthority:
    _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)


def _launch_native_leaf_role_policy(
    authority: _NativeLeafConstructionAuthority,
    role: str,
) -> _NativeLeafRoleConstructionPolicy:
    if type(authority) is not _NativeLeafConstructionAuthority:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    authority.__post_init__()
    matches = tuple(policy for policy in authority.role_policies if policy.role == role)
    if len(matches) != 1:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return matches[0]


@dataclass(frozen=True)
class FrozenNativeLeaf:
    version: Literal["complete-suite-native-leaf-v1"]
    role: Literal["git", "node", "powershell_decoder"]
    executable_path: str
    executable_size: int
    executable_sha256: str
    executable_identity: FilesystemObjectIdentity
    ancestor_identities: tuple[FilesystemObjectIdentity, ...]
    hardlink_paths: tuple[str, ...]
    hardlink_manifest_sha256: str
    file_version: str
    product_version: str
    argv_grammar_sha256: str
    environment_grammar_sha256: str
    cwd_role: str
    constructor_class: Literal["guarded-target-or-native-leaf"]
    permitted_constructor_implementations: tuple[
        tuple[
            Literal["host-native-core-v1", "broker-native-core-v1"],
            str,
        ],
        ...,
    ]
    constructor_implementation_set_sha256: str
    constructor_attribute_set_sha256: str
    job_topology_sha256: str
    descendant_policy: Literal["child-process-restricted-zero-descendants"]
    canonical_sha256: str

    def __post_init__(self) -> None:
        if (
            self.version != "complete-suite-native-leaf-v1"
            or self.role not in {"git", "node", "powershell_decoder"}
            or type(self.executable_size) is not int
            or self.executable_size < 1
            or not _is_sha256(self.executable_sha256)
            or type(self.ancestor_identities) is not tuple
            or not self.ancestor_identities
            or any(
                type(identity) is not FilesystemObjectIdentity
                for identity in self.ancestor_identities
            )
            or type(self.hardlink_paths) is not tuple
            or not self.hardlink_paths
            or any(type(path) is not str for path in self.hardlink_paths)
            or tuple(
                sorted(
                    self.hardlink_paths,
                    key=lambda item: (item.casefold(), item),
                )
            )
            != self.hardlink_paths
            or len({item.casefold() for item in self.hardlink_paths})
            != len(self.hardlink_paths)
            or self.executable_path not in self.hardlink_paths
            or self.hardlink_manifest_sha256
            != _native_hardlink_manifest_sha256(self.hardlink_paths)
            or type(self.file_version) is not str
            or not self.file_version
            or type(self.product_version) is not str
            or not self.product_version
            or not _is_sha256(self.argv_grammar_sha256)
            or not _is_sha256(self.environment_grammar_sha256)
            or type(self.cwd_role) is not str
            or not self.cwd_role
            or self.constructor_class != "guarded-target-or-native-leaf"
            or type(self.permitted_constructor_implementations) is not tuple
            or any(
                type(item) is not tuple
                or len(item) != 2
                or item[0]
                not in {"host-native-core-v1", "broker-native-core-v1"}
                or not _is_sha256(item[1])
                for item in self.permitted_constructor_implementations
            )
            or not _is_sha256(self.constructor_implementation_set_sha256)
            or not _is_sha256(self.constructor_attribute_set_sha256)
            or not _is_sha256(self.job_topology_sha256)
            or self.descendant_policy
            != "child-process-restricted-zero-descendants"
            or not _is_sha256(self.canonical_sha256)
        ):
            _launch_reject()
        implementation_ids = tuple(
            item[0] for item in self.permitted_constructor_implementations
        )
        if (
            self.role == "git"
            and implementation_ids
            != ("host-native-core-v1", "broker-native-core-v1")
        ) or (
            self.role in {"node", "powershell_decoder"}
            and implementation_ids != ("broker-native-core-v1",)
        ):
            _launch_reject()
        _launch_absolute_path(self.executable_path)
        for path in self.hardlink_paths:
            _launch_absolute_path(path)
        if type(self.executable_identity) is not FilesystemObjectIdentity:
            _launch_reject()
        self.executable_identity.__post_init__()
        for identity in self.ancestor_identities:
            identity.__post_init__()
        if (
            self.executable_identity.file_type != 1
            or self.executable_identity.reparse_tag != 0
            or self.executable_identity.link_count != len(self.hardlink_paths)
            or any(identity.reparse_tag != 0 for identity in self.ancestor_identities)
            or self.canonical_sha256
            != sha256(
                _canonical_json_bytes(_frozen_native_leaf_payload(self))
            ).hexdigest()
        ):
            _launch_reject()


