@dataclass(frozen=True, repr=False)
class _LaunchPrelaunchAuthority:
    version: Literal["complete-suite-launch-prelaunch-authority-v1"]
    prompts: tuple[CapturedLaunchInput, CapturedLaunchInput, CapturedLaunchInput]
    output_schema: CapturedLaunchInput
    workspace_snapshot: FilesystemRootSnapshot
    workspace_snapshot_manifest: CapturedLaunchInput
    final_message_paths: tuple[str, str, str, str]
    final_paths_were_absent: tuple[bool, bool, bool, bool]
    canonical_sha256: str

    def __post_init__(self) -> None:
        if (
            self.version != "complete-suite-launch-prelaunch-authority-v1"
            or type(self.prompts) is not tuple
            or len(self.prompts) != 3
            or any(type(item) is not CapturedLaunchInput for item in self.prompts)
            or type(self.output_schema) is not CapturedLaunchInput
            or type(self.workspace_snapshot) is not FilesystemRootSnapshot
            or type(self.workspace_snapshot_manifest) is not CapturedLaunchInput
            or type(self.final_message_paths) is not tuple
            or len(self.final_message_paths) != 4
            or any(type(item) is not str for item in self.final_message_paths)
            or self.final_paths_were_absent != (True, True, True, True)
            or not _is_sha256(self.canonical_sha256)
        ):
            _launch_reject()
        for capture in (*self.prompts, self.output_schema, self.workspace_snapshot_manifest):
            capture.__post_init__()
        self.workspace_snapshot.__post_init__()
        if self.canonical_sha256 != sha256(
            _canonical_json_bytes(_launch_prelaunch_authority_payload(self))
        ).hexdigest():
            _launch_reject()


@dataclass(frozen=True, repr=False)
class _LaunchDurableAuthority:
    version: Literal["complete-suite-launch-durable-authority-v1"]
