def _launch_advertised_tools_bytes() -> bytes:
    payload = _canonical_json_bytes(_launch_advertised_tools_payload())
    if (
        sha256(payload).hexdigest()
        != client_preflight_server.ADVERTISED_TOOLS_SHA256
        or _launch_advertised_tools_payload()["tools"]
        != client_preflight_server.advertised_tools()
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return payload


def _launch_independent_response_sse(
    *,
    response_id: str,
    item: dict[str, object],
) -> bytes:
    output_item = {
        "item": item,
        "type": "response.output_item.done",
    }
    completed = {
        "response": {
            "id": response_id,
            "incomplete_details": None,
            "status": "completed",
            "usage": {
                "input_tokens": 0,
                "input_tokens_details": {
                    "cache_write_tokens": 0,
                    "cached_tokens": 0,
                },
                "output_tokens": 0,
                "output_tokens_details": {"reasoning_tokens": 0},
                "total_tokens": 0,
            },
        },
        "type": "response.completed",
    }
    return b"data: " + _canonical_json_bytes(output_item) + b"\n\n" + (
        b"data: " + _canonical_json_bytes(completed) + b"\n\n"
    )


def _launch_independent_tool_call_sse(
    *,
    arguments: str,
    response_id: str,
    call_id: str,
    tool_item_id: str,
    tool_name: str,
) -> bytes:
    return _launch_independent_response_sse(
        response_id=response_id,
        item={
            "arguments": arguments,
            "call_id": call_id,
            "id": tool_item_id,
            "name": tool_name,
            "status": "completed",
            "type": "function_call",
        },
    )


def _launch_independent_final_text_sse(*, response_id: str) -> bytes:
    return _launch_independent_response_sse(
        response_id=response_id,
        item={
            "content": [
                {
                    "annotations": [],
                    "text": "campaign6-loopback-complete",
                    "type": "output_text",
                }
            ],
            "id": "msg_campaign6_loopback_final",
            "phase": "final_answer",
            "role": "assistant",
            "status": "completed",
            "type": "message",
        },
    )


def _launch_independent_loopback_contract_payload() -> dict[str, object]:
    tools = _launch_advertised_tools_payload()["tools"]
    if type(tools) is not list:
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    scenario_inputs = (
        (
            "shell",
            {"command": r"Test-Path -LiteralPath '.\case.json'"},
            "Chunk ID: campaign6-loopback\n"
            "Process exited with code 0\n"
            "Final output:\n"
            "True\n",
            "shell",
            None,
        ),
        (
            "file_add",
            {
                "patch": (
                    "*** Begin Patch\n"
                    "*** Add File: preflight-file-change.txt\n"
                    "+campaign6-add\n"
                    "*** End Patch"
                )
            },
            "Done!",
            "apply_patch",
            b"campaign6-add\n",
        ),
        (
            "file_update",
            {
                "patch": (
                    "*** Begin Patch\n"
                    "*** Update File: preflight-file-change.txt\n"
                    "@@\n"
                    "-campaign6-add\n"
                    "+campaign6-update\n"
                    "*** End Patch"
                )
            },
            "Done!",
            "apply_patch",
            b"campaign6-update\n",
        ),
    )
    scenarios: list[dict[str, object]] = []
    for scenario, argument_object, tool_output, tool_name, file_bytes in (
        scenario_inputs
    ):
        argument_bytes = _canonical_json_bytes(argument_object)
        arguments = argument_bytes.decode("utf-8")
        first_request = {
            "input": [
                {
                    "content": [
                        {
                            "text": f"{scenario}\ncase-root=<case-root>",
                            "type": "input_text",
                        }
                    ],
                    "role": "user",
                }
            ],
            "model": "gpt-5.6-terra",
            "parallel_tool_calls": False,
            "store": False,
            "stream": True,
            "tool_choice": "auto",
            "tools": tools,
        }
        second_request = {
            "input": [
                {
                    "call_id": "<response-call-id>",
                    "output": tool_output,
                    "type": "function_call_output",
                }
            ],
            "model": "gpt-5.6-terra",
            "parallel_tool_calls": False,
            "previous_response_id": "<response-id-1>",
            "store": False,
            "stream": True,
            "tool_choice": "auto",
            "tools": tools,
        }
        first_sse = _launch_independent_tool_call_sse(
            arguments=arguments,
            response_id="<response-id-1>",
            call_id="<response-call-id>",
            tool_item_id="<tool-item-id>",
            tool_name=tool_name,
        )
        second_sse = _launch_independent_final_text_sse(
            response_id="<response-id-2>",
        )
        scenarios.append(
            {
                "arguments_sha256": sha256(argument_bytes).hexdigest(),
                "file_bytes_sha256": (
                    None
                    if file_bytes is None
                    else sha256(file_bytes).hexdigest()
                ),
                "first_request_sha256": sha256(
                    _canonical_json_bytes(first_request)
                ).hexdigest(),
                "first_sse_sha256": sha256(first_sse).hexdigest(),
                "name": scenario,
                "prompt_template": f"{scenario}\ncase-root=<case-root>",
                "second_request_sha256": sha256(
                    _canonical_json_bytes(second_request)
                ).hexdigest(),
                "second_sse_sha256": sha256(second_sse).hexdigest(),
                "tool_name": tool_name,
                "tool_output_sha256": sha256(
                    tool_output.encode("utf-8")
                ).hexdigest(),
            }
        )
    return {
        "advertised_tools_sha256": sha256(
            _canonical_json_bytes(_launch_advertised_tools_payload())
        ).hexdigest(),
        "bind_host": "127.0.0.1",
        "capabilities": {
            "parallel_tool_calls": False,
            "tool_choice": "auto",
        },
        "max_request_bytes": 1_048_576,
        "method": "POST",
        "model": "gpt-5.6-terra",
        "native_tool_schema_provenance": (
            "unverified-fail-closed-static-request-tool-schema-v1"
        ),
        "normalizable_fields": [
            "owned_ephemeral_port",
            "responses_call_ids",
            "case_root",
            "derived_request_content_length",
            "request_header.traceparent",
            "request_header.tracestate",
            "request_header.x-client-request-id",
        ],
        "port_assignment": "os-assigned",
        "request_header_contract": {
            "allow_duplicate_names": False,
            "comparison": "case-insensitive-name-unordered",
            "content_length": "canonical-decimal-body-bytes",
            "content_type": "application/json",
            "host": "127.0.0.1:<owned-ephemeral-port>",
            "optional_names": [
                "accept",
                "accept-encoding",
                "connection",
                "openai-beta",
                "traceparent",
                "tracestate",
                "x-client-request-id",
                "x-codex-installation-id",
                "x-codex-routing-hint",
                "x-codex-turn-metadata",
                "x-codex-turn-state",
                "x-oai-attestation",
                "x-openai-subagent",
                "x-responsesapi-include-timing-metrics",
            ],
            "required_names": [
                "content-length",
                "content-type",
                "host",
                "user-agent",
            ],
            "user_agent": "kokoroarc-campaign6-client-preflight-v1",
        },
        "request_optional_fields": [
            "client_metadata",
            "codex_output_schema",
            "include",
            "instructions",
            "prompt_cache_key",
            "reasoning",
            "service_tier",
            "stream_options",
        ],
        "request_ordinals": ["tool_call", "final_text"],
        "route": "/v1/responses",
        "scenarios": scenarios,
        "shell_repeat_additional_normalizable_fields": [
            "shell_tool_item_id"
        ],
        "tools": tools,
        "version": "complete-suite-loopback-contract-v1",
    }


def _launch_loopback_contract_bytes() -> bytes:
    payload = _canonical_json_bytes(
        _launch_independent_loopback_contract_payload()
    )
    if (
        _canonical_json_bytes(client_preflight_server.loopback_contract_manifest())
        != payload
        or sha256(payload).hexdigest()
        != client_preflight_server.LOOPBACK_CONTRACT_SHA256
    ):
        _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    return payload


def _launch_recapture_server_contracts(
    value: LaunchPreflight,
    bundle_root: Path,
) -> None:
    try:
        if type(value) is not LaunchPreflight:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        _validate_launch_preflight_structure(value)
        root = _validator_absolute_path(bundle_root, output=True)
        layout = _launch_bundle_layout(root)
        advertised_bytes, advertised_identity = _validator_capture_plain_file(
            layout["advertised_tools"],
            max_bytes=_MAX_CAPTURE_BYTES,
        )
        loopback_bytes, loopback_identity = _validator_capture_plain_file(
            layout["loopback_contract"],
            max_bytes=_MAX_CAPTURE_BYTES,
        )
        if advertised_identity == loopback_identity:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        advertised = _launch_decode_canonical_object(advertised_bytes)
        loopback = _launch_decode_canonical_object(loopback_bytes)
        expected_advertised_bytes = _launch_advertised_tools_bytes()
        expected_loopback_bytes = _launch_loopback_contract_bytes()
        advertised_digest = sha256(expected_advertised_bytes).hexdigest()
        loopback_digest = sha256(expected_loopback_bytes).hexdigest()
        if (
            advertised_bytes != expected_advertised_bytes
            or loopback_bytes != expected_loopback_bytes
            or advertised != _launch_advertised_tools_payload()
            or loopback
            != client_preflight_server.loopback_contract_manifest()
            or advertised_digest
            != client_preflight_server.ADVERTISED_TOOLS_SHA256
            or advertised_digest != value.advertised_tools_sha256
            or advertised_digest != value.file_change.advertised_tools_sha256
            or loopback_digest
            != client_preflight_server.LOOPBACK_CONTRACT_SHA256
            or loopback_digest != value.loopback_contract_sha256
            or loopback.get("advertised_tools_sha256") != advertised_digest
            or loopback.get("tools") != advertised.get("tools")
            or loopback.get("model") != advertised.get("model")
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
    except RuntimeError as exc:
        if str(exc) in (
            VALIDATOR_BUNDLE_INVALID,
            LAUNCH_PREFLIGHT_BUNDLE_INVALID,
            COMMAND_LAUNCH_SPEC_MISMATCH,
        ):
            raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from None
        raise


def _launch_recapture_launch_contracts(
    value: LaunchPreflight,
    bundle_root: Path,
    executable_descriptors: tuple[_LaunchExecutableDescriptor, ...],
) -> int:
    try:
        if (
            type(value) is not LaunchPreflight
            or type(executable_descriptors) is not tuple
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        _validate_launch_preflight_structure(value)
        provisional_authority = _ValidatedLaunchPreflightAuthority(
            preflight_binding_sha256=_launch_preflight_binding_sha256(value),
            prelaunch_binding_sha256=_launch_prelaunch_binding_sha256(value),
            prelaunch_authority=_launch_detach_prelaunch_authority(
                _launch_get_durable_authority(value).prelaunch
            ),
            executable_descriptors=executable_descriptors,
            exact_config_sha256=value.exact_config_sha256,
            normalized_config_sha256=value.normalized_config_sha256,
            loopback_launch_sha256=value.loopback_launch_sha256,
            real_launch_template_sha256=value.real_launch_template_sha256,
        )
        _launch_validate_authority_projection(value, provisional_authority)
        root = _validator_absolute_path(bundle_root, output=True)
        layout = _launch_bundle_layout(root)
        codex_home = dict(value.launcher_environment).get("CODEX_HOME")
        if type(codex_home) is not str:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        case_root = ntpath.dirname(ntpath.dirname(codex_home))
        if case_root != str(root):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

        captured: dict[str, bytes] = {}
        identities: list[FilesystemObjectIdentity] = []
        for role in (
            "exact_config",
            "normalized_config",
            "loopback_launch_contract",
            "real_launch_template_contract",
        ):
            payload, identity = _validator_capture_plain_file(
                layout[role],
                max_bytes=_MAX_CAPTURE_BYTES,
            )
            captured[role] = payload
            identities.append(identity)
        if len(set(identities)) != len(identities):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)

        loopback_port = _launch_extract_loopback_port(
            captured["exact_config"]
        )
        local_config, _local_transport, _local_credential = (
            _launch_configuration(
                mode="loopback",
                loopback_port=loopback_port,
                shell_environment=value.shell_environment,
            )
        )
        real_config, real_transport, real_credential = _launch_configuration(
            mode="real",
            loopback_port=None,
            shell_environment=value.shell_environment,
        )
        exact_bytes = _launch_exact_config_bytes(local_config)
        normalized_bytes = _launch_normalized_config_bytes(
            case_root=case_root,
            loopback_port=loopback_port,
            config_overrides=local_config,
        )
        real_normalized_bytes = _launch_normalized_config_bytes(
            case_root=case_root,
            loopback_port=None,
            config_overrides=real_config,
        )
        if normalized_bytes != real_normalized_bytes:
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        workspace = ntpath.join(case_root, "workspace")
        output_schema_path = _launch_get_durable_authority(
            value
        ).prelaunch.output_schema.path
        real_final_message_path = ntpath.join(case_root, "raw", "final.md")
        real_argv = _launch_argv_tuple(
            codex_path=value.codex.executable_path,
            output_schema_path=output_schema_path,
            final_message_path=real_final_message_path,
            cwd=workspace,
            config_overrides=real_config,
        )
        loopback_bytes = _launch_loopback_aggregate_contract_bytes(
            preflight=value,
            executable_descriptors=executable_descriptors,
            loopback_port=loopback_port,
        )
        real_bytes = _launch_mode_contract_bytes(
            mode="real",
            case_root=case_root,
            loopback_port=None,
            argv=real_argv,
            config_overrides=real_config,
            output_schema_path=output_schema_path,
            final_message_path=real_final_message_path,
            cwd=workspace,
            launcher_environment=value.launcher_environment,
            shell_environment=value.shell_environment,
            credential_transport_version=real_transport,
            credential_environment_name=real_credential,
            executable_descriptors=executable_descriptors,
            preflight_binding_sha256=_launch_prelaunch_binding_sha256(
                value
            ),
        )
        expected_payloads = {
            "exact_config": exact_bytes,
            "normalized_config": normalized_bytes,
            "loopback_launch_contract": loopback_bytes,
            "real_launch_template_contract": real_bytes,
        }
        for role in (
            "normalized_config",
            "loopback_launch_contract",
            "real_launch_template_contract",
        ):
            decoded = _launch_decode_canonical_object(captured[role])
            if _canonical_json_bytes(decoded) != expected_payloads[role]:
                _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        expected_digests = tuple(
            sha256(expected_payloads[role]).hexdigest()
            for role in (
                "exact_config",
                "normalized_config",
                "loopback_launch_contract",
                "real_launch_template_contract",
            )
        )
        if (
            captured != expected_payloads
            or expected_digests
            != (
                value.exact_config_sha256,
                value.normalized_config_sha256,
                value.loopback_launch_sha256,
                value.real_launch_template_sha256,
            )
            or expected_digests
            != _launch_reference_expected_digests(
                preflight=value,
                executable_descriptors=executable_descriptors,
                loopback_port=loopback_port,
            )
        ):
            _reject(LAUNCH_PREFLIGHT_BUNDLE_INVALID)
        return loopback_port
    except RuntimeError as exc:
        if str(exc) in {
            CLIENT_LAUNCH_INPUT_INVALID,
            VALIDATOR_BUNDLE_INVALID,
            COMMAND_LAUNCH_SPEC_MISMATCH,
            LAUNCH_PREFLIGHT_BUNDLE_INVALID,
        }:
            raise RuntimeError(LAUNCH_PREFLIGHT_BUNDLE_INVALID) from None
        raise


def build_client_launch_spec(
    *,
    mode: Literal["loopback_probe", "real_campaign_template", "real_campaign"],
    preflight: LaunchPreflight | None,
    case_root: Path,
    evaluation: ClientEvaluationEnvelope,
    output_schema: CapturedLaunchInput,
    prompt: CapturedLaunchInput,
    loopback_port: int | None = None,
) -> ClientLaunchSpec:
    try:
        if mode not in {
            "loopback_probe",
            "real_campaign_template",
            "real_campaign",
        }:
            _launch_reject()
        frozen = _validate_launch_preflight(preflight)
        authority = _lookup_validated_launch_authority(frozen)
        if type(authority) is not _ValidatedLaunchPreflightAuthority:
            _launch_reject()
        if not isinstance(case_root, Path):
            _launch_reject()
        case_root_text = _launch_absolute_path(str(case_root))
        if type(evaluation) is not ClientEvaluationEnvelope:
            _launch_reject()
        evaluation.__post_init__()
        _launch_bind_evaluation(frozen, evaluation)
        if type(output_schema) is not CapturedLaunchInput or type(prompt) is not CapturedLaunchInput:
            _launch_reject()
        output_schema.__post_init__()
        prompt.__post_init__()
        if (
            _launch_absolute_path(output_schema.path) != output_schema.path
            or _launch_absolute_path(prompt.path) != prompt.path
            or not _launch_path_is_beneath(output_schema.path, case_root_text)
            or not _launch_path_is_beneath(prompt.path, case_root_text)
            or output_schema.path == prompt.path
            or output_schema.identity == prompt.identity
        ):
            _launch_reject()
        local = mode == "loopback_probe"
        if local:
            if (
                type(loopback_port) is not int
                or not 1 <= loopback_port <= 65_535
                or evaluation.purpose != "local_renderer_conformance"
            ):
                _launch_reject()
            credential_transport_version = _CLIENT_NO_CREDENTIAL_TRANSPORT
            credential_environment_name = None
            prompt_index = {
                ("shell_renderer", 1): 0,
                ("shell_renderer", 2): 0,
                ("file_add", 3): 1,
                ("file_update", 4): 2,
            }.get((evaluation.probe_role, evaluation.probe_ordinal))
            prelaunch = authority.prelaunch_authority
            authority_case_root = ntpath.dirname(
                ntpath.dirname(prelaunch.output_schema.path)
            )
            if (
                prompt_index is None
                or case_root_text != authority_case_root
                or prompt != prelaunch.prompts[prompt_index]
                or output_schema != prelaunch.output_schema
            ):
                _launch_reject()
        else:
            if (
                loopback_port is not None
                or evaluation.purpose != "approved_campaign"
                or (mode == "real_campaign_template") != evaluation.is_template
                or (mode == "real_campaign") != evaluation.credential_present
            ):
                _launch_reject()
            credential_transport_version = _CLIENT_PROVIDER_CREDENTIAL_TRANSPORT
            credential_environment_name = _CLIENT_CREDENTIAL_ENVIRONMENT_NAME
        codex_directory = ntpath.dirname(frozen.codex.executable_path)
        shell_directory = ntpath.dirname(frozen.shell.path)
        python_directory = ntpath.dirname(frozen.python_path)
        rg_directory = ntpath.dirname(frozen.rg_path)
        system_root = ntpath.dirname(ntpath.dirname(frozen.comspec_path))
        system32 = ntpath.join(system_root, "System32")
        if ntpath.normcase(ntpath.join(system32, "cmd.exe")) != ntpath.normcase(
            frozen.comspec_path
        ):
            _launch_reject()
        workspace = ntpath.join(case_root_text, "workspace")
        cwd, final_message = _launch_owned_probe_paths(
            case_root=case_root_text,
            evaluation=evaluation,
        )
        if os.path.lexists(final_message):
            _launch_reject()
        launcher_root = ntpath.join(case_root_text, "launcher")
        launcher_profile = ntpath.join(launcher_root, "profile")
        workspace_tools = ntpath.join(workspace, ".tools")
        launcher_path = ";".join(
            _launch_ordered_unique_paths(
                (
                    codex_directory,
                    shell_directory,
                    workspace_tools,
                    python_directory,
                    rg_directory,
                    system32,
                    system_root,
                )
            )
        )
        shell_path = ";".join(
            _launch_ordered_unique_paths(
                (
                    workspace_tools,
                    python_directory,
                    rg_directory,
                    shell_directory,
                    system32,
                    system_root,
                )
            )
        )
        launcher_environment = _launch_environment_tuple(
            {
                "APPDATA": ntpath.join(launcher_profile, "AppData", "Roaming"),
                "CODEX_HOME": ntpath.join(launcher_root, "codex-home"),
                "COMSPEC": frozen.comspec_path,
                "HOME": launcher_profile,
                "LOCALAPPDATA": ntpath.join(
                    launcher_profile,
                    "AppData",
                    "Local",
                ),
                "NO_COLOR": "1",
                "PATH": launcher_path,
                "PATHEXT": ".COM;.EXE;.BAT;.CMD",
                "POWERSHELL_TELEMETRY_OPTOUT": "1",
                "POWERSHELL_UPDATECHECK": "Off",
                "PYTHONDONTWRITEBYTECODE": "1",
                "PYTHONUTF8": "1",
                "SYSTEMROOT": system_root,
                "TEMP": ntpath.join(launcher_root, "tmp"),
                "TMP": ntpath.join(launcher_root, "tmp"),
                "USERPROFILE": launcher_profile,
                "WINDIR": system_root,
            }
        )
        workspace_tmp = ntpath.join(workspace, "tmp")
        shell_environment = _launch_environment_tuple(
            {
                "COMSPEC": frozen.comspec_path,
                "KOKOROARC_DATA_DIR": ntpath.join(workspace, "data"),
                "PATH": shell_path,
                "PATHEXT": ".COM;.EXE;.BAT;.CMD",
                "PIP_CACHE_DIR": ntpath.join(workspace_tmp, "pip-cache"),
                "PIP_CONFIG_FILE": "NUL",
                "PIP_DISABLE_PIP_VERSION_CHECK": "1",
                "PIP_NO_INDEX": "1",
                "POWERSHELL_TELEMETRY_OPTOUT": "1",
                "POWERSHELL_UPDATECHECK": "Off",
                "PYTHONDONTWRITEBYTECODE": "1",
                "PYTHONHASHSEED": "0",
                "PYTHONNOUSERSITE": "1",
                "PYTHONPATH": ntpath.join(case_root_text, "runtime"),
                "PYTHONSAFEPATH": "1",
                "PYTHONUTF8": "1",
                "RIPGREP_CONFIG_PATH": "NUL",
                "SYSTEMROOT": system_root,
                "TEMP": workspace_tmp,
                "TMP": workspace_tmp,
                "WINDIR": system_root,
            }
        )
        (
            config_overrides,
            configured_transport,
            configured_environment_name,
        ) = _launch_configuration(
            mode="loopback" if local else "real",
            loopback_port=loopback_port,
            shell_environment=shell_environment,
        )
        if (
            configured_transport != credential_transport_version
            or configured_environment_name != credential_environment_name
        ):
            _launch_reject()
        config_bytes = ("\n".join(config_overrides) + "\n").encode("utf-8")
        argv = _launch_argv_tuple(
            codex_path=frozen.codex.executable_path,
            output_schema_path=output_schema.path,
            final_message_path=final_message,
            cwd=cwd,
            config_overrides=config_overrides,
        )
        try:
            vector = command_plan._windows_native_vector(argv[0], argv[1:])
        except RuntimeError as exc:
            if str(exc) in {
                command_plan.COMMAND_DECODER_IDENTITY_MISMATCH,
                command_plan.COMMAND_DECODER_LIMIT_EXCEEDED,
            }:
                _launch_reject(exc)
            raise
        executable_identities = _launch_authority_executable_identities(
            authority
        )
        config_sha256 = sha256(config_bytes).hexdigest()
        normalized_config_sha256 = _launch_normalized_config_sha256(
            case_root=case_root_text,
            loopback_port=loopback_port,
            config_overrides=config_overrides,
        )
        mode_contract_bytes = _launch_mode_contract_bytes(
            mode="loopback" if local else "real",
            case_root=case_root_text,
            loopback_port=loopback_port,
            argv=argv,
            config_overrides=config_overrides,
            output_schema_path=output_schema.path,
            final_message_path=final_message,
            cwd=cwd,
            launcher_environment=launcher_environment,
            shell_environment=shell_environment,
            credential_transport_version=credential_transport_version,
            credential_environment_name=credential_environment_name,
            executable_descriptors=authority.executable_descriptors,
            preflight_binding_sha256=authority.prelaunch_binding_sha256,
        )
        if local:
            mode_contract_sha256 = sha256(
                _launch_loopback_role_mode_contract_bytes(
                    probe_role=evaluation.probe_role,
                    probe_ordinal=evaluation.probe_ordinal,
                    case_root=case_root_text,
                    loopback_port=loopback_port,
                    cwd=cwd,
                    final_message_path=final_message,
                    base_mode_contract_bytes=mode_contract_bytes,
                )
            ).hexdigest()
            retained_launch_contract_bytes = (
                _launch_loopback_aggregate_contract_bytes(
                    preflight=frozen,
                    executable_descriptors=authority.executable_descriptors,
                    loopback_port=loopback_port,
                )
            )
            launch_member_key: tuple[str, int] | None = (
                evaluation.probe_role,
                evaluation.probe_ordinal,
            )
            launch_contract_sha256 = (
                _launch_loopback_aggregate_member_sha256(
                    retained_launch_contract_bytes,
                    probe_role=evaluation.probe_role,
                    probe_ordinal=evaluation.probe_ordinal,
                    expected_base_mode_contract_bytes=mode_contract_bytes,
                )
            )
            if mode_contract_sha256 != (
                _launch_loopback_aggregate_mode_sha256(
                    retained_launch_contract_bytes,
                    probe_role=evaluation.probe_role,
                    probe_ordinal=evaluation.probe_ordinal,
                    expected_base_mode_contract_bytes=mode_contract_bytes,
                )
            ):
                _launch_reject()
        else:
            mode_contract_sha256 = sha256(mode_contract_bytes).hexdigest()
            retained_launch_contract_bytes = mode_contract_bytes
            launch_member_key = None
            launch_contract_sha256 = mode_contract_sha256
        normalized_sha256 = _launch_normalized_sha256(
            case_root=case_root_text,
            loopback_port=loopback_port,
            argv=argv,
            config_overrides=config_overrides,
            evaluation=evaluation,
            prompt=prompt,
            output_schema=output_schema,
            launcher_environment=launcher_environment,
            shell_environment=shell_environment,
            credential_transport_version=credential_transport_version,
            credential_environment_name=credential_environment_name,
            executable_descriptors=authority.executable_descriptors,
            preflight_authority_sha256=(
                _launch_validated_authority_sha256(authority)
            ),
        )
        construction_authority = _ClientLaunchConstructionAuthority(
            preflight_authority=authority,
            mode="loopback" if local else "real",
            config_sha256=config_sha256,
            normalized_config_sha256=normalized_config_sha256,
            launch_contract_sha256=launch_contract_sha256,
            retained_launch_contract_bytes=retained_launch_contract_bytes,
            expected_base_mode_contract_bytes=mode_contract_bytes,
            launch_member_key=launch_member_key,
            normalized_sha256=normalized_sha256,
        )
        return _launch_construct_client_spec(
            preflight=frozen,
            preflight_authority=authority,
            authority=construction_authority,
            version=_CLIENT_LAUNCH_SPEC_VERSION,
            argv=argv,
            native_vector_contract=vector.contract,
            native_vector_utf16_units=vector.utf16_units,
            native_vector_utf16le_sha256=vector.utf16le_sha256,
            cwd=cwd,
            config_overrides=config_overrides,
            config_bytes=config_bytes,
            config_sha256=config_sha256,
            evaluation=evaluation,
            prompt=prompt,
            output_schema=output_schema,
            launcher_environment=launcher_environment,
            shell_environment=shell_environment,
            credential_transport_version=credential_transport_version,
            credential_environment_name=credential_environment_name,
            client_process_limit_role=evaluation.client_process_limit_role,
            client_process_limit_table_sha256=(
                evaluation.client_process_limit_table_sha256
            ),
            client_constructor_class=evaluation.client_constructor_class,
            client_constructor_implementation_id=(
                evaluation.client_constructor_implementation_id
            ),
            client_constructor_implementation_sha256=(
                evaluation.client_constructor_implementation_sha256
            ),
            client_constructor_implementation_set_sha256=(
                evaluation.client_constructor_implementation_set_sha256
            ),
            client_constructor_attribute_set_sha256=(
                evaluation.client_constructor_attribute_set_sha256
            ),
            client_job_topology_sha256=evaluation.client_job_topology_sha256,
            executable_identities=executable_identities,
            normalized_sha256=normalized_sha256,
        )
    except RuntimeError as exc:
        if str(exc) == COMMAND_LAUNCH_SPEC_MISMATCH:
            raise
        if str(exc) in {
            CLIENT_LAUNCH_INPUT_INVALID,
            VALIDATOR_BUNDLE_INVALID,
            LAUNCH_PREFLIGHT_BUNDLE_INVALID,
        }:
            _launch_reject(exc)
        raise
